window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s5-264","number":264,"surah":5,"verses":[45],"verseLabel":"المائدة: 45","question":"ما دلالة مجيء الخبر مفردًا في قوله تعالى: ﴿والجروح قصاص﴾؟","answer":"﴿قصاص﴾ مصدر، والمصدر يستوي فيه المفرد والجمع؛ فالمعنى أن كل جرح مما يمكن استيفاء مثله تجري فيه المماثلة، وجمع ﴿الجروح﴾ يستوعب أنواعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص223–236.","url":""}]},{"id":"s5-265","number":265,"surah":5,"verses":[45],"verseLabel":"المائدة: 45","question":"ما دلالة تسمية العفو عن القصاص ﴿صدقة﴾؟","answer":"لأن صاحب الحق يتجافى عن حق ثابت له ابتغاء وجه الله، فشابه بذل المال تطوعًا؛ وتسميته صدقة ترغّب في العفو وتدل على صدق إيمان صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص223–236.","url":""}]},{"id":"s5-266","number":266,"surah":5,"verses":[45],"verseLabel":"المائدة: 45","question":"إلى من يعود الضمير في قوله تعالى: ﴿فهو كفارة له﴾؟","answer":"الأظهر أن الضمير يعود إلى المتصدق صاحب الحق؛ فعفوه كفارة لذنوبه. وقيل: يعود إلى الجاني، فيكون عفو المجني عليه كفارة عنه بقدر الجناية. واحتمال الضمير للوجهين هو سبب اختلاف المفسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص223–236.","url":""}]},{"id":"s5-267","number":267,"surah":5,"verses":[44,45],"verseLabel":"المائدة: 44–45","question":"ما الفرق بين ختم آية الحكم بقوله تعالى: ﴿الكافرون﴾ وختم آية القصاص بقوله: ﴿الظالمون﴾؟","answer":"ناسب الكفر مقام رد حكم الله وستره، وناسب الظلم مقام مجاوزة العدل في الدماء والقصاص وترك إعطاء كل ذي حق حقه. والأوصاف تتداخل، لكن كل خاتمة أبرزت الجهة الغالبة في سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص223–236.","url":""}]},{"id":"s5-268","number":268,"surah":5,"verses":[46],"verseLabel":"المائدة: 46","question":"ما الصورة في قوله تعالى: ﴿وقفينا على آثارهم بعيسى ابن مريم﴾؟","answer":"التقفية جعل الشيء في قفا الشيء، أي إتباعه إياه؛ فصورت الآية عيسى عليه السلام آتيًا على آثار الأنبياء قبله، متبعًا طريقهم ومصدقًا للتوراة، في سلسلة متصلة من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص237–246.","url":""}]},{"id":"s5-269","number":269,"surah":5,"verses":[46],"verseLabel":"المائدة: 46","question":"ما دلالة ذكر عيسى عليه السلام باسمه منسوبًا إلى أمه؟","answer":"نسبته إلى مريم تثبت نسبه البشري المعروف مع ولادته من غير أب، وتكرّم أمه الصديقة، وتدفع ما أُلصق به من دعوى البنوة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص237–246.","url":""}]},{"id":"s5-270","number":270,"surah":5,"verses":[46],"verseLabel":"المائدة: 46","question":"ما دلالة وصف الإنجيل بأنه ﴿هدى ونور﴾ ثم زيادة ﴿وموعظة للمتقين﴾؟","answer":"هو ﴿هدى﴾ يرشد إلى الحق و﴿نور﴾ يكشفه، ثم خُص أثره الوعظي بالمتقين لأنهم الذين تقبل قلوبهم الموعظة وتنتفع بها؛ فالوصفان لذات الكتاب، والموعظة لأثره في أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص237–246.","url":""}]},{"id":"s5-271","number":271,"surah":5,"verses":[46],"verseLabel":"المائدة: 46","question":"ما دلالة قوله تعالى عن عيسى عليه السلام: ﴿مصدقًا لما بين يديه من التوراة﴾؟","answer":"أي مؤيدًا للتوراة السابقة عليه وشاهدًا بصدق أصلها، عاملًا بما لم ينسخ من أحكامها؛ فدعوة عيسى امتداد لأصل الوحي وليست نقضًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص237–246.","url":""}]},{"id":"s5-272","number":272,"surah":5,"verses":[27],"verseLabel":"المائدة: 46؛ الحديد: 27","question":"ما سرّ ذكر ﴿برسلنا﴾ قبل عيسى عليه السلام في سورة الحديد، وعدم ذكره في الموضع المقابل من سورة المائدة؟","answer":"سياق الحديد يستعرض تتابع الرسل في تاريخ الأمم، فناسب قوله: ﴿ثم قفينا على آثارهم برسلنا وقفينا بعيسى ابن مريم﴾. أما المائدة فقد سبقت بذكر النبيين الذين حكموا بالتوراة ثم انتقلت مباشرة إلى عيسى، فكان ذكر ﴿برسلنا﴾ معلومًا من السياق ولا حاجة إلى إعادته.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج60، ص337–343.","url":""}]},{"id":"s5-273","number":273,"surah":5,"verses":[46,48],"verseLabel":"المائدة: 46، 48","question":"ما سرّ تكرار ﴿مصدقًا لما بين يديه﴾ في وصف عيسى عليه السلام والقرآن، ثم اختلاف ما بعده؟","answer":"وصف عيسى بالتصديق لما بين يديه من التوراة لبيان اتصال رسالته بها، ووصف القرآن بالتصديق لما بين يديه من جنس الكتاب كله لأنه جاء بعد الرسالات جامعًا لها. ثم زيد في القرآن ﴿ومهيمنًا عليه﴾ لأنه المرجع الحافظ الشاهد الذي يبين ما صح وما دخله التحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص235–286، في موضعي المائدة: 46 و48.","url":""}]},{"id":"s5-274","number":274,"surah":5,"verses":[47],"verseLabel":"المائدة: 47","question":"ما دلالة صيغة الأمر في قوله تعالى: ﴿وليحكم أهل الإنجيل بما أنزل الله فيه﴾؟","answer":"اللام للأمر، فتجعل ما في الإنجيل المنزل حاكمًا على أهله، لا مجرد خبر عن حكم وقع في الماضي. وهي تلزمهم باتباع وحي الله الصحيح الذي يقودهم إلى تصديق الرسول الخاتم، لا ما بدلته الأهواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص247–257.","url":""}]},{"id":"s5-275","number":275,"surah":5,"verses":[44,45,46,47],"verseLabel":"المائدة: 44–47","question":"ما مناسبة ختم الآية الثالثة في سياق الحكم بقوله تعالى: ﴿فأولئك هم الفاسقون﴾ بعد ﴿الكافرون﴾ و﴿الظالمون﴾؟","answer":"الكفر يبرز ستر حكم الله أو جحوده، والظلم يبرز مجاوزة العدل والحقوق، والفسق يبرز الخروج عن طاعة الله وعدم الانقياد لما أنزل؛ فجاء كل وصف ملائمًا للجهة التي أبرزها سياقه، مع إمكان اجتماع الأوصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص247–257.","url":""}]},{"id":"s5-276","number":276,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما دلالة وصف القرآن بأنه ﴿مصدقًا لما بين يديه من الكتاب ومهيمنًا عليه﴾؟","answer":"القرآن يصدق أصول الوحي السابق، وهو مهيمن عليه: شاهد له، وأمين حافظ، ومرجع يكشف ما بقي صحيحًا وما وقع فيه من تبديل، ويحكم بما جعله الله الشريعة الخاتمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-277","number":277,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما دلالة إفراد ﴿الكتاب﴾ في قوله تعالى: ﴿لما بين يديه من الكتاب﴾ مع تعدد الكتب السابقة؟","answer":"﴿الكتاب﴾ اسم جنس يشمل ما أنزله الله من الكتب، ويشير إفراده إلى وحدة أصل الوحي ومصدره وإن تعددت صحفه وشرائعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-278","number":278,"surah":5,"verses":[42,48],"verseLabel":"المائدة: 42، 48","question":"ما وجه الأمر بقوله تعالى: ﴿فاحكم بينهم بما أنزل الله﴾ بعد التخيير في الآية 42 بين الحكم والإعراض؟","answer":"التخيير السابق في أصل قبول التحاكم من غير المسلمين، فإن اختار النبي ﷺ الحكم لزمه القسط. وهنا جاء الأمر بأن يكون الحكم نفسه بما أنزل الله بعد تقرير هيمنة القرآن، وقيل إن الأمر اللاحق نسخ التخيير؛ وعلى الوجهين لا إذن قط في الحكم بالهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-279","number":279,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما دلالة جمع ﴿أهواءهم﴾ في مقابل إفراد الحق المنزل؟","answer":"الأهواء متعددة متفرقة بتعدد الشهوات وأصحابها، أما الحق فواحد متسق صادر من الله؛ فجمع الباطل المتشعب وأفرد الطريق المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-280","number":280,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما الفرق بين ﴿شرعة﴾ و﴿منهاجًا﴾ في قوله تعالى: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾؟","answer":"الشرعة أصلها مورد الماء الظاهر، واستعيرت للأحكام التي شرعها الله؛ والمنهاج الطريق الواضح المستمر. واجتماعهما يفيد ما شُرع من أحكام وما رسم من طريق بيّن للسير عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-281","number":281,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما الحكمة التي تبينها الآية في عدم جعل الناس أمة واحدة؟","answer":"صرحت الآية بأن الله لو شاء لجعلهم أمة واحدة، لكنه نوّع شرائعهم في الفروع بحسب حكمته وأحوالهم ليختبر استجابتهم لما آتاهم، مع وحدة أصل التوحيد؛ فالاختلاف المقصود ميدان ابتلاء لا حجة لاتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-282","number":282,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما دلالة قوله تعالى في اختلاف الشرائع: ﴿ليبلوكم في ما آتاكم﴾؟","answer":"أي ليختبركم في داخل ما أعطاكم من كتاب وشريعة ونعم: هل تطيعون حكمه في مرحلتكم وتستجيبون لما يجدده من وحي، أم تجعلون ما أوتيتموه ذريعة للتعصب والمخالفة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-283","number":283,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما دلالة قوله تعالى: ﴿فاستبقوا الخيرات﴾ دون: افعلوا الخيرات؟","answer":"الاستباق يزيد على مجرد الفعل معنى المبادرة والتنافس وطلب السبق؛ فوجه اختلاف الشرائع إلى ميدان الطاعة والعمل، لا إلى الخصومة العقيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-284","number":284,"surah":5,"verses":[48],"verseLabel":"المائدة: 48","question":"ما دلالة تقديم ﴿إلى الله﴾ في قوله تعالى: ﴿إلى الله مرجعكم جميعًا﴾؟","answer":"التقديم يفيد قصر المرجع النهائي على الله، و﴿جميعًا﴾ تسوي بين المختلفين في الوقوف بين يديه؛ ثم يبين هو حقيقة ما اختلفوا فيه، فلا يملك فريق أن يجعل هواه الحكم الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص258–277.","url":""}]},{"id":"s5-285","number":285,"surah":5,"verses":[48,49],"verseLabel":"المائدة: 48–49","question":"ما مناسبة تكرار الأمر بالحكم بما أنزل الله في الآيتين 48 و49؟","answer":"الأمر الأول مترتب على إنزال القرآن مصدقًا ومهيمنًا، فيقرر مصدر الحكم؛ وأعيد الأمر لتوكيده ثم عطف عليه التحذير من فتنتهم عن بعض الوحي، فلكل موضع غرضه في إحكام القضية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص278–286.","url":""}]},{"id":"s5-286","number":286,"surah":5,"verses":[49],"verseLabel":"المائدة: 49","question":"ما دلالة قوله تعالى: ﴿واحذرهم أن يفتنوك عن بعض ما أنزل الله إليك﴾ وذكر ﴿بعض﴾؟","answer":"يحذر من أدنى تنازل عن الوحي؛ لأن صرف الحكم عن بعض ما أنزل الله فتنة ولو بقي أكثره معمولًا به، ولأنهم كانوا يحاولون استمالته في أحكام معينة توافق أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص278–286.","url":""}]},{"id":"s5-287","number":287,"surah":5,"verses":[49],"verseLabel":"المائدة: 49","question":"ما دلالة قوله تعالى: ﴿فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم﴾؟","answer":"إذا أعرضوا بعد قيام الحجة فإعراضهم سبب لعقوبة عاجلة تصيبهم ببعض ما كسبوا، أما تمام جزاء ذنوبهم ففي الآخرة. وذكر ﴿بعض﴾ يهوّل الأمر: فإذا كان بعض الذنوب كافيًا لهذه الإصابة فكيف بمجموعها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص278–286.","url":""}]},{"id":"s5-288","number":288,"surah":5,"verses":[49],"verseLabel":"المائدة: 49","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وإن كثيرًا من الناس لفاسقون﴾؟","answer":"الخاتمة تقرر أن الإعراض عن حكم الله ليس حادثة نادرة، بل يقع من كثير من الناس خروجًا عن طاعته؛ وأكدت الجملة بـ﴿إن﴾ واللام تثبيتًا لهذه الحقيقة مع تجنب تعميمها على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص278–286.","url":""}]},{"id":"s5-289","number":289,"surah":5,"verses":[50],"verseLabel":"المائدة: 50","question":"ما دلالة تسمية ما يطلبونه ﴿حكم الجاهلية﴾؟","answer":"كل حكم يُطلب اتباعًا للهوى والعصبية على خلاف وحي الله يلحق بحكم الجاهلية؛ فالجاهلية هنا وصف لمنهج الحكم الذي يجهل الحق أو يتجاهله، لا مجرد اسم لزمن مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص287–293.","url":""}]},{"id":"s5-290","number":290,"surah":5,"verses":[50],"verseLabel":"المائدة: 50","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أفحكم الجاهلية يبغون﴾؟","answer":"الاستفهام للإنكار والتوبيخ والتعجيب من إعراضهم عن حكم الله الكامل وطلبهم حكمًا تصنعه الأهواء، وتقديم ﴿حكم الجاهلية﴾ يبرز فداحة المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص287–293.","url":""}]},{"id":"s5-291","number":291,"surah":5,"verses":[50],"verseLabel":"المائدة: 50","question":"ما دلالة قوله تعالى: ﴿ومن أحسن من الله حكمًا لقوم يوقنون﴾ وذكر الموقنين؟","answer":"الاستفهام ينفي أن يكون حكم أحسن من حكم الله، وخص الموقنين لأن يقينهم بكمال علمه وعدله وحكمته يجعلهم يدركون هذا الحسن ويذعنون له، بخلاف من تحجبه الأهواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص287–293.","url":""}]},{"id":"s5-292","number":292,"surah":5,"verses":[51],"verseLabel":"المائدة: 51","question":"ما دلالة النهي عن اتخاذ اليهود والنصارى ﴿أولياء﴾؟","answer":"الولاية أوسع من الصداقة العابرة؛ فهي ولاء ونصرة واعتماد يمنح صاحبه سلطةً وانحيازًا على حساب جماعة المؤمنين ودينهم. لذلك لا تتناول الآية مجرد البر والعدل وحسن المعاملة المأذون بها، وإنما ولاية النصرة والانتماء التي يحددها السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص294–300.","url":""}]},{"id":"s5-293","number":293,"surah":5,"verses":[51],"verseLabel":"المائدة: 51","question":"ما دلالة قوله تعالى: ﴿بعضهم أولياء بعض﴾؟","answer":"يبين أنهم، على ما بينهم من اختلاف، يتناصر بعضهم مع بعض حين تجمعهم المصلحة والموقف من المؤمنين؛ وفيه تحذير من طلب الحماية بولاية تخرج المؤمن من صف جماعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص294–300.","url":""}]},{"id":"s5-294","number":294,"surah":5,"verses":[51],"verseLabel":"المائدة: 51","question":"ما دلالة التوكيد في قوله تعالى: ﴿ومن يتولهم منكم فإنه منهم﴾؟","answer":"الفاء و﴿إن﴾ تؤكدان نتيجة الولاية: من ينضم إليهم في ولاء النصرة والانحياز على المؤمنين يلتحق بصفهم في هذا الباب ويأخذ حكمه؛ وليس المراد كل معاملة أو بر أو قسط.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص294–300.","url":""}]},{"id":"s5-295","number":295,"surah":5,"verses":[51],"verseLabel":"المائدة: 51","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الظالمين﴾؟","answer":"اتخاذ ولاية تضر المؤمنين وتناصر عليهم وضع للولاء في غير موضعه، فهو ظلم؛ ومن يصر على هذا الظلم يُحرم هداية التوفيق إلى الطريق المستقيم، فجاءت الخاتمة تعليلًا للتحذير السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص294–300.","url":""}]},{"id":"s5-296","number":296,"surah":5,"verses":[52],"verseLabel":"المائدة: 52","question":"ما دلالة قوله تعالى: ﴿فترى الذين في قلوبهم مرض يسارعون فيهم﴾؟","answer":"مرض القلب هو النفاق وضعف اليقين، ولذلك تراهم يبادرون إلى التوغل في ولاية أولئك والاحتماء بهم. و﴿فيهم﴾ تصورهم داخلين في جماعتهم وعلاقاتهم، لا مجرد متجهين إليها من بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص301–308.","url":""}]},{"id":"s5-297","number":297,"surah":5,"verses":[52],"verseLabel":"المائدة: 52","question":"ما دلالة قولهم: ﴿نخشى أن تصيبنا دائرة﴾؟","answer":"الدائرة ما تدور به الأيام من تحول الغلبة والرخاء إلى ضدّهما؛ فاتخذ المنافقون خوفهم من انقلاب الأحوال ذريعة لموالاة الفريق الذي ظنوا أن القوة قد تصير إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص301–308.","url":""}]},{"id":"s5-298","number":298,"surah":5,"verses":[52],"verseLabel":"المائدة: 52","question":"ما دلالة قوله تعالى: ﴿فعسى الله أن يأتي بالفتح أو أمر من عنده﴾؟","answer":"﴿عسى﴾ من الله وعد محقق، والفتح ما يظهر به أمر المؤمنين ويقهر عدوهم، أما ﴿أمر من عنده﴾ فأعم من الفتح؛ ككشف المنافقين أو إبطال تدبيرهم من غير قتال. فترك التعبير صورة النصر مفتوحة لما يأتي به الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص301–308.","url":""}]},{"id":"s5-299","number":299,"surah":5,"verses":[52],"verseLabel":"المائدة: 52","question":"ما دلالة قوله تعالى: ﴿فيصبحوا على ما أسروا في أنفسهم نادمين﴾؟","answer":"الفاء تصور سرعة انقلاب حالهم عند مجيء الفتح، و﴿يصبحوا﴾ تدل على ظهور ندمهم بعد خفائه، و﴿ما أسروا في أنفسهم﴾ يكشف أن موالاتهم كانت مبنية على خوف مكتوم وسوء ظن بالله؛ فيصير السر ندامة ظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص301–308.","url":""}]},{"id":"s5-300","number":300,"surah":5,"verses":[53],"verseLabel":"المائدة: 53","question":"ما دلالة تعجب المؤمنين بقولهم: ﴿أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم﴾؟","answer":"الاستفهام للتعجب من افتضاح قوم بالغوا في توكيد أنهم مع المؤمنين، ثم كشف الفتح كذبهم. واسم الإشارة يستحضرهم بعد سقوط سترهم كأن المؤمنين لا يكادون يصدقون أنهم أصحاب تلك الأيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص309–314.","url":""}]},{"id":"s5-301","number":301,"surah":5,"verses":[53],"verseLabel":"المائدة: 53","question":"ما دلالة قوله تعالى: ﴿جهد أيمانهم﴾؟","answer":"أي أقصى ما يستطيعونه من توكيد الحلف؛ فالإضافة تبين أنهم استفرغوا طاقتهم في تثبيت دعوى النصرة، وبذلك يشتد التناقض بين ظاهر أيمانهم وحقيقة ولائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص309–314.","url":""}]},{"id":"s5-302","number":302,"surah":5,"verses":[53],"verseLabel":"المائدة: 53","question":"ما مناسبة قوله تعالى بعد أيمانهم: ﴿حبطت أعمالهم فأصبحوا خاسرين﴾؟","answer":"لما كشف الفتح نفاقهم بطلت أعمالهم التي أظهروها من غير إيمان صحيح، فكانت النتيجة خسارة ما ظنوا أنه يحفظ مصالحهم في الفريقين. والفاء تربط الخسارة مباشرة بحبوط العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص309–314.","url":""}]},{"id":"s5-303","number":303,"surah":5,"verses":[54],"verseLabel":"المائدة: 54","question":"ما دلالة قوله تعالى: ﴿من يرتد منكم عن دينه فسوف يأتي الله بقوم﴾؟","answer":"الشرط يقرر أن ارتداد أحد لا يضر دين الله؛ فسنة الاستبدال تأتي بقوم يقومون بحقه. و﴿سوف﴾ تحقق الوعد مع فسحة زمنه، لا أنها تدل على استبدال لحظي بكل فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص315–324.","url":""}]},{"id":"s5-304","number":304,"surah":5,"verses":[54],"verseLabel":"المائدة: 54","question":"ما سرّ ابتداء صفات القوم بقوله تعالى: ﴿يحبهم ويحبونه﴾؟","answer":"لأن محبة الله لهم ومحبتهم له أصل الصفات الآتية ودافعها؛ فمنها يفيض تواضعهم للمؤمنين وعزتهم على الكافرين وجهادهم وثباتهم أمام اللوم. وتقديم محبته لهم يشعر بأن فضله سابق على محبتهم وطاعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص315–324.","url":""}]},{"id":"s5-305","number":305,"surah":5,"verses":[54],"verseLabel":"المائدة: 54","question":"ما دلالة المقابلة في قوله تعالى: ﴿أذلة على المؤمنين أعزة على الكافرين﴾؟","answer":"الذلة هنا لين الجانب والتواضع والرحمة للمؤمنين، والعزة قوة النفس والامتناع عن الخضوع للكافرين؛ فجمعت المقابلة رحمة الداخل وثبات الموقف تجاه المعتدي، وليست الذلة مهانة ولا العزة ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص315–324.","url":""}]},{"id":"s5-306","number":306,"surah":5,"verses":[54],"verseLabel":"المائدة: 54","question":"ما مناسبة ذكر الجهاد قبل قوله تعالى: ﴿ولا يخافون لومة لائم﴾؟","answer":"لأن الجهاد عمل ظاهر عظيم التبعة قد يستجلب لوم المثبطين، فجاء عدم خوف اللوم وصفًا للثبات عليه وعلى سائر الحق؛ فالترتيب من بذل الجهد إلى مقاومة الضغط الذي يحاول إيقافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص315–324.","url":""}]},{"id":"s5-307","number":307,"surah":5,"verses":[54],"verseLabel":"المائدة: 54","question":"ما مناسبة ختم الصفات بقوله تعالى: ﴿ذلك فضل الله يؤتيه من يشاء﴾؟","answer":"أعاد ما تقدم من المحبة والرحمة والعزة والجهاد إلى فضل الله، حتى لا يعجب أصحابها بأنفسهم، وقرر أن الله يمنح هذا الفضل من يشاء بحكمته؛ فالصفات توفيق ومنحة مع كونها أعمالًا يُكلّف بها العبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص315–324.","url":""}]},{"id":"s5-308","number":308,"surah":5,"verses":[55],"verseLabel":"المائدة: 55","question":"ما دلالة القصر في قوله تعالى: ﴿إنما وليكم الله ورسوله والذين آمنوا﴾؟","answer":"بعد النهي عن ولاية من يعادون جماعة المؤمنين، حصر السياق ولاية النصرة والانتماء في الله ورسوله والمؤمنين؛ فحدد مركز ولاء الجماعة الذي تستمد منه هويتها وقوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص325–328.","url":""}]},{"id":"s5-309","number":309,"surah":5,"verses":[55],"verseLabel":"المائدة: 55","question":"ما سرّ إفراد ﴿وليكم﴾ مع تعدد المذكورين بعده؟","answer":"أفرد ﴿ولي﴾ لأن ولاية الله ورسوله والمؤمنين ولاية واحدة متآزرة في مقصدها، ولأن اسم الجنس المفرد يصلح أن يخبر به عن متعدد؛ فليس المراد ولايات متعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص325–328.","url":""}]},{"id":"s5-310","number":310,"surah":5,"verses":[55],"verseLabel":"المائدة: 55","question":"ما دلالة وصف المؤمنين بقوله تعالى: ﴿يؤتون الزكاة وهم راكعون﴾؟","answer":"الجملة حالية، فتصفهم بإيتاء الزكاة مع الركوع؛ والركوع يُحمل على الصلاة أو على الخضوع لله، فيجتمع في وصفهم بذل المال وعبادة البدن ودوام الطاعة. وقيل نزلت في واقعة صدقة حال الركوع، غير أن صيغة الجمع تبقي الحكم عامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص325–328.","url":""}]},{"id":"s5-311","number":311,"surah":5,"verses":[56],"verseLabel":"المائدة: 56","question":"ما دلالة قوله تعالى: ﴿ومن يتول الله ورسوله والذين آمنوا فإن حزب الله هم الغالبون﴾؟","answer":"جعل المتولي لله ورسوله والمؤمنين من حزب الله، ثم رتب على ذلك وعد الغلبة؛ فالفاء تصل الولاية بنتيجتها، والحزب جماعة يجمعها مقصد ونصرة، وغلبتها ثمرة انتسابها إلى الله وثباتها على أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص329–331.","url":""}]},{"id":"s5-312","number":312,"surah":5,"verses":[56],"verseLabel":"المائدة: 56","question":"ما سرّ إظهار اسم الله في قوله تعالى: ﴿حزب الله﴾ بدل الإضمار؟","answer":"الإظهار في موضع الإضمار يشرف الحزب بإضافته إلى الله، ويصرح بأن علة غلبته هذا الانتساب والنصرة لدينه، كما يجعل الاسم الجليل محور الجملة لا مجرد مرجع ضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص329–331.","url":""}]},{"id":"s5-313","number":313,"surah":5,"verses":[56],"verseLabel":"المائدة: 56","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿هم الغالبون﴾؟","answer":"ضمير الفصل يقوّي الحكم ويفيد القصر: حزب الله هم أصحاب الغلبة الحقيقية في العاقبة، لا من توهم المنافقون القوة في موالاتهم؛ فجاء الرد على حساباتهم مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص329–331.","url":""}]},{"id":"s5-314","number":314,"surah":5,"verses":[57],"verseLabel":"المائدة: 57","question":"ما مناسبة الجمع في النهي بين المستهزئين بالدين من أهل الكتاب والكفار؟","answer":"جمعهم اشتراكهم في اتخاذ الدين هزوًا ولعبًا وإن اختلفت أسماؤهم ومعتقداتهم؛ فهذا الموقف يجعل ولايتهم خطرًا على حرمة الدين وجماعة المؤمنين، فدار النهي مع الوصف الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص332–336.","url":""}]},{"id":"s5-315","number":315,"surah":5,"verses":[57],"verseLabel":"المائدة: 57","question":"ما الفرق بين ﴿هزوًا﴾ و﴿لعبًا﴾، وما دلالة الجمع بينهما؟","answer":"الهزو السخرية والاستخفاف بالقول أو الإشارة، واللعب معاملة الأمر الجاد بما لا قصد صحيح وراءه؛ فجمعهما لاستيعاب احتقار الدين وتحويل شعائره إلى عبث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص332–336.","url":""}]},{"id":"s5-316","number":316,"surah":5,"verses":[57],"verseLabel":"المائدة: 57","question":"ما دلالة قوله تعالى: ﴿واتقوا الله إن كنتم مؤمنين﴾ بعد النهي عن تلك الولاية؟","answer":"الشرط يهيج الإيمان الكامن في المخاطبين: إن كان إيمانكم صادقًا فثمرته تقوى الله وامتثال نهيه عن ولاية المستهزئين بدينه. فليس المعنى الشك في كل مخاطب، بل إلزام الإيمان بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص332–336.","url":""}]},{"id":"s5-317","number":317,"surah":5,"verses":[58],"verseLabel":"المائدة: 58","question":"ما دلالة قوله تعالى: ﴿وإذا ناديتم إلى الصلاة اتخذوها هزوًا ولعبًا﴾؟","answer":"الضمير في ﴿اتخذوها﴾ يعود إلى الصلاة أو إلى المناداة المفهومة من ﴿ناديتم﴾؛ وفي الحالين تجاوز استهزاؤهم المؤذن إلى الشعيرة التي يدعو إليها، فكشف التعبير أن موضع سخريتهم هو عبادة المؤمنين نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص337–342.","url":""}]},{"id":"s5-318","number":318,"surah":5,"verses":[58],"verseLabel":"المائدة: 58","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿ذلك بأنهم قوم لا يعقلون﴾ دون: لا يعلمون؟","answer":"لأنهم قد يعرفون ظاهر الصلاة والنداء، لكنهم لا يستعملون عقولهم في إدراك جلال العبادة وحكمة تشريعها؛ فالاستهزاء دليل خلل في التعقل، لا مجرد نقص في وصول المعلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص337–342.","url":""}]},{"id":"s5-319","number":319,"surah":5,"verses":[59],"verseLabel":"المائدة: 59","question":"ما دلالة قوله تعالى: ﴿هل تنقمون منا إلا أن آمنا بالله﴾، فجعل الإيمان محل نقمتهم؟","answer":"قصر ما يعيبونه على المؤمنين في إيمانهم بالله ووحيه تهكم بهم وإلزام؛ فإذا لم يجدوا موضع نقمة إلا التوحيد والتصديق بالكتب، انقلب اتهامهم مدحًا للمؤمنين وحجة على الناقمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص343–347.","url":""}]},{"id":"s5-320","number":320,"surah":5,"verses":[59],"verseLabel":"المائدة: 59","question":"ما دلالة الجمع بين الإيمان بما أنزل إلينا وما أنزل من قبل؟","answer":"لإظهار أن إيمان المسلمين جامع لا يفرق بين وحي الله؛ فهم يصدقون القرآن والكتب المنزلة في أصلها، وبذلك ينتفي أن تكون نقمة أهل الكتاب ناشئة من إنكار المسلمين لوحيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص343–347.","url":""}]},{"id":"s5-321","number":321,"surah":5,"verses":[59],"verseLabel":"المائدة: 59","question":"ما دلالة عطف قوله تعالى: ﴿وأن أكثركم فاسقون﴾ على ما ينقمونه؟","answer":"يجوز أن يكون المعنى: وما تنقمون منا إلا إيماننا، وإلا لأن أكثركم خارجون عن طاعة الله؛ ففسقهم هو الذي حملهم على كراهية الإيمان. وذكر ﴿أكثركم﴾ يمنع تعميم الوصف على جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص343–347.","url":""}]},{"id":"s5-322","number":322,"surah":5,"verses":[60],"verseLabel":"المائدة: 60","question":"ما دلالة الاستفهام بـ﴿هل﴾ في قوله تعالى: ﴿هل أنبئكم بشر من ذلك مثوبة عند الله﴾؟","answer":"﴿هل﴾ تعرض عليهم الخبر وتشوّق السامع إلى النبأ الذي سيكشف من هو شر منزلة، وفيها مع الأمر ﴿قل﴾ إلزام لهم بسماع الجواب؛ فهي أنسب من استفهام يطلب تعيينًا مجهولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص348–358.","url":""}]},{"id":"s5-323","number":323,"surah":5,"verses":[60],"verseLabel":"المائدة: 60","question":"ما سرّ تسمية العقوبة ﴿مثوبة﴾ في قوله تعالى: ﴿بشر من ذلك مثوبة عند الله﴾؟","answer":"المثوبة ما يرجع إلى الإنسان جزاءً على عمله، فلا تختص في أصلها بجزاء الخير؛ واستعمالها هنا في العقوبة مشاكلة تهكمية لزعمهم أنهم أهل الثواب، ثم كشف جزاؤهم الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص348–358.","url":""}]},{"id":"s5-324","number":324,"surah":5,"verses":[60],"verseLabel":"المائدة: 60","question":"ما دلالة ترتيب اللعنة والغضب والمسخ وعبادة الطاغوت في الآية؟","answer":"بدأ بالحكم الإلهي عليهم: اللعنة وهي الإبعاد عن الرحمة، ثم الغضب، ثم ذكر ما ظهر في بعضهم من المسخ، وما بلغ إليه فريق من عبادة الطاغوت؛ فتدرج من جزاء معنوي إلى آثاره الظاهرة ومن فساد العمل إلى غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص348–358.","url":""}]},{"id":"s5-325","number":325,"surah":5,"verses":[60],"verseLabel":"المائدة: 60","question":"ما دلالة قوله تعالى: ﴿وجعل منهم القردة والخنازير وعبد الطاغوت﴾؟","answer":"قوله ﴿منهم﴾ يفيد أن المسخ وقع في طوائف منهم لا في الجميع، وجمع بين المسخ الحسي في القردة والخنازير والمسخ المعنوي في عبادة الطاغوت؛ لتتعدد صور انحرافهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص348–358.","url":""}]},{"id":"s5-326","number":326,"surah":5,"verses":[60],"verseLabel":"المائدة: 60","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿أولئك شر مكانًا وأضل عن سواء السبيل﴾؟","answer":"عاد الختام إلى سؤال ﴿هل أنبئكم بشر من ذلك﴾ فعيّن أصحاب تلك الأفعال بأنهم شر منزلة عند الله، ثم بيّن سببها: أنهم أبعد عن الطريق المستوي. فجمع سوء المصير وضلال الطريق الموصل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص348–358.","url":""}]},{"id":"s5-327","number":327,"surah":5,"verses":[61],"verseLabel":"المائدة: 61","question":"ما الصورة في قوله تعالى: ﴿وقد دخلوا بالكفر وهم قد خرجوا به﴾؟","answer":"صوّر الكفر شيئًا مصاحبًا لهم دخلوا به مجلس المؤمنين ثم خرجوا حاملين إياه؛ فلم يؤثر في باطنهم ما سمعوا بين الدخول والخروج، مع قولهم الظاهر: ﴿آمنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص359–364.","url":""}]},{"id":"s5-328","number":328,"surah":5,"verses":[61],"verseLabel":"المائدة: 61","question":"ما دلالة تكرار ﴿قد﴾ مع الدخول والخروج؟","answer":"﴿قد﴾ تحقق كلًا من الحالين على حدة: تحقق دخولهم متلبسين بالكفر، وتحقق خروجهم به كما دخلوا؛ فتؤكد أن الإيمان لم يخالط قلوبهم في أي طرف من الزيارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص359–364.","url":""}]},{"id":"s5-329","number":329,"surah":5,"verses":[61],"verseLabel":"المائدة: 61","question":"ما دلالة الجمع بين دخولهم بالكفر وخروجهم به؟","answer":"ذكر الطرفين يحيط بالمجلس كله، ويثبت أن حالهم لم تتغير بسماعهم: ابتدؤوه بالكفر وختموه به. كما تكشف المقابلة كذب قولهم عند المجيء: ﴿آمنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص359–364.","url":""}]},{"id":"s5-330","number":330,"surah":5,"verses":[61],"verseLabel":"المائدة: 61","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله أعلم بما كانوا يكتمون﴾؟","answer":"لما قابلوا إظهار الإيمان بإبطان الكفر، ختمت الآية بعلم الله التام بما يخفونه؛ ففيه كشف لنفاقهم ووعيد بأن السر الذي قد يخفى على الناس لا يخفى عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص359–364.","url":""}]},{"id":"s5-331","number":331,"surah":5,"verses":[61],"verseLabel":"آل عمران: 167؛ المائدة: 61","question":"ما دلالة زيادة ﴿كانوا﴾ في قوله تعالى في المائدة: ﴿والله أعلم بما كانوا يكتمون﴾، وعدم ذكرها في نظيره بآل عمران؟","answer":"في المائدة دلّت ﴿كانوا﴾ مع المضارع على أن الكتمان صار شأنًا مستمرًا متقررًا فيهم، وهو مناسب لتصوير دخولهم وخروجهم بالكفر. أما آية آل عمران فواجهت ما يكتمونه في الواقعة نفسها، فناسب المضارع المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج6، ص294–296.","url":""}]},{"id":"s5-332","number":332,"surah":5,"verses":[62],"verseLabel":"المائدة: 62","question":"ما دلالة قوله تعالى: ﴿وترى كثيرًا منهم يسارعون في الإثم والعدوان وأكلهم السحت﴾؟","answer":"﴿ترى﴾ تستحضر سلوكهم كأنه مشهد، و﴿يسارعون في﴾ تصورهم منغمسين متنافسين في أنواعه: الإثم فيما بينهم وبين الله، والعدوان في حقوق الناس، وأكل المال الحرام؛ و﴿كثيرًا﴾ يمنع التعميم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص365–369.","url":""}]},{"id":"s5-333","number":333,"surah":5,"verses":[62],"verseLabel":"المائدة: 62","question":"ما سرّ تخصيص ﴿أكلهم السحت﴾ بعد الإثم والعدوان؟","answer":"خُص أكل المال الحرام، ومنه الرشوة، مع دخوله في الإثم والعدوان لشيوعه فيهم ولشدة أثره في تحريف الأحكام وأكل حقوق الناس؛ فذكر الخاص بعد العام لإبرازه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص365–369.","url":""}]},{"id":"s5-334","number":334,"surah":5,"verses":[62],"verseLabel":"المائدة: 62","question":"ما دلالة قوله تعالى: ﴿لبئس ما كانوا يعملون﴾؟","answer":"اللام توكيد، و﴿بئس﴾ إنشاء للذم يجعل مجموع ما تقدم بالغ السوء، و﴿كانوا يعملون﴾ تدل على رسوخ هذه الأفعال وتجددها في سلوكهم، لا وقوعها عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص365–369.","url":""}]},{"id":"s5-335","number":335,"surah":5,"verses":[63],"verseLabel":"المائدة: 63","question":"ما دلالة قوله تعالى: ﴿لولا ينهاهم الربانيون والأحبار﴾؟","answer":"﴿لولا﴾ للتحضيض الممزوج بالتوبيخ: هلا نهى العلماءُ العامةَ عن قول الإثم وأكل السحت؟ وبذلك حمّلت الآية أهل العلم مسؤولية مقاومة الفساد، ولم تجعل ذنبهم مقصورًا على فعل الحرام بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص370–374.","url":""}]},{"id":"s5-336","number":336,"surah":5,"verses":[63],"verseLabel":"المائدة: 63","question":"ما سرّ تقديم ﴿قولهم الإثم﴾ على ﴿أكلهم السحت﴾؟","answer":"قُدّم فساد القول لأنه مظهر تحريفهم وكذبهم في الدين، ومنه تهيئة الطريق لفساد الكسب وأكل الرشوة؛ ثم ذُكر السحت بوصفه ثمرة عملية ظاهرة. فالترتيب من فساد البيان إلى فساد المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص370–374.","url":""}]},{"id":"s5-337","number":337,"surah":5,"verses":[62,63],"verseLabel":"المائدة: 62–63","question":"ما الفرق بين ختم فعل العامة بقوله تعالى: ﴿لبئس ما كانوا يعملون﴾، وختم تقصير العلماء بقوله: ﴿لبئس ما كانوا يصنعون﴾؟","answer":"الصنع أخص من العمل، إذ يشعر بفعل متقن مدبر صار كالحرفة؛ فناسب العلماء الذين كان تركهم النهي مع العلم والتدبير أشد، بينما وُصف مباشرة العامة للآثام بلفظ العمل الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص365–374.","url":""}]},{"id":"s5-338","number":338,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما دلالة حكاية قول اليهود: ﴿يد الله مغلولة﴾؟","answer":"حكى القرآن مقالتهم نفسها ليفضح شناعتها؛ فهي كناية عن اتهام الله بالبخل ومنع العطاء، تعالى الله عن قولهم. ثم جاء الرد في الآية بإبطالها وإثبات سعة جوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-339","number":339,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما دلالة الرد بقوله تعالى: ﴿غُلّت أيديهم﴾ من جنس عبارتهم؟","answer":"الرد من جنس لفظهم على سبيل المشاكلة والدعاء عليهم: هم المستحقون للمنع والقبض والذل بسبب بهتانهم، لا رب العالمين. فارتد معنى الغل على قائليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-340","number":340,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما دلالة التثنية في قوله تعالى: ﴿بل يداه مبسوطتان﴾؟","answer":"التثنية في هذا التعبير أبلغ في الدلالة على كمال الجود وسعته من صورة اليد الواحدة المبسوطة؛ فهي إبطال مؤكد لوصف البخل، ويُفهم اللفظ على ما يليق بالله من غير تشبيه بالمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-341","number":341,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما مناسبة قوله تعالى: ﴿ينفق كيف يشاء﴾ بعد قوله: ﴿بل يداه مبسوطتان﴾؟","answer":"أثبت بسط الجود ثم بيّن أن العطاء والمنع يجريان وفق مشيئته وحكمته، لا لعجز ولا لبخل؛ فليس تفاوت الأرزاق دليلًا على ضيق خزائنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-342","number":342,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"كيف نفهم قوله تعالى: ﴿وليزيدن كثيرًا منهم ما أنزل إليك من ربك طغيانًا وكفرًا﴾ مع أن الوحي هدى؟","answer":"الوحي في نفسه هدى، لكن عناد كثير منهم يجعل نزوله مناسبة لزيادة طغيانهم وكفرهم؛ فالزيادة ناشئة من سوء استقبالهم وحسدهم، كما يزيد الدواءُ الصحيحُ المريضَ ضررًا إذا رفضه أو أساء استعماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-343","number":343,"surah":5,"verses":[14,64],"verseLabel":"المائدة: 14، 64","question":"ما الفرق بين قوله تعالى: ﴿فأغرينا بينهم العداوة والبغضاء﴾ وقوله: ﴿وألقينا بينهم العداوة والبغضاء﴾؟","answer":"الإغراء يفيد الإلصاق والتسليط والإدامة، فناسب ما ترتب على نسيان النصارى حظًا من الذكر من افتراق متلازم. والإلقاء يصور وضع العداوة بينهم وإيقاعها في وسطهم، فناسب سياق اليهود وما ذكرت الآية من محاولات إيقاد الحرب؛ واتحدت النتيجة واختلف تصوير منشئها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388؛ ج8، ص696–709؛ وباحث، تفريغ د. فاضل السامرائي: «فأغرينا… وألقينا…».","url":""}]},{"id":"s5-344","number":344,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما الصورة في قوله تعالى: ﴿كلما أوقدوا نارًا للحرب أطفأها الله﴾؟","answer":"استعار إيقاد النار لإشعال أسباب الحرب وتأجيجها، واستعار الإطفاء لإبطال الله تدبيرهم وإخماد الفتنة. و﴿كلما﴾ تفيد تكرر محاولتهم وتكرر إحباطها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-345","number":345,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما مناسبة قوله تعالى: ﴿ويسعون في الأرض فسادًا﴾ بعد ذكر إيقاد الحرب؟","answer":"إيقاد الحرب صورة مخصوصة من فسادهم، ثم جاء السعي في الأرض فسادًا تعميمًا لسائر حركتهم التخريبية؛ ولفظ السعي يدل على القصد وبذل الجهد والتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-346","number":346,"surah":5,"verses":[64],"verseLabel":"المائدة: 64","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله لا يحب المفسدين﴾؟","answer":"بعد وصف سعيهم في الإفساد، جاءت الخاتمة معللة لخذلان مسعاهم ومهددة لهم بحرمان محبة الله؛ كما سمّتهم باسم الفاعل ﴿المفسدين﴾ للدلالة على رسوخ الوصف فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388.","url":""}]},{"id":"s5-347","number":347,"surah":5,"verses":[65],"verseLabel":"المائدة: 65","question":"ما دلالة الجمع بين الإيمان والتقوى في قوله تعالى: ﴿ولو أن أهل الكتاب آمنوا واتقوا﴾؟","answer":"الإيمان تصديق بالله ورسله وكتبه، ومنه الإيمان بالرسول الخاتم، والتقوى أثره العملي باجتناب المعاصي والتحريف؛ فليست التقوى تكرارًا للإيمان، بل كمال يصدقه في السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص389–394.","url":""}]},{"id":"s5-348","number":348,"surah":5,"verses":[65],"verseLabel":"المائدة: 65","question":"ما سرّ تقديم تكفير السيئات على إدخال جنات النعيم؟","answer":"تكفير السيئات إزالة لما يمنع النجاة، وإدخال الجنة تحصيل للنعيم؛ فقدم التطهير من الذنب والعقوبة على التحلية بالثواب، على ترتيب التخلية ثم التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص389–394.","url":""}]},{"id":"s5-349","number":349,"surah":5,"verses":[65],"verseLabel":"المائدة: 65","question":"ما دلالة التعبير بقوله تعالى: ﴿جنات النعيم﴾؟","answer":"الجمع في ﴿جنات﴾ يشعر بتعدد البساتين والدرجات، وإضافتها إلى ﴿النعيم﴾ تجعل النعيم وصفًا محيطًا بها ثابتًا لأهلها؛ فهي ليست مجرد حدائق بل دار النعمة الكاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص389–394.","url":""}]},{"id":"s5-350","number":350,"surah":5,"verses":[66],"verseLabel":"المائدة: 66","question":"ما معنى إقامة الكتاب في قوله تعالى: ﴿ولو أنهم أقاموا التوراة والإنجيل﴾؟","answer":"إقامة الكتاب ليست مجرد تلاوته أو حفظ ألفاظه، بل جعله قائمًا في الاعتقاد والحكم والعمل من غير تحريف ولا انتقاء؛ ومن إقامته اتباع ما فيه من البشارة بالرسول الخاتم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص395–402.","url":""}]},{"id":"s5-351","number":351,"surah":5,"verses":[66],"verseLabel":"المائدة: 66","question":"ما دلالة إضافة قوله تعالى: ﴿وما أُنزل إليهم من ربهم﴾ بعد التوراة والإنجيل؟","answer":"ليدخل كل ما أنزله الله إليهم مما يجب الإيمان به، وفي مقدمته القرآن الذي خوطبوا باتباعه؛ فلا تصح إقامة كتاب سابق مع رد الوحي اللاحق المصدق له. وإضافة الرب إليهم تذكرهم بأن المنزل تربية ورحمة من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص395–402.","url":""}]},{"id":"s5-352","number":352,"surah":5,"verses":[66],"verseLabel":"المائدة: 66","question":"ما الصورة في قوله تعالى: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾؟","answer":"صورت الآية الرزق محيطًا بهم من جهتي العلو والسفل: من بركات السماء وثمرات الأرض، وهو كناية عن السعة والوفرة واندفاع أسباب النعمة من كل جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص395–402.","url":""}]},{"id":"s5-353","number":353,"surah":5,"verses":[66],"verseLabel":"المائدة: 66","question":"ما دلالة المقابلة في قوله تعالى: ﴿منهم أمة مقتصدة وكثير منهم ساء ما يعملون﴾؟","answer":"أنصفت الآية أهل الكتاب فلم تعمم الذم: أثبتت فيهم جماعة مستقيمة معتدلة، ثم حكمت بسوء عمل كثير منهم. فقابلت القلة المحمودة بالكثرة المسيئة، وجعلت المعيار العمل لا مجرد الانتساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص395–402.","url":""}]},{"id":"s5-354","number":354,"surah":5,"verses":[66],"verseLabel":"المائدة: 66","question":"ما دلالة وصف الفئة المحمودة من أهل الكتاب بأنها ﴿مقتصدة﴾؟","answer":"الاقتصاد سلوك القصد، أي الطريق المستقيم المتوسط الذي لا غلو فيه ولا تقصير؛ فوصفهم بأنهم أقرب إلى العدل واتباع الحق من الأكثرية التي ساء عملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص395–402.","url":""}]},{"id":"s5-355","number":355,"surah":5,"verses":[67],"verseLabel":"المائدة: 67","question":"ما دلالة نداء النبي ﷺ بقوله تعالى: ﴿يا أيها الرسول بلّغ ما أُنزل إليك من ربك﴾؟","answer":"نداؤه بوصف الرسالة تشريف وتثبيت، وهو أيضًا تمهيد للأمر بما هو صميم مهمته: تبليغ جميع ما أنزل إليه. وإضافة المنزل إلى ﴿ربك﴾ تشعر بالرعاية والتأييد في أداء التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–409.","url":""}]},{"id":"s5-356","number":356,"surah":5,"verses":[67],"verseLabel":"المائدة: 67","question":"ما دلالة قوله تعالى: ﴿وإن لم تفعل فما بلغت رسالته﴾ مع سبق تبليغ النبي ﷺ للوحي؟","answer":"المعنى أن كتمان أي جزء مما أُمر بتبليغه يخل بحقيقة أداء الرسالة كاملة؛ لأن المبلّغ لا يختار من الوحي ما يظهر وما يترك. وليس المراد نفي ما وقع من تبليغ سابق، بل بيان أن كمال المهمة لا يتجزأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–409.","url":""}]},{"id":"s5-357","number":357,"surah":5,"verses":[67],"verseLabel":"المائدة: 67","question":"ما دلالة إفراد ﴿رسالته﴾ في قراءة، وجمعها ﴿رسالاته﴾ في قراءة أخرى؟","answer":"الإفراد يجعل الرسالة اسم جنس جامعًا للوحي كله ويبرز وحدتها في المصدر والمقصد، والجمع يلحظ تعدد أوامرها وأحكامها وما أرسل النبي ﷺ بتبليغه؛ فالقراءتان تجمعان وحدة الرسالة وتعدد مضامينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–409.","url":""}]},{"id":"s5-358","number":358,"surah":5,"verses":[67],"verseLabel":"المائدة: 67","question":"ما مناسبة قوله تعالى: ﴿والله يعصمك من الناس﴾ عقب الأمر بالتبليغ؟","answer":"لما كان تمام التبليغ قد يعرض الرسول ﷺ لأذى المعاندين، تكفل الله بحفظه من أن يقتلوه أو يمنعوه من إكمال رسالته؛ فالطمأنة ترفع خوف الصد عن أداء التكليف، ولا تعني نفي كل أذى بشري عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–409.","url":""}]},{"id":"s5-359","number":359,"surah":5,"verses":[67],"verseLabel":"المائدة: 67","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الكافرين﴾؟","answer":"بعد ضمان عصمة الرسول ﷺ، قررت الخاتمة أن الله لا يوفق المعاندين إلى إبطال الرسالة ولا يهدي من أصر على كفره؛ فلا ينبغي أن يكون صدودهم سببًا لنقص البلاغ أو الحزن على تدبيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–409.","url":""}]},{"id":"s5-360","number":360,"surah":5,"verses":[68],"verseLabel":"المائدة: 68","question":"ما دلالة قوله تعالى: ﴿لستم على شيء حتى تقيموا التوراة والإنجيل﴾؟","answer":"نفي أن يكونوا ﴿على شيء﴾ مبالغة في نفي قيامهم على أصل ديني معتبر ما داموا لا يقيمون كتب الله؛ فليس المراد نفي وجودهم أو علومهم، بل نفي قيمة دعواهم الدينية دون إيمان وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص410–415.","url":""}]},{"id":"s5-361","number":361,"surah":5,"verses":[68],"verseLabel":"المائدة: 68","question":"ما دلالة قوله تعالى: ﴿وما أُنزل إليكم من ربكم﴾ بعد ذكر التوراة والإنجيل؟","answer":"يعطف الوحي الذي أنزله الله إليهم بعد الكتابين، وفي مقدمته القرآن، حتى لا يزعموا أن إقامة التوراة والإنجيل تغني عن تصديق ما جاء مصدقًا لهما. فإقامة الوحي سلسلة لا يصح قطع آخرها عن أولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص410–415.","url":""}]},{"id":"s5-362","number":362,"surah":5,"verses":[64,68],"verseLabel":"المائدة: 64، 68","question":"ما مناسبة تكرار قوله تعالى: ﴿وليزيدن كثيرًا منهم ما أُنزل إليك من ربك طغيانًا وكفرًا﴾؟","answer":"ورد أولًا بعد كشف مقالتهم في بخل الله وإيقادهم الحرب، ثم أعيد بعد أمرهم بإقامة الكتب؛ ليقرر أن وضوح الوحي نفسه لا ينفع المعاند، وليواسي الرسول ﷺ من رد فعلهم عند تبليغ ما أنزل إليه. فالمعنى واحد ووظيفة كل موضع مرتبطة بسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص375–388، 410–415.","url":""}]},{"id":"s5-363","number":363,"surah":5,"verses":[68],"verseLabel":"المائدة: 68","question":"ما دلالة قوله تعالى: ﴿فلا تأس على القوم الكافرين﴾؟","answer":"الأسى شدة الحزن، فنهاه الله عن الحزن المستغرق على من اختار الكفر بعد قيام الحجة؛ لأنه أدى البلاغ، ولأن زيادة طغيانهم من سوء تلقيهم لا من قصور الوحي. وليس النهي عن الرحمة والرغبة في هدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص410–415.","url":""}]},{"id":"s5-364","number":364,"surah":5,"verses":[69],"verseLabel":"المائدة: 69","question":"ما سرّ رفع ﴿الصابئون﴾ في قوله تعالى: ﴿إن الذين آمنوا والذين هادوا والصابئون والنصارى﴾؟","answer":"رُفعت على القطع والاستئناف، كأن التقدير: والصابئون كذلك؛ فخُولف الإعراب المتوقع للتنبيه إلى أن هذه الطائفة، مع بعدها في ظن السامع، تدخل في الحكم إن تحقق فيها الإيمان الصحيح والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص416–421.","url":""}]},{"id":"s5-365","number":365,"surah":5,"verses":[69],"verseLabel":"البقرة: 62؛ المائدة: 69","question":"ما سرّ تقديم ﴿الصابئون﴾ على ﴿النصارى﴾ في المائدة، وتأخيرهم عنهم في البقرة؟","answer":"قدمت المائدة الصابئين لأن رفعهم على الاستئناف جعلهم موضع تنبيه خاص: حتى هذه الطائفة الأبعد في الاعتقاد لا يحجبها اسمها عن الجزاء إن آمنت وعملت صالحًا. أما البقرة فساقت الطوائف في نسق معطوف معتاد، فجاء الصابئون بعد النصارى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص416–421؛ وله مناقشة عكسية ج1، ص538.","url":""}]},{"id":"s5-366","number":366,"surah":5,"verses":[69],"verseLabel":"المائدة: 69","question":"ما دلالة إعادة قوله تعالى: ﴿من آمن بالله واليوم الآخر وعمل صالحًا﴾ بعد ذكر ﴿الذين آمنوا﴾؟","answer":"تبين الإعادة أن أسماء الجماعات وانتسابها التاريخي لا تكفي للنجاة؛ فالعبرة بتحقق الإيمان الصحيح والعمل الصالح في زمن الرسالة التي بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص416–421.","url":""}]},{"id":"s5-367","number":367,"surah":5,"verses":[69],"verseLabel":"المائدة: 69","question":"ما الفرق في بناء النفي بين قوله تعالى: ﴿فلا خوف عليهم﴾ وقوله: ﴿ولا هم يحزنون﴾؟","answer":"﴿لا خوف عليهم﴾ تنفي جنس الخوف عنهم فيما يستقبلهم، فجاءت جملة اسمية شاملة، و﴿ولا هم يحزنون﴾ تنفي تجدد الحزن عليهم لما مضى، وذكر الضمير يؤكد اختصاصهم بهذا الأمن. فاجتمع أمن المستقبل وسلامة النفس من حزن الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص416–421.","url":""}]},{"id":"s5-368","number":368,"surah":5,"verses":[69],"verseLabel":"البقرة: 62؛ المائدة: 69","question":"ما سرّ ذكر ﴿فلهم أجرهم عند ربهم﴾ في البقرة، وعدم ذكره في نظيرتها من المائدة؟","answer":"سياق البقرة مقام تأسيس لوعد الطوائف التي حققت الإيمان والعمل، فصرح بالأجر ثم نفى الخوف والحزن. أما المائدة فجاءت الآية في أثناء محاجة أهل الكتاب، فاقتصر على نفي الخوف والحزن، والأجر معلوم من العمل الصالح ومن نظير الآية؛ فالحذف إيجاز لا نفي للثواب.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج1، ص527–538.","url":""}]},{"id":"s5-369","number":369,"surah":5,"verses":[12,70],"verseLabel":"المائدة: 12، 70","question":"ما مناسبة إعادة ذكر ميثاق بني إسرائيل بعد وروده في الآية 12؟","answer":"ذُكر أول السورة مع تفصيل النقباء وشروط العهد ونقضه، ثم أعيد هنا تمهيدًا لتاريخ استقبالهم الرسل بين التكذيب والقتل؛ فالأول يشرح بنود الميثاق وعاقبته، والثاني يجعله أصلًا للحكم على مسيرتهم مع الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص422–426.","url":""}]},{"id":"s5-370","number":370,"surah":5,"verses":[70],"verseLabel":"المائدة: 70","question":"ما دلالة تنكير ﴿رسلًا﴾ وجمعها في قوله تعالى: ﴿وأرسلنا إليهم رسلًا﴾؟","answer":"الجمع يدل على تتابع عدد من الرسل إليهم، والتنكير يعظم كثرتهم وتنوع أزمانهم ورسالاتهم؛ فتشتد الحجة لأن العصيان لم يقع مع رسول واحد أو في حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص422–426.","url":""}]},{"id":"s5-371","number":371,"surah":5,"verses":[70],"verseLabel":"المائدة: 70","question":"ما دلالة قوله تعالى: ﴿كلما جاءهم رسول بما لا تهوى أنفسهم﴾؟","answer":"﴿كلما﴾ تفيد تكرر النمط مع الرسل، وجعل ما تهواه النفس أو تكرهه معيار موقفهم يفضح انقلاب وظيفة الوحي عندهم: بدل أن يحكم الوحي أهواءهم، جعلوا أهواءهم تحكم قبول الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص422–426.","url":""}]},{"id":"s5-372","number":372,"surah":5,"verses":[70],"verseLabel":"المائدة: 70","question":"ما سرّ اختلاف الزمن في قوله تعالى: ﴿فريقًا كذبوا وفريقًا يقتلون﴾؟","answer":"جاء التكذيب بالماضي لتسجيل ما وقع منهم، وجاء القتل بالمضارع لاستحضار بشاعته وتصويره متجددًا، ولأن عدوانهم على الرسل ظل عادة متكررة حتى زمن الخطاب؛ فانتقل من الخبر إلى المشهد الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص422–426.","url":""}]},{"id":"s5-373","number":373,"surah":5,"verses":[71],"verseLabel":"المائدة: 71","question":"ما دلالة قوله تعالى: ﴿وحسبوا ألا تكون فتنة﴾؟","answer":"﴿حسبوا﴾ تدل على اعتقاد بنوه على تقدير فاسد وثقة واهية، إذ توهموا ألا تلحقهم محنة أو عقوبة بسبب تكذيب الرسل وقتلهم؛ فليس مجرد ظن عابر، بل حساب باطل رتبوا عليه فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص427–436.","url":""}]},{"id":"s5-374","number":374,"surah":5,"verses":[71],"verseLabel":"المائدة: 71","question":"ما الصورة في قوله تعالى: ﴿فعموا وصموا﴾؟","answer":"استعار العمى لامتناعهم عن رؤية دلائل الحق، والصمم لامتناعهم عن سماعها سماع قبول؛ فصوّر التعطيل الإرادي للبصيرة والسمع كأنه فقد للحاستين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص427–436.","url":""}]},{"id":"s5-375","number":375,"surah":5,"verses":[71],"verseLabel":"المائدة: 71","question":"ما دلالة تكرار ﴿ثم﴾ في قوله تعالى: ﴿ثم تاب الله عليهم ثم عموا وصموا كثير منهم﴾؟","answer":"الأولى تفصل بين فتنتهم الأولى وبين تفضل الله بقبول توبتهم، والثانية تستبعد رتبة عود كثير منهم إلى العمى والصمم بعد تلك الرحمة؛ فالتكرار يصور تعاقب الأطوار ويعظم قبح الانتكاس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص427–436.","url":""}]},{"id":"s5-376","number":376,"surah":5,"verses":[71],"verseLabel":"المائدة: 71","question":"ما دلالة تقييد العمى والصمم في المرة الثانية بقوله تعالى: ﴿كثير منهم﴾؟","answer":"قيد الوصف في العودة الثانية بالكثير إنصافًا لمن ثبت على التوبة ولم ينتكس؛ فلا يحمل تاريخ الجماعة على كل فرد فيها. أما الإطلاق الأول فيحكي السمة الغالبة في المرحلة الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص427–436.","url":""}]},{"id":"s5-377","number":377,"surah":5,"verses":[71],"verseLabel":"المائدة: 71","question":"ما مناسبة قوله تعالى: ﴿والله بصير بما يعملون﴾ بعد وصفهم بالعمى والصمم؟","answer":"في الخاتمة مقابلة تهديدية: هم عموا عن دلائل الله وصموا عنها، أما الله فبصير لا يخفى عليه شيء من أعمالهم. وانتقل من أحوال القلوب إلى ﴿يعملون﴾ لأن آثار ذلك العمى ظهرت في التكذيب والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص427–436.","url":""}]},{"id":"s5-378","number":378,"surah":5,"verses":[17,72],"verseLabel":"المائدة: 17، 72","question":"ما مناسبة تكرار قوله تعالى: ﴿لقد كفر الذين قالوا إن الله هو المسيح ابن مريم﴾؟","answer":"ورد أولًا في سياق بيان ملك الله وقدرته على إهلاك المسيح وأمه ومن في الأرض، ثم أعيد هنا تمهيدًا للاحتجاج بكلام المسيح نفسه وبيان عاقبة الشرك؛ فتكرر الحكم وتنوعت الحجة التابعة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص437–447؛ ج8، ص726–737.","url":""}]},{"id":"s5-379","number":379,"surah":5,"verses":[72],"verseLabel":"المائدة: 72","question":"ما دلالة مجيء الرد على تأليه المسيح من كلامه عليه السلام: ﴿يا بني إسرائيل اعبدوا الله ربي وربكم﴾؟","answer":"شهادة المسيح نفسه ألزم لمن زعم ألوهيته؛ فقد دعا قومه إلى عبادة الله، وصرح بأنه مربوب لهم كما هم مربوبون، فبطل الغلو فيه من أصل تعليمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص437–447.","url":""}]},{"id":"s5-380","number":380,"surah":5,"verses":[72],"verseLabel":"المائدة: 72","question":"ما دلالة قول المسيح عليه السلام: ﴿ربي وربكم﴾؟","answer":"بدأ بربوبية الله له ليعلن عبوديته وينفي أن يكون إلهًا، ثم عطف ربوبية مخاطبيه ليدعوهم وإياه إلى أصل واحد: عبادة الرب الواحد. فتقديم ﴿ربي﴾ حجة من نفسه قبل إلزامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص437–447.","url":""}]},{"id":"s5-381","number":381,"surah":5,"verses":[72],"verseLabel":"المائدة: 72","question":"ما دلالة الجمع بين قوله تعالى: ﴿حرم الله عليه الجنة﴾ وقوله: ﴿ومأواه النار﴾؟","answer":"الأول ينفي عنه غاية النعيم ويقرر منعه منها، والثاني يثبت له مقابلها وهو النار دار إقامة؛ فجمع حرمان الخير وحلول العذاب، ولم يترك بعد النفي توهم منزلة بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص437–447.","url":""}]},{"id":"s5-382","number":382,"surah":5,"verses":[72],"verseLabel":"المائدة: 72","question":"ما دلالة قوله تعالى: ﴿وما للظالمين من أنصار﴾؟","answer":"نفت ﴿ما﴾ الناصر، وزادت ﴿من﴾ الاستغراق فنفت أي نصير مهما كان، وجاء الجمع لأن تعدد الأنصار هو مظنة النجاة؛ لكن ظلم الشرك يقطع عن صاحبه كل نصرة يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص437–447.","url":""}]},{"id":"s5-383","number":383,"surah":5,"verses":[73],"verseLabel":"المائدة: 73","question":"ما دلالة قولهم الذي حكاه القرآن: ﴿إن الله ثالث ثلاثة﴾؟","answer":"التعبير يحكي جعلهم الله واحدًا في عدد مركب من ثلاثة، فجاء الرد بإبطال أصل التعدد لا مناقشة ترتيب الأقانيم: ﴿وما من إله إلا إله واحد﴾. ولفظ ﴿ثالث ثلاثة﴾ أصرح في بناء العدد الذي ينقضه التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص448–460.","url":""}]},{"id":"s5-384","number":384,"surah":5,"verses":[73],"verseLabel":"المائدة: 73","question":"ما دلالة المؤكدات في قوله تعالى: ﴿وما من إله إلا إله واحد﴾؟","answer":"﴿ما﴾ تنفي الألوهية عما سوى الله، و﴿من﴾ تستغرق كل ما قد يُدعى إلهًا، و﴿إلا﴾ تحصرها، ثم جاء ﴿واحد﴾ لنفي كل تركيب أو تعدد؛ فاجتمعت المؤكدات في مواجهة مقالة التثليث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص448–460.","url":""}]},{"id":"s5-385","number":385,"surah":5,"verses":[73],"verseLabel":"المائدة: 73","question":"ما دلالة قوله تعالى: ﴿وإن لم ينتهوا عما يقولون﴾ دون الاقتصار على ذكر الاعتقاد؟","answer":"لأن مقالتهم هي الصورة المعلنة للعقيدة الباطلة ووسيلة نشرها، فطُلب انتهاء صريح عما ينطقون به ويدعون إليه، وهو يتضمن الرجوع عن الاعتقاد الذي يصدر عنه القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص448–460.","url":""}]},{"id":"s5-386","number":386,"surah":5,"verses":[73],"verseLabel":"المائدة: 73","question":"ما دلالة ﴿منهم﴾ في قوله تعالى: ﴿ليمسن الذين كفروا منهم عذاب أليم﴾؟","answer":"﴿منهم﴾ للتبعيض، فتخص الوعيد بمن يثبت على الكفر من القائلين ولا يتوب؛ فلا تغلق الآية باب الرجوع أمام جميعهم، وهو ما يمهد له عرض التوبة في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص448–460.","url":""}]},{"id":"s5-387","number":387,"surah":5,"verses":[90],"verseLabel":"المائدة: 73؛ التوبة: 90","question":"ما الفرق بين قوله تعالى في المائدة: ﴿ليمسن الذين كفروا منهم عذاب أليم﴾، وقوله في التوبة: ﴿سيصيب الذين كفروا منهم عذاب أليم﴾؟","answer":"في المائدة جاء الوعيد جوابًا لشرط عدم الانتهاء، فأكد باللام والنون وصوّر العذاب مماسة مباشرة لهم. وفي التوبة سيق خبرًا عن المكذبين والمتخلفين، فناسب الاستقبال بـ﴿سيصيب﴾. فزاد توكيد المائدة لقربه من مقالة التثليث والإنذار المشروط.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج18، ص52–53.","url":""}]},{"id":"s5-388","number":388,"surah":5,"verses":[74],"verseLabel":"المائدة: 74","question":"ما دلالة عرض التوبة بقوله تعالى: ﴿أفلا يتوبون إلى الله ويستغفرونه﴾ بدل الأمر المباشر؟","answer":"الاستفهام للتحضيض والتعجيب من تركهم التوبة مع وضوح الباطل وفظاعة الوعيد؛ وهو ألطف في فتح الباب واستدعاء الرجوع من أمر مجرد، كأن التوبة أمر يتوقعه العقل منهم ولا عذر في تأخيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص461–465.","url":""}]},{"id":"s5-389","number":389,"surah":5,"verses":[74],"verseLabel":"المائدة: 74","question":"ما دلالة الجمع بين التوبة والاستغفار؟","answer":"التوبة رجوع عن الاعتقاد والقول الباطل وندم وعزم على عدم العودة، والاستغفار طلب محو ما سلف وستره؛ فالأولى إصلاح للموقف من الذنب، والثاني سؤال لرفع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص461–465.","url":""}]},{"id":"s5-390","number":390,"surah":5,"verses":[74],"verseLabel":"المائدة: 74","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله غفور رحيم﴾ بعد ذكر مقالة التثليث؟","answer":"الخاتمة تعلل دعوتهم إلى التوبة: فمع عظم المقالة يغفر الله لمن رجع ويرحمه، وفيها تغليب للترغيب بعد الوعيد وبيان أن باب الرحمة لا يغلق أمام صادق التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص461–465.","url":""}]},{"id":"s5-391","number":391,"surah":5,"verses":[75],"verseLabel":"المائدة: 75","question":"ما دلالة القصر في قوله تعالى: ﴿ما المسيح ابن مريم إلا رسول قد خلت من قبله الرسل﴾؟","answer":"حصر المسيح عليه السلام في حقيقة الرسالة البشرية التي شاركه فيها رسل سبقوه ومضوا؛ فمن كان واحدًا في سلسلة الرسل وتلحقه سننهم لا يكون إلهًا. والقصر رد مباشر على الغلو مع حفظ منزلته رسولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص466–476.","url":""}]},{"id":"s5-392","number":392,"surah":5,"verses":[75],"verseLabel":"المائدة: 75","question":"ما دلالة وصف مريم عليها السلام بأنها ﴿صديقة﴾ في هذا المقام؟","answer":"الصديقة كثيرة الصدق بالقول والتصديق بوحي الله، فالوصف يثبت لها أعلى منازل الصالحات اللائقة بالبشر من غير أن يرفعها إلى الألوهية؛ وهو مدح يرد الغلو في الوقت نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص466–476.","url":""}]},{"id":"s5-393","number":393,"surah":5,"verses":[75],"verseLabel":"المائدة: 75","question":"ما دلالة الاحتجاج على بشرية المسيح وأمه بقوله تعالى: ﴿كانا يأكلان الطعام﴾؟","answer":"أكل الطعام دليل حسي على حاجتهما إلى القوت وما يلزم طبيعة البشر؛ والمحتاج لا يكون إلهًا غنيًا عن العالمين. فجاءت حجة قريبة لا تحتاج إلى جدل نظري.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص466–476.","url":""}]},{"id":"s5-394","number":394,"surah":5,"verses":[75],"verseLabel":"المائدة: 75","question":"ما دلالة تكرار الأمر بالنظر في قوله تعالى: ﴿انظر كيف نبين لهم الآيات ثم انظر أنى يؤفكون﴾؟","answer":"النظر الأول إلى وضوح طريقة بيان الحجج، والثاني إلى عجب انصرافهم عنها بعد هذا البيان؛ فكرر الأمر لاختلاف المنظور إليه، وجاءت ﴿ثم﴾ لتفاوت الحالين واستبعاد الانتقال من الوضوح إلى الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص466–476.","url":""}]},{"id":"s5-395","number":395,"surah":5,"verses":[75],"verseLabel":"المائدة: 75","question":"ما الفرق بين ﴿كيف﴾ و﴿أنى﴾ في قوله تعالى: ﴿انظر كيف نبين لهم الآيات ثم انظر أنى يؤفكون﴾؟","answer":"﴿كيف﴾ تسأل عن حال البيان وطريقته فتلفت إلى تنوعه ووضوحه، و﴿أنى﴾ تسأل من أي جهة وكيف يُصرفون عنه، فتفيد التعجب من مبلغ انحرافهم بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص466–476.","url":""}]},{"id":"s5-396","number":396,"surah":5,"verses":[76],"verseLabel":"المائدة: 76","question":"ما سرّ تقديم الضر على النفع في قوله تعالى: ﴿ما لا يملك لكم ضرًا ولا نفعًا﴾؟","answer":"السياق مقام إنكار وتهديد للمشركين، فبدأ بنفي قدرة معبوداتهم على الضر الذي يخافه العابد عادة، ثم نفى قدرتها على جلب النفع الذي يرجوه؛ وباجتماعهما بطلت كل علة لعبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص477–485.","url":""}]},{"id":"s5-397","number":397,"surah":5,"verses":[76],"verseLabel":"المائدة: 76","question":"ما دلالة التعبير عن المعبودات بـ﴿ما﴾ في قوله تعالى: ﴿أتعبدون من دون الله ما لا يملك لكم ضرًا ولا نفعًا﴾؟","answer":"جيء بـ﴿ما﴾ لأنها تعم كل ما عُبد من دون الله بالنظر إلى وصفه لا إلى شخصه، ولأن سلب القدرة عن المعبود ينزله منزلة ما لا يعقل ولا يملك تصرفًا؛ فناسبها مقام إبطال الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص477–485.","url":""}]},{"id":"s5-398","number":398,"surah":5,"verses":[76],"verseLabel":"المائدة: 76","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿والله هو السميع العليم﴾؟","answer":"يفيد ﴿هو﴾ قصر كمال السمع والعلم على الله؛ فهو يسمع أقوال العابدين ودعاءهم، ويعلم عقائدهم وحاجاتهم، بخلاف ما عُبد من دونه مما لا يملك ضرًا ولا نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص477–485.","url":""}]},{"id":"s5-399","number":399,"surah":5,"verses":[77],"verseLabel":"المائدة: 77","question":"ما دلالة قوله تعالى: ﴿لا تغلوا في دينكم غير الحق﴾، وهل يفيد القيد وجود غلوٍّ بحق؟","answer":"الغلو مجاوزة الحد المشروع، فهو في الدين غير حق بطبيعته. وقوله ﴿غير الحق﴾ قيد كاشف يؤكد بطلانه ويواجه غلوهم في المسيح، لا قيد احترازي يثبت نوعًا مشروعًا من الغلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص486–494.","url":""}]},{"id":"s5-400","number":400,"surah":5,"verses":[77],"verseLabel":"المائدة: 77","question":"ما مناسبة النهي عن اتباع أهواء قوم ﴿قد ضلوا من قبل وأضلوا كثيرًا وضلوا عن سواء السبيل﴾؟","answer":"لأن من ثبت ضلاله في نفسه، ونقل الضلال إلى كثير غيره، واستمر بعيدًا عن الطريق المستوي لا يصلح أن يكون متبوعًا في الدين؛ فاتباع أهوائه امتداد لسلسلة الضلال لا طلب للهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص486–494.","url":""}]},{"id":"s5-401","number":401,"surah":5,"verses":[77],"verseLabel":"المائدة: 77","question":"ما دلالة تكرار فعل الضلال في قوله تعالى: ﴿قد ضلوا من قبل وأضلوا كثيرًا وضلوا عن سواء السبيل﴾؟","answer":"الأول يسجل ضلالهم السابق، والثاني يبين تعديته إلى غيرهم بصيغة ﴿أضلوا﴾، والثالث يقرر استمرارهم وانتهاءهم بعيدًا عن الطريق المستقيم؛ فتدرج من فساد النفس إلى إفساد الناس ثم رسوخ المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص486–494.","url":""}]},{"id":"s5-402","number":402,"surah":5,"verses":[78],"verseLabel":"المائدة: 78","question":"ما دلالة قوله تعالى: ﴿لُعن الذين كفروا من بني إسرائيل على لسان داود وعيسى ابن مريم﴾؟","answer":"بُني ﴿لُعن﴾ للمجهول للتركيز على ثبوت الطرد من الرحمة، ثم بيّن أن اللعنة جرت على لساني نبيين منهم وفي كتابين وعصرين؛ فتقوم عليهم الحجة من داخل تاريخهم الديني.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص495–501.","url":""}]},{"id":"s5-403","number":403,"surah":5,"verses":[78],"verseLabel":"المائدة: 78","question":"ما دلالة الجمع بين داود وعيسى عليهما السلام مع تباعد زمنيهما؟","answer":"يدل على أن إنكار العصيان والعدوان سنة متصلة في رسالات الله، وأن أسباب اللعنة تكررت في بني إسرائيل عبر أزمنة متباعدة؛ فلم تكن زلة جيل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص495–501.","url":""}]},{"id":"s5-404","number":404,"surah":5,"verses":[78],"verseLabel":"المائدة: 78","question":"ما الفرق بين العصيان والاعتداء في قوله تعالى: ﴿ذلك بما عصوا وكانوا يعتدون﴾؟","answer":"العصيان مخالفة أمر الله وترك طاعته، والاعتداء تجاوز الحدود إلى حقوق الغير؛ فجمع فساد الصلة بالتكليف وفساد المعاملة، ودلت ﴿كانوا﴾ والمضارع على أن الاعتداء صار دأبًا متجددًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص495–501.","url":""}]},{"id":"s5-405","number":405,"surah":5,"verses":[79],"verseLabel":"المائدة: 79","question":"ما دلالة قوله تعالى: ﴿كانوا لا يتناهون عن منكر فعلوه﴾؟","answer":"﴿يتناهون﴾ تدل على أن بعضهم لا ينهى بعضًا؛ فصار ترك التناهي عادة جماعية، و﴿فعلوه﴾ يبين أن المنكر وقع واستمر من غير أن يواجهوه بإنكار أو توبة. فالذم يشمل الفاعل والساكت القادر على النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص502–506.","url":""}]},{"id":"s5-406","number":406,"surah":5,"verses":[79],"verseLabel":"المائدة: 79","question":"ما دلالة تنكير وإفراد ﴿منكر﴾ في قوله تعالى: ﴿عن منكر فعلوه﴾؟","answer":"التنكير يعم أي منكر يقع منهم، ولو كان واحدًا، فكيف إذا كثرت منكراتهم؛ والإفراد اسم جنس يستوعب أنواع المنكر ولا يقصر الذم على جريمة معينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص502–506.","url":""}]},{"id":"s5-407","number":407,"surah":5,"verses":[79],"verseLabel":"المائدة: 79","question":"ما دلالة ختم الآية بقوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"﴿بئس﴾ تنشئ ذمًا بالغًا لما اجتمع فيهم من فعل المنكر وترك التناهي عنه، واللام تؤكده، و﴿كانوا يفعلون﴾ تصور ذلك سلوكًا متقررًا لا حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص502–506.","url":""}]},{"id":"s5-408","number":408,"surah":5,"verses":[80],"verseLabel":"المائدة: 80","question":"ما دلالة المضارع في قوله تعالى: ﴿ترى كثيرًا منهم يتولون الذين كفروا﴾؟","answer":"﴿ترى﴾ تجعل ولايتهم مشهدًا مشاهدًا، والمضارع ﴿يتولون﴾ يستحضر تجددها واستمرارها، و﴿كثيرًا﴾ يثبت شيوعها من غير تعميمها على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص507–511.","url":""}]},{"id":"s5-409","number":409,"surah":5,"verses":[80],"verseLabel":"المائدة: 80","question":"ما دلالة قوله تعالى: ﴿لبئس ما قدمت لهم أنفسهم﴾؟","answer":"صوّر أعمالهم زادًا بعثوه أمامهم إلى الآخرة، لكنه شر زاد جر عليهم السخط والعذاب. وإسناد التقديم إلى ﴿أنفسهم﴾ يحملهم المسؤولية؛ فلم يظلمهم غيرهم، بل صنعوا مصيرهم بأفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص507–511.","url":""}]},{"id":"s5-410","number":410,"surah":5,"verses":[80],"verseLabel":"المائدة: 80","question":"ما دلالة جعل ما قدمته أنفسهم هو قوله تعالى: ﴿أن سخط الله عليهم﴾؟","answer":"ذُكرت العاقبة مقام العمل لأنها ملازمة له وناشئة عنه؛ فكأنهم قدموا لأنفسهم سخط الله حين اختاروا ولاية الكافرين. وفيه تهويل للسيئة بذكر نتيجتها بدل الاكتفاء باسمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص507–511.","url":""}]},{"id":"s5-411","number":411,"surah":5,"verses":[80],"verseLabel":"المائدة: 80","question":"ما دلالة التقديم والتوكيد في قوله تعالى: ﴿وفي العذاب هم خالدون﴾؟","answer":"تقديم ﴿في العذاب﴾ يبرز الوعاء الذي أحاط بهم، وضمير الفصل ﴿هم﴾ يقوي ثبوت الخلود لهم؛ فجاء التركيب أبلغ في لزوم العذاب من الخبر المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص507–511.","url":""}]},{"id":"s5-412","number":412,"surah":5,"verses":[81],"verseLabel":"المائدة: 81","question":"ما دلالة الشرط في قوله تعالى: ﴿ولو كانوا يؤمنون بالله والنبي وما أنزل إليه ما اتخذوهم أولياء﴾؟","answer":"جعلت الآية انتفاء تلك الولاية ثمرة لازمة للإيمان الصحيح؛ فلو تحقق إيمانهم بالله ونبيه ووحيه لمنعهم من موالاة الكافرين عليه. و﴿لو﴾ تكشف أن دعوى الإيمان تناقض واقع فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص512–517.","url":""}]},{"id":"s5-413","number":413,"surah":5,"verses":[81],"verseLabel":"المائدة: 81","question":"ما دلالة التعبير بـ﴿النبي﴾ في قوله تعالى: ﴿يؤمنون بالله والنبي وما أنزل إليه﴾؟","answer":"وصف النبوة يلائم اقتران النبي بما أنزل إليه؛ فهو الذي نبّأه الله بالوحي، والإيمان بنبوته يوجب تصديق ما أنزل عليه. أما وصف الرسالة فيبرز جهة التبليغ، والمقام هنا في أصل التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص512–517.","url":""}]},{"id":"s5-414","number":414,"surah":5,"verses":[81],"verseLabel":"المائدة: 81","question":"ما دلالة ختم الآية بقوله تعالى: ﴿ولكن كثيرًا منهم فاسقون﴾؟","answer":"استدركت ﴿لكن﴾ على الشرط السابق لتبين المانع من الإيمان وآثاره: خروج كثير منهم عن طاعة الله هو الذي أوقعهم في تلك الولاية، و﴿كثيرًا﴾ يمنع تعميم الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص512–517.","url":""}]},{"id":"s5-415","number":415,"surah":5,"verses":[82],"verseLabel":"المائدة: 82","question":"ما دلالة التوكيد والمقابلة بين قوله تعالى: ﴿لتجدن أشد الناس عداوة﴾ وقوله: ﴿ولتجدن أقربهم مودة﴾؟","answer":"اللام ونون التوكيد تثبتان ما سيجده المخاطب، والمقابلة ترسم طرفي الموقف من المؤمنين: شدة العداوة في فريق، وقرب المودة في فريق آخر. ولم تسوِّ بين الطرفين في اللفظ، بل قالت في الثاني ﴿أقربهم﴾ لا أشدهم مودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص518–532.","url":""}]},{"id":"s5-416","number":416,"surah":5,"verses":[82],"verseLabel":"المائدة: 82","question":"ما سرّ تقديم اليهود على المشركين في جانب العداوة؟","answer":"رتبت الآية الفريقين بحسب ما كشفه سياق السورة وواقع المخاطبين من شدة العداوة؛ فقد كان اليهود أقرب احتكاكًا بالمؤمنين وأظهر كيدًا وجدالًا لهم، ثم عطف عليهم المشركين لاشتراكهم في العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص518–532.","url":""}]},{"id":"s5-417","number":417,"surah":5,"verses":[82],"verseLabel":"المائدة: 82","question":"ما دلالة وصف النصارى بأنهم ﴿أقربهم مودة للذين آمنوا﴾ دون: أشدهم مودة؟","answer":"﴿أقربهم﴾ وصف نسبي يقرر أنهم أقرب الطوائف المذكورة إلى المودة، ولا يحكم بأن جميعهم على غاية المحبة أو أن المودة ثابتة لكل فرد؛ فاختير اللفظ الأدق الذي يوافق التفصيل الآتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص518–532.","url":""}]},{"id":"s5-418","number":418,"surah":5,"verses":[82],"verseLabel":"المائدة: 82","question":"ما دلالة تعليل قرب المودة بوجود ﴿قِسيسين ورهبانًا﴾؟","answer":"القسيسون أهل علم وتعليم، والرهبان أهل عبادة وزهد؛ فوجود العلم الصادق والعبادة التي ترقق القلب كان سببًا في قرب فريق منهم من قبول الحق حين سمعه، لا أن مجرد اللقب يوجب المودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص518–532.","url":""}]},{"id":"s5-419","number":419,"surah":5,"verses":[82],"verseLabel":"المائدة: 82","question":"ما دلالة ختم التعليل بقوله تعالى: ﴿وأنهم لا يستكبرون﴾؟","answer":"عدم الاستكبار هو الباب الذي جعل علمهم وعبادتهم يثمران قبولًا للحق؛ فقد يمنع الكبر صاحبه من الإذعان ولو عرف. لذلك ختمت به العلل تمهيدًا لمشهد بكائهم وإيمانهم عند سماع القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص518–532.","url":""}]},{"id":"s5-420","number":420,"surah":5,"verses":[83],"verseLabel":"المائدة: 83","question":"ما الصورة في قوله تعالى: ﴿وإذا سمعوا ما أُنزل إلى الرسول ترى أعينهم تفيض من الدمع﴾؟","answer":"نقلت الآية أثر الوحي من السماع إلى مشهد تراه العين: امتلأت أعينهم بالدمع حتى فاض، بسبب ما عرفوه من الحق. فاجتمع إدراك القلب وانفعال الجسد، وجاء المضارع لاستحضار المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص533–546.","url":""}]},{"id":"s5-421","number":421,"surah":5,"verses":[83],"verseLabel":"المائدة: 83","question":"ما سرّ إسناد الفيضان إلى الأعين لا إلى الدموع؟","answer":"الأصل أن يفيض الدمع من العين، لكن إسناد الفيضان إلى الأعين مبالغة تصورها وقد امتلأت حتى كأنها هي التي فاضت؛ فيدل على كثرة الدمع وشدة التأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص533–546.","url":""}]},{"id":"s5-422","number":422,"surah":5,"verses":[83],"verseLabel":"المائدة: 83","question":"ما دلالة قوله تعالى: ﴿مما عرفوا من الحق﴾ دون الاقتصار على ذكر سماع القرآن؟","answer":"لأن البكاء لم ينشأ من مجرد الصوت، بل من معرفتهم أن المنزل حق يوافق بشارات الوحي وما بقي عندهم من العلم؛ فربط الأثر بالبصيرة والتصديق، لا بالسماع العاطفي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص533–546.","url":""}]},{"id":"s5-423","number":423,"surah":5,"verses":[83],"verseLabel":"المائدة: 83","question":"ما دلالة انتقالهم من السماع مباشرة إلى قولهم: ﴿ربنا آمنا فاكتبنا مع الشاهدين﴾؟","answer":"لأن معرفتهم الحق أورثت تصديقًا بلا تردد، فترجموا تأثر العين إلى إقرار اللسان وعهد مع الله. والفاء في ﴿فاكتبنا﴾ تصل ثمرة الإيمان بطلب تثبيتهم في جماعة الشاهدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص533–546.","url":""}]},{"id":"s5-424","number":424,"surah":5,"verses":[83],"verseLabel":"المائدة: 83","question":"ما دلالة طلبهم: ﴿فاكتبنا مع الشاهدين﴾؟","answer":"طلبوا أن يثبتهم الله مع أمة محمد ﷺ التي تشهد للرسل بالبلاغ وتشهد بوحدانية الله وصدق وحيه؛ فليس المطلوب مجرد اسم، بل منزلة من أعلن الحق وقام بشهادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص533–546.","url":""}]},{"id":"s5-425","number":425,"surah":5,"verses":[84],"verseLabel":"المائدة: 84","question":"ما دلالة قولهم: ﴿وما لنا لا نؤمن بالله وما جاءنا من الحق﴾؟","answer":"الاستفهام إنكاري ينفي وجود مانع معقول من الإيمان بعد معرفة الحق؛ فكأنهم يقولون: أي عذر يبقى لنا في تركه؟ وفيه رد على من لامهم أو حاول صدهم عن إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص547–551.","url":""}]},{"id":"s5-426","number":426,"surah":5,"verses":[84],"verseLabel":"المائدة: 84","question":"ما دلالة قولهم بعد الإيمان: ﴿ونطمع أن يدخلنا ربنا مع القوم الصالحين﴾؟","answer":"عبروا بالطمع تواضعًا وأدبًا؛ فلم يجعلوا إقرارهم موجبًا حتميًا للجنة، بل جمعوا العمل والرجاء في فضل ربهم. وإضافة الرب إليهم تشعر برحمته وتربيته التي يرجون بها الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص547–551.","url":""}]},{"id":"s5-427","number":427,"surah":5,"verses":[83,84],"verseLabel":"المائدة: 83–84","question":"ما الفرق بين طلب المعية في ﴿مع الشاهدين﴾ و﴿مع القوم الصالحين﴾؟","answer":"طلبوا أولًا الثبات مع الشاهدين بالحق في الدنيا، ثم طمعوا في المآل مع الصالحين الذين استحقوا رضوان الله؛ فجمعت المعيتان وظيفة الإيمان في الشهادة وثمرته في حسن الصحبة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص547–551.","url":""}]},{"id":"s5-428","number":428,"surah":5,"verses":[85],"verseLabel":"المائدة: 85","question":"ما دلالة قوله تعالى: ﴿فأثابهم الله بما قالوا جنات﴾، مع أن الثواب ليس على مجرد القول؟","answer":"قولهم كان إقرارًا صادقًا كشف ما استقر في قلوبهم من معرفة وإيمان، واقترن بما ظهر من خشوعهم؛ فذكر القول لأنه الصورة المعلنة لتصديقهم، لا لأن لفظًا مجردًا من الاعتقاد والعمل يوجب الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص552–556.","url":""}]},{"id":"s5-429","number":429,"surah":5,"verses":[85],"verseLabel":"المائدة: 85","question":"ما دلالة وصف الجنات بقوله تعالى: ﴿تجري من تحتها الأنهار خالدين فيها﴾؟","answer":"جريان الأنهار يدل على حياة الجنات ودوام خصبها ونعيمها، ثم دفع ﴿خالدين فيها﴾ احتمال انقطاع هذا النعيم أو مفارقتهم له؛ فجمع كمال المكان ودوام الإقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص552–556.","url":""}]},{"id":"s5-430","number":430,"surah":5,"verses":[85],"verseLabel":"المائدة: 85","question":"ما دلالة ختم الآية بقوله تعالى: ﴿وذلك جزاء المحسنين﴾ دون: المؤمنين؟","answer":"لأن موقفهم تجاوز أصل التصديق إلى حسن الاستماع ومعرفة الحق والخشوع وإعلان الشهادة؛ فناسبهم وصف الإحسان الذي يجمع صحة الإيمان وحسن الاستجابة والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص552–556.","url":""}]},{"id":"s5-431","number":431,"surah":5,"verses":[86],"verseLabel":"المائدة: 86","question":"ما دلالة الجمع بين قوله تعالى: ﴿كفروا﴾ وقوله: ﴿وكذبوا بآياتنا﴾؟","answer":"الكفر وصف لأصل موقفهم من الحق، والتكذيب بالآيات مظهر محدد لهذا الكفر حين جحدوا دلائل الله ووحيه؛ فجمع الباطن الجامع والفعل الذي كشفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص557–560.","url":""}]},{"id":"s5-432","number":432,"surah":5,"verses":[86],"verseLabel":"المائدة: 86","question":"ما دلالة قوله تعالى: ﴿أولئك أصحاب الجحيم﴾ في مقابل جزاء المحسنين؟","answer":"اسم الإشارة يميزهم ببعد منزلتهم، و﴿أصحاب﴾ تفيد ملازمة الجحيم لهم كما يلازم الصاحب صاحبه؛ فجاء الجزاء المقابل: أولئك في نار ملازمة، بعد جنات الخلود للمحسنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص557–560.","url":""}]},{"id":"s5-433","number":433,"surah":5,"verses":[87],"verseLabel":"المائدة: 87","question":"ما مناسبة النهي عن تحريم الطيبات بعد ذكر النصارى الذين قربوا مودة؟","answer":"لئلا يحمل الثناء على خشوع فريق من النصارى المؤمنين بعض المسلمين على تقليد الرهبانية وترك المباحات تقربًا؛ فصحح السياق الميزان: يُقبل تواضعهم للحق، ولا يُتبع ما أحدث من تحريم الطيبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–569.","url":""}]},{"id":"s5-434","number":434,"surah":5,"verses":[87],"verseLabel":"المائدة: 87","question":"ما دلالة الجمع بين النهي عن تحريم الطيبات والنهي عن الاعتداء؟","answer":"تحريم ما أحل الله اعتداء على حق التشريع، وقد يكون الاعتداء أيضًا بمجاوزة حد الاعتدال في تناول المباح؛ فجمعت الآية منع التضييق بلا دليل ومنع التجاوز في الاستعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–569.","url":""}]},{"id":"s5-435","number":435,"surah":5,"verses":[87],"verseLabel":"المائدة: 87","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يحب المعتدين﴾؟","answer":"الخاتمة تعلل النهي: من تجاوز حدود الله بتحريم حلال أو تعدي حد الاعتدال حرم محبته؛ وتسميتهم ﴿المعتدين﴾ تجعل الحكم متعلقًا بوصف التجاوز نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–569.","url":""}]},{"id":"s5-436","number":436,"surah":5,"verses":[88],"verseLabel":"المائدة: 88","question":"ما دلالة الأمر بقوله تعالى: ﴿وكلوا مما رزقكم الله حلالًا طيبًا﴾ بعد النهي عن التحريم؟","answer":"لم يكتف برفع التحريم، بل أمر بالانتفاع برزق الله شكرًا له وإبطالًا للتقرب بتركه؛ و﴿مما﴾ تفيد تناول بعض الرزق في حدود الحاجة والاعتدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–569.","url":""}]},{"id":"s5-437","number":437,"surah":5,"verses":[88],"verseLabel":"المائدة: 88","question":"ما الفرق بين ﴿حلالًا﴾ و﴿طيبًا﴾ في وصف الرزق؟","answer":"الحلال ما أذن الشرع في تناوله، والطيب ما كان مستلذًا نافعًا خاليًا من الخبث والضرر؛ فاجتماعهما يطلب سلامة طريق الكسب والحكم، وسلامة ذات المأكول وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–569.","url":""}]},{"id":"s5-438","number":438,"surah":5,"verses":[88],"verseLabel":"المائدة: 88","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿واتقوا الله الذي أنتم به مؤمنون﴾؟","answer":"الإيمان بالله يوجب تقواه في حدوده: فلا يحرموا ما أحل، ولا يتناولوا ما حرم، ولا يسرفوا في الحلال. والموصول ﴿الذي أنتم به مؤمنون﴾ يستنهض إيمانهم ليظهر أثره في الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–569.","url":""}]},{"id":"s5-439","number":439,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما الفرق بين لغو اليمين واليمين المعقودة في قوله تعالى: ﴿لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما عقدتم الأيمان﴾؟","answer":"لغو اليمين ما يجري على اللسان من غير قصد جازم إلى الحلف، فلا مؤاخذة به؛ أما ما عُقد بالقصد وتوثقت به إرادة الحالف فتتعلق به المسؤولية والكفارة عند الحنث. و﴿لكن﴾ تفصل محل العفو من محل المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-440","number":440,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما دلالة اختيار فعل ﴿عقدتم﴾ للأيمان؟","answer":"استعار العقد الحسي لربط القلب بالقصد وتوثيق اليمين، كأن الحالف شد على نفسه عهدًا لا ينحل بلا وفاء أو كفارة؛ فهو أبلغ من مجرد النطق بالحلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-441","number":441,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما دلالة التخيير بين الإطعام والكسوة وتحرير الرقبة في كفارة اليمين؟","answer":"عطفها بـ﴿أو﴾ يجعلها بدائل متساوية في أصل الإجزاء، يختار المكفّر واحدًا منها بحسب استطاعته؛ فلا يدل ترتيب الذكر على وجوب البدء بالإطعام ثم الانتقال. ثم ينتقل إلى الصيام عند العجز عن هذه الخصال المالية كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-442","number":442,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما دلالة تقييد الإطعام بقوله تعالى: ﴿من أوسط ما تطعمون أهليكم﴾؟","answer":"أوجب من الطعام المعتاد المتوسط الذي يقدمه الإنسان لأهله، فلا يجزئ الرديء الذي يترفعون عنه، ولا يكلف بأرفع ما يأكلون؛ فجمع التكليف الكرامة واليسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-443","number":443,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما دلالة قوله تعالى: ﴿فمن لم يجد فصيام ثلاثة أيام﴾ مع عدم ذكر التتابع؟","answer":"ظاهر الآية أطلق صيام الأيام الثلاثة ولم يقيده بالتتابع، ولذلك وقع الخلاف الفقهي تبعًا للأدلة والقراءات الواردة خارج هذا اللفظ؛ فلا يصح إضافة شرط التتابع إلى نص الآية نفسها من غير بيان مستنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-444","number":444,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما دلالة تكرار ذكر الأيمان في قوله تعالى: ﴿كفارة أيمانكم إذا حلفتم واحفظوا أيمانكم﴾؟","answer":"تعلق كل ذكر بجهة: الأول يبين ما تجبر به الأيمان عند الحنث، والثاني يحدد زمن انعقاد سبب الكفارة، والثالث يأمر بصيانة الأيمان؛ فليس التكرار إعادة، بل إحاطة بالعقد والحنث والحفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-445","number":445,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما مناسبة الأمر بقوله تعالى: ﴿واحفظوا أيمانكم﴾ بعد بيان الكفارة؟","answer":"حتى لا تتحول الكفارة إلى ذريعة للإكثار من الحلف والحنث؛ فحفظ اليمين يكون بتقليل الحلف، والصدق فيه، والوفاء بما لا معصية فيه، وأداء الكفارة إذا وقع الحنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-446","number":446,"surah":5,"verses":[89],"verseLabel":"المائدة: 89","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كذلك يبين الله لكم آياته لعلكم تشكرون﴾؟","answer":"تفصيل أنواع اليمين والكفارة تيسير وبيان يحفظ الدين والحقوق ويفتح مخرجًا من الحنث؛ فناسب أن تكون غايته الشكر بالاعتراف بالنعمة والعمل بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص570–591.","url":""}]},{"id":"s5-447","number":447,"surah":5,"verses":[90],"verseLabel":"المائدة: 90","question":"ما مناسبة جمع الخمر والميسر والأنصاب والأزلام في حكم واحد؟","answer":"جمعها أنها رجس من عمل الشيطان: فالخمر تفسد العقل، والميسر يأكل المال ويثير الخصومة، والأنصاب والأزلام من شعائر الشرك والخرافة؛ وكلها تصرف عن عبادة الله وتفتح باب العداوة والفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص592–602.","url":""}]},{"id":"s5-448","number":448,"surah":5,"verses":[90],"verseLabel":"المائدة: 90","question":"ما دلالة وصف الخمر والميسر والأنصاب والأزلام بأنها ﴿رجس من عمل الشيطان﴾ دون الاكتفاء بذكر التحريم؟","answer":"﴿رجس﴾ ينفر منها بوصفها خبثًا مستقذرًا في آثارها الدينية والعقلية والاجتماعية، وإضافتها إلى عمل الشيطان تكشف مصدر تزيينها وغايته؛ فصار النهي عنها قائمًا على بيان حقيقتها لا على الحكم المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص592–602.","url":""}]},{"id":"s5-449","number":449,"surah":5,"verses":[90],"verseLabel":"المائدة: 90","question":"ما سرّ إفراد ﴿رجس﴾ مع تعدد الخمر والميسر والأنصاب والأزلام؟","answer":"﴿رجس﴾ مصدر أو اسم جنس يستوي فيه المفرد والجمع، وقد جعلت المذكورات كلها جنسًا واحدًا في الخبث والحكم؛ لذلك صح الإخبار عنها بالمفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص592–602.","url":""}]},{"id":"s5-450","number":450,"surah":5,"verses":[90],"verseLabel":"المائدة: 90","question":"ما دلالة الأمر بقوله تعالى: ﴿فاجتنبوه﴾ بدل: فاتركوه؟","answer":"الاجتناب جعل الشيء في جانب والإنسان في جانب آخر؛ فهو أبلغ من مجرد ترك الفعل، إذ يقتضي البعد عن العين والوسائل والمجالس التي تجر إليه، ويغلق ذرائع الوقوع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص592–602.","url":""}]},{"id":"s5-451","number":451,"surah":5,"verses":[90],"verseLabel":"المائدة: 90","question":"إلى ماذا يعود الضمير المفرد في قوله تعالى: ﴿فاجتنبوه﴾؟","answer":"يعود إلى ﴿رجس﴾ المذكور مفردًا، وهو وصف جامع للخمر والميسر والأنصاب والأزلام؛ فاجتناب الرجس يقتضي اجتناب جميع أفراده، ولا يختص بواحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص592–602.","url":""}]},{"id":"s5-452","number":452,"surah":5,"verses":[90],"verseLabel":"المائدة: 90","question":"ما مناسبة ختم الأمر بالاجتناب بقوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"جعل الفلاح ثمرة اجتناب هذه الرجاسات؛ لأنه يجمع النجاة من أضرارها والفوز برضا الله. و﴿لعل﴾ تستنهض الرجاء والعمل، فلا فلاح مع الإصرار على ما يفسد الدين والعقل والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص592–602.","url":""}]},{"id":"s5-453","number":453,"surah":5,"verses":[91],"verseLabel":"المائدة: 91","question":"ما دلالة قوله تعالى: ﴿إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء في الخمر والميسر﴾؟","answer":"القصر يكشف المقصد الخفي وراء تزيين الخمر والميسر: إيقاع العداوة الظاهرة والبغضاء الباطنة بين الناس، ثم صدهم عن ذكر الله والصلاة. فحوّل النظر من لذة عاجلة إلى خطة الشيطان وعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص603–614.","url":""}]},{"id":"s5-454","number":454,"surah":5,"verses":[91],"verseLabel":"المائدة: 91","question":"ما سرّ تقديم العداوة والبغضاء على الصد عن ذكر الله والصلاة؟","answer":"بدأ بالأثر الاجتماعي المشاهد الذي يعرفونه من نزاع السكر والقمار، ثم ارتقى إلى الأثر الديني الأخطر: قطع الصلة بالله. فاحتج بما تدركه التجربة أولًا ليفضي إلى ما هو أعظم في ميزان الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص603–614.","url":""}]},{"id":"s5-455","number":455,"surah":5,"verses":[91],"verseLabel":"المائدة: 91","question":"ما دلالة قوله تعالى: ﴿في الخمر والميسر﴾ دون: بالخمر والميسر؟","answer":"جعل الخمر والميسر كأنهما مجال تتحرك داخله العداوة والبغضاء وتنشآن في ملابساته، لا مجرد أداتين منفصلتين؛ فـ﴿في﴾ تصور إحاطة آثارهما بمن يمارسهما ورسوخ الفساد فيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص603–614.","url":""}]},{"id":"s5-456","number":456,"surah":5,"verses":[91],"verseLabel":"المائدة: 91","question":"ما دلالة الجمع بين ﴿ذكر الله﴾ و﴿الصلاة﴾ مع دخول الصلاة في الذكر؟","answer":"ذكر الله أعم من الصلاة، ثم خُصت الصلاة بعده لشرفها وانتظامها في أوقات معلومة وكونها عماد الصلة بالله؛ فذكر الخاص بعد العام يبرز شدة ما تضيعه الخمر والميسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص603–614.","url":""}]},{"id":"s5-457","number":457,"surah":5,"verses":[91],"verseLabel":"المائدة: 91","question":"ما دلالة ختم الآية بالاستفهام: ﴿فهل أنتم منتهون﴾ بدل الأمر المباشر؟","answer":"الاستفهام يبلغ غاية الحث والتقرير بعد اكتمال أسباب التحريم، فلا يترك للمخاطب جوابًا يليق إلا إعلان الانتهاء. ولذلك كان أوقع في النفس من أمر مجرد، وقد تلقاه المؤمنون بقولهم: انتهينا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص603–614.","url":""}]},{"id":"s5-458","number":458,"surah":5,"verses":[92],"verseLabel":"المائدة: 92","question":"ما دلالة تكرار فعل الطاعة في قوله تعالى: ﴿وأطيعوا الله وأطيعوا الرسول﴾؟","answer":"إعادة ﴿أطيعوا﴾ تؤكد أن طاعة الرسول واجبة في تبليغه وبيانه وأمره، كما تجب طاعة الله، وإن كانت طاعته من طاعة الله؛ فليست سنته تابعة لاختيار الناس بعد ورود أصل الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص615–626.","url":""}]},{"id":"s5-459","number":459,"surah":5,"verses":[92],"verseLabel":"المائدة: 92","question":"ما دلالة قوله تعالى: ﴿واحذروا﴾ مع حذف المحذور؟","answer":"حذف متعلق الحذر ليعم كل ما ينبغي اتقاؤه: مخالفة الأمر، والعودة إلى المحرمات، وفتنة الشيطان، وعاقبة التولي؛ فالإطلاق أشد إيقاظًا من تسمية خطر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص615–626.","url":""}]},{"id":"s5-460","number":460,"surah":5,"verses":[92],"verseLabel":"المائدة: 92","question":"ما دلالة قوله تعالى: ﴿فإن توليتم فاعلموا أنما على رسولنا البلاغ المبين﴾؟","answer":"الشرط يحمل المتولين مسؤولية إعراضهم؛ فقد حصر واجب الرسول ﷺ في البلاغ الواضح وقد أداه، وليس عليه إكراههم على القبول. وفي الأمر ﴿فاعلموا﴾ تهديد بأن التولي بعد البيان لا عذر معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص615–626.","url":""}]},{"id":"s5-461","number":461,"surah":5,"verses":[92],"verseLabel":"المائدة: 92","question":"ما دلالة إضافة الرسول إلى ضمير العظمة في قوله تعالى: ﴿رسولنا﴾؟","answer":"الإضافة تشرف الرسول ﷺ وتقرر أن سلطانه في البلاغ مستمد من مرسله؛ فمن تولى عنه فقد تولى عن رسالة الله، كما تشعر بأن الله ناصره وشاهد على أدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص615–626.","url":""}]},{"id":"s5-462","number":462,"surah":5,"verses":[92],"verseLabel":"المائدة: 92","question":"ما دلالة وصف البلاغ بأنه ﴿المبين﴾؟","answer":"المبين هو الواضح في نفسه والمظهر لما يحتاج الناس إلى معرفته؛ فنفى الوصف أن يكون توليهم ناشئًا من غموض الرسالة، وأقام عليهم الحجة بعد تمام البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص615–626.","url":""}]},{"id":"s5-463","number":463,"surah":5,"verses":[12],"verseLabel":"المائدة: 92؛ التغابن: 12","question":"ما سرّ زيادة ﴿واحذروا﴾ و﴿فاعلموا﴾ في المائدة، وعدم ذكرهما في الآية المشابهة من التغابن؟","answer":"جاءت آية المائدة عقب تحريم الخمر والميسر وما ألفه الناس منهما، فاحتاج المقام إلى تحذير زائد من المخالفة وإلى أمرهم أن يعلموا تمام مسؤوليتهم بعد البلاغ. أما التغابن فساق أصل الطاعة والتولي في سياق عام، فناسبه الإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج62، ص204–208.","url":""}]},{"id":"s5-464","number":464,"surah":5,"verses":[93],"verseLabel":"المائدة: 93","question":"ما دلالة نفي الجناح عما طعمه المؤمنون قبل التحريم؟","answer":"رفع الحرج عمن شرب الخمر أو تناول ما كان مباحًا قبل نزول التحريم ثم امتثل؛ لأن الأحكام لا تؤاخذ الناس قبل بيانها. وسمّى التناول ﴿طعموا﴾ ليعم ما أكلوه وشربوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص627–636.","url":""}]},{"id":"s5-465","number":465,"surah":5,"verses":[93],"verseLabel":"المائدة: 93","question":"ما دلالة تكرار التقوى وتدرج الأوصاف في قوله تعالى: ﴿إذا ما اتقوا وآمنوا وعملوا الصالحات ثم اتقوا وآمنوا ثم اتقوا وأحسنوا﴾؟","answer":"التكرار يصور التقوى درجات متجددة لا موقفًا واحدًا: اتقوا المحرم بعد بيانه مع الإيمان والعمل الصالح، ثم ثبتوا على التقوى والإيمان، ثم ترقوا إلى الإحسان. و﴿ثم﴾ تفيد الانتقال في مراتب الاستقامة حتى كمال المراقبة والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص627–636.","url":""}]},{"id":"s5-466","number":466,"surah":5,"verses":[93],"verseLabel":"المائدة: 93","question":"ما دلالة ختم التدرج بالإحسان في قوله تعالى: ﴿ثم اتقوا وأحسنوا﴾؟","answer":"الإحسان مرتبة يتجاوز فيها المؤمن مجرد ترك الحرام إلى إتقان الطاعة وفعل الخير ومراقبة الله؛ فناسب أن يكون غاية التدرج بعد الإيمان والتقوى والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص627–636.","url":""}]},{"id":"s5-467","number":467,"surah":5,"verses":[93],"verseLabel":"المائدة: 93","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله يحب المحسنين﴾؟","answer":"لما انتهى التدرج إلى الإحسان، ختم بالجزاء الموافق له وهو محبة الله؛ فشجعت الخاتمة على بلوغ أعلى من مجرد السلامة من الجناح إلى مقام يحبه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص627–636.","url":""}]},{"id":"s5-468","number":468,"surah":5,"verses":[94],"verseLabel":"المائدة: 94","question":"ما دلالة وصف الابتلاء بقوله تعالى: ﴿بشيء من الصيد﴾؟","answer":"التنكير والتبعيض في ﴿بشيء﴾ يشعران بأن الابتلاء جزء يسير من الصيد ووقت محدود هو الإحرام، مع بقاء وجوه واسعة من المباح؛ وفي ذلك إظهار لضعف المعتدي رغم خفة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص637–647.","url":""}]},{"id":"s5-469","number":469,"surah":5,"verses":[94],"verseLabel":"المائدة: 94","question":"ما دلالة كون الصيد المبتلى به مما ﴿تناله أيديكم ورماحكم﴾؟","answer":"جُعل الصيد قريب المنال ليصدق الاختبار مع وجود الداعي والقدرة: ما تدركه الأيدي من صغيره وقريبه، وما تصل إليه الرماح من كبيره وبعيده؛ فشمل أدوات الصيد ودرجات سهولته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص637–647.","url":""}]},{"id":"s5-470","number":470,"surah":5,"verses":[94],"verseLabel":"المائدة: 94","question":"كيف نفهم قوله تعالى: ﴿ليعلم الله من يخافه بالغيب﴾ مع سبق علم الله بكل شيء؟","answer":"ليس المراد حدوث علم لم يكن، بل ظهور المعلوم في واقع العمل ليتميز المطيع من المعتدي ويقوم عليه الجزاء والحجة؛ فعلم الله السابق يتعلق بما سيكون، والابتلاء يظهره فعلًا مشاهدًا من العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص637–647.","url":""}]},{"id":"s5-471","number":471,"surah":5,"verses":[94],"verseLabel":"المائدة: 94","question":"ما دلالة التعبير عن الطاعة في الخلوة بقوله تعالى: ﴿يخافه بالغيب﴾؟","answer":"أي يخاف الله وهو غائب عن أعين الناس، ويخافه مع أنه لا يراه؛ فيمتنع عن الصيد الممكن من وازع الإيمان لا من رقابة بشرية. وهذا هو موضع صدق الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص637–647.","url":""}]},{"id":"s5-472","number":472,"surah":5,"verses":[94],"verseLabel":"المائدة: 94","question":"ما دلالة قوله تعالى: ﴿فمن اعتدى بعد ذلك فله عذاب أليم﴾؟","answer":"﴿بعد ذلك﴾ أي بعد بيان التحريم وإقامة اختبار الطاعة، فالاعتداء بعد العلم أشد استحقاقًا للوعيد. وتقديم ﴿له﴾ يثبت اختصاصه بالعاقبة التي كسبها، ووصف العذاب بالأليم يناسب تعمد تجاوز الحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص637–647.","url":""}]},{"id":"s5-473","number":473,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة النهي بقوله تعالى: ﴿لا تقتلوا الصيد وأنتم حرم﴾ دون: لا تصيدوا؟","answer":"تعلق النهي بقتل الصيد ليشمل إزهاق روحه بأي وسيلة، سواء باصطياد مباشر أو إعانة أو فعل آخر؛ فالعبرة بحماية حيوان البر في حال الإحرام، لا بصورة المطاردة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-474","number":474,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة تقييد الحكم بقوله تعالى: ﴿ومن قتله منكم متعمدًا﴾؟","answer":"ذكر التعمد لأنه محل الإثم والوعيد بـ﴿فينتقم الله منه﴾، ولأنه أظهر صور الاعتداء على حرمة الإحرام. أما حكم الخطأ وتفاصيل الضمان ففيه خلاف فقهي وأدلة أخرى، فلا يستخرج نفيه من هذا القيد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-475","number":475,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة جعل الجزاء ﴿مثل ما قتل من النعم﴾؟","answer":"أقام الجزاء على المماثلة بين الصيد المقتول وحيوان من الأنعام يقاربه في الخلقة أو القيمة بحسب الحكم؛ ليشعر المعتدي بمقدار ما أتلف، ويتحقق عدل التعويض من غير جزاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-476","number":476,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة اشتراط أن يحكم بالمثل ﴿ذوا عدل منكم﴾؟","answer":"لأن تقدير المماثلة قد يختلف باختلاف الصيد، فاحتاج إلى اثنين يجمعان الخبرة والعدالة حتى يبتعد الحكم عن هوى الجاني أو اجتهاد الفرد المنفرد، ويطمأن إلى تقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-477","number":477,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة وصف الجزاء بقوله تعالى: ﴿هديًا بالغ الكعبة﴾؟","answer":"جعله ﴿هديًا﴾ ينقل المثل من مجرد غرامة إلى قربان يُهدى لله، و﴿بالغ الكعبة﴾ كناية عن وصوله إلى الحرم وذبحه في موضعه الشرعي؛ فجمع التعويض وتعظيم شعائر البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-478","number":478,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة التخيير بين الهدي وإطعام المساكين وعدل ذلك صيامًا؟","answer":"نوّعت الكفارة بين مثل الصيد من النعم، أو ما يقابله من إطعام المساكين، أو ما يعادل الطعام صيامًا؛ لتبقى المؤاخذة محققة مع اختلاف قدرة المكلف وصورة الجبر، ويضبط التعادل حتى لا تصير البدائل مهربًا من تبعة الجناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-479","number":479,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة تعليل الكفارة بقوله تعالى: ﴿ليذوق وبال أمره﴾؟","answer":"الذوق استعارة للإحساس المباشر بعاقبة الفعل، و﴿وبال أمره﴾ سوء نتيجته وثقله؛ فالكفارة ليست تعويضًا مجردًا، بل تربية تجعل المعتدي يباشر أثر مخالفته فيرتدع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-480","number":480,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما دلالة المقابلة في قوله تعالى: ﴿عفا الله عما سلف ومن عاد فينتقم الله منه﴾؟","answer":"فتح العفو لما وقع قبل البيان أو من الزلة الماضية، وقابله بوعيد من يعود بعد العلم بالحكم؛ فجمع الرحمة في الماضي والحزم مع الإصرار، ودلت الفاء والمضارع على ترتب الانتقام على العود.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-481","number":481,"surah":5,"verses":[95],"verseLabel":"المائدة: 95","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله عزيز ذو انتقام﴾؟","answer":"﴿عزيز﴾ غالب لا يفلت المعتدي من قدرته، و﴿ذو انتقام﴾ يجازي المصر بعد العفو والبيان بما يردعه؛ فناسب الاسمان وعيد من عاد إلى انتهاك الحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص648–674.","url":""}]},{"id":"s5-482","number":482,"surah":5,"verses":[96],"verseLabel":"المائدة: 96","question":"ما الفرق بين ﴿صيد البحر﴾ و﴿طعامه﴾ في قوله تعالى: ﴿أحل لكم صيد البحر وطعامه﴾؟","answer":"صيد البحر ما أُخذ منه حيًا بالصيد، وطعامه ما يؤكل منه مما قذفه البحر أو مات فيه، وقيل ما أُعد منه وحُفظ زادًا؛ وعلى الوجهين عطف الطعام يوسع الإباحة لتتجاوز مباشرة الصيد الطازج.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص675–682.","url":""}]},{"id":"s5-483","number":483,"surah":5,"verses":[96],"verseLabel":"المائدة: 96","question":"ما دلالة قوله تعالى: ﴿متاعًا لكم وللسيارة﴾ مع دخول المسافرين في عموم ﴿لكم﴾؟","answer":"خص السيارة، أي المسافرين، بعد العموم لأنهم أشد انتفاعًا بصيد البحر وطعامه في الطريق، ولا سيما ما يُدخر منه زادًا؛ فهو ذكر للخاص بعد العام لإبراز الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص675–682.","url":""}]},{"id":"s5-484","number":484,"surah":5,"verses":[96],"verseLabel":"المائدة: 96","question":"ما سرّ مقابلة حل صيد البحر بتحريم ﴿صيد البر﴾ دون: طعام البر؟","answer":"المحرم حال الإحرام هو التعرض لصيد البر وقتله، لا مطلق أكل كل طعام أصله من البر؛ فقد يؤكل بشروط إذا لم يصده المحرم ولم يُصد لأجله. لذلك تعلق التحريم بالصيد، بينما فُصل صيد البحر وطعامه لتوكيد سعة إباحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص675–682.","url":""}]},{"id":"s5-485","number":485,"surah":5,"verses":[1,96],"verseLabel":"المائدة: 1، 96","question":"ما مناسبة إعادة قيد ﴿ما دمتم حرمًا﴾ في تحريم صيد البر؟","answer":"ورد القيد أول السورة ضمن إجمال أحكام الأنعام والصيد، وأعيد هنا بعد تفصيل إباحة البحر لتحديد زمن تحريم صيد البر ومنع توهم مساواته بالبحر؛ فالأول تأسيس والآخر ضبط للمقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص675–682.","url":""}]},{"id":"s5-486","number":486,"surah":5,"verses":[96],"verseLabel":"المائدة: 96","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿واتقوا الله الذي إليه تحشرون﴾؟","answer":"لأن حكم الصيد قد يختبر المكلف بعيدًا عن رقابة الناس، فذُكر بالحشر إلى الله الذي يحاسبه على امتثاله؛ ووصف الموصول يجعل الإيمان بالرجوع إليه باعثًا على التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص675–682.","url":""}]},{"id":"s5-487","number":487,"surah":5,"verses":[97],"verseLabel":"المائدة: 97","question":"ما معنى جعل الكعبة ﴿قيامًا للناس﴾ في قوله تعالى: ﴿جعل الله الكعبة البيت الحرام قيامًا للناس﴾؟","answer":"أي جعلها ما تقوم به مصالح دينهم ودنياهم: قبلةً وموضع حج وعبادة، وأمنًا يجتمعون عنده، وسببًا لتعارفهم وتجارتهم. و﴿قيامًا﴾ يصورها دعامة تنتظم بها شؤونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص683–694.","url":""}]},{"id":"s5-488","number":488,"surah":5,"verses":[97],"verseLabel":"المائدة: 97","question":"ما مناسبة عطف الشهر الحرام والهدي والقلائد على الكعبة؟","answer":"لأن قيام مصالح الناس لا يتم بالمكان وحده، بل بمنظومة الحرمة حوله: زمن آمن هو الشهر الحرام، ونسك يصل إليه هو الهدي، وعلامة تصونه في الطريق هي القلائد؛ فجمعت الآية المكان والزمان والشعيرة وعلامتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص683–694.","url":""}]},{"id":"s5-489","number":489,"surah":5,"verses":[2,97],"verseLabel":"المائدة: 2، 97","question":"ما مناسبة إعادة ذكر ﴿القلائد﴾ بعد ورودها في الآية 2؟","answer":"ذُكرت أول السورة في سياق النهي عن انتهاك شعائر الله والهدي المقلد، ثم أعيدت هنا ضمن ما جعله الله قيامًا للناس؛ فالأول يحمي حرمتها بحكم عملي، والثاني يبين موقعها في نظام الأمن والحج.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص683–694.","url":""}]},{"id":"s5-490","number":490,"surah":5,"verses":[97],"verseLabel":"المائدة: 97","question":"ما دلالة تعليل هذه الشعائر بقوله تعالى: ﴿ذلك لتعلموا أن الله يعلم ما في السماوات وما في الأرض﴾؟","answer":"ما أودعه الله في الكعبة والأشهر والهدي من مصالح دقيقة لمختلف الناس والأزمان دليل على علمه المحيط بأحوال خلقه وحاجاتهم؛ فحكمة التشريع طريق إلى معرفة سعة علم المشرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص683–694.","url":""}]},{"id":"s5-491","number":491,"surah":5,"verses":[97],"verseLabel":"المائدة: 97","question":"ما دلالة الجمع بين قوله تعالى: ﴿يعلم ما في السماوات وما في الأرض﴾ وقوله: ﴿وأن الله بكل شيء عليم﴾؟","answer":"الأول يصرح بإحاطة علمه بأعظم عالمي الخلق وما فيهما، ثم جاء العام ﴿بكل شيء عليم﴾ ليمنع توهم اختصاص العلم بهما أو ببعض ما فيهما، ويقرر القاعدة الشاملة بعد المثال الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص683–694.","url":""}]},{"id":"s5-492","number":492,"surah":5,"verses":[98],"verseLabel":"المائدة: 98","question":"ما دلالة الجمع بين قوله تعالى: ﴿أن الله شديد العقاب﴾ وقوله: ﴿وأن الله غفور رحيم﴾؟","answer":"جمع الترهيب والترغيب ليبقى المكلف بين الخوف والرجاء: شدة العقاب لمن انتهك الحدود وأصر، والمغفرة والرحمة لمن تاب وأطاع. فلا أمن من الجزاء ولا قنوط من الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص695–700.","url":""}]},{"id":"s5-493","number":493,"surah":5,"verses":[98],"verseLabel":"المائدة: 98","question":"ما سرّ تقديم ﴿شديد العقاب﴾ على ﴿غفور رحيم﴾؟","answer":"جاء السياق عقب أحكام تحريم الصيد ووعيد العائد وتعظيم حرمات الكعبة، فناسب أن يقدم التحذير من انتهاكها، ثم أتبع بالمغفرة والرحمة حتى لا يغلق باب التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص695–700.","url":""}]},{"id":"s5-494","number":494,"surah":5,"verses":[98],"verseLabel":"المائدة: 98","question":"ما دلالة إعادة اسم الله في قوله تعالى: ﴿أن الله شديد العقاب وأن الله غفور رحيم﴾ بدل الإضمار؟","answer":"إعادة الاسم الجليل تجعل كل جملة أصلًا مستقلًا مؤكدًا: فالله نفسه شديد العقاب، وهو نفسه غفور رحيم. وبذلك تتوازن صفتا الجلال والجمال من غير أن تبدو الثانية تابعة عارضة للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص695–700.","url":""}]},{"id":"s5-495","number":495,"surah":5,"verses":[99],"verseLabel":"المائدة: 99","question":"ما دلالة القصر في قوله تعالى: ﴿ما على الرسول إلا البلاغ﴾؟","answer":"حصر واجب الرسول ﷺ في إيصال الرسالة، فلا يملك إجبار القلوب على الإيمان ولا يحمل وزر من أعرض بعد البيان؛ وفي الوقت نفسه يحمل المخاطبين مسؤولية الاستجابة لأن الحجة قد بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص701–707.","url":""}]},{"id":"s5-496","number":496,"surah":5,"verses":[92,99],"verseLabel":"المائدة: 92، 99","question":"ما سرّ الاقتصار على ﴿البلاغ﴾ هنا، ووصفه في الآية 92 بأنه ﴿البلاغ المبين﴾؟","answer":"في الآية 92 جاء الوعيد عقب أمر الطاعة والتحذير من التولي، فزيد ﴿المبين﴾ لإقامة الحجة بأن البلاغ كان واضحًا. أما هنا فالمقام يقرر أصل وظيفة الرسول بعد الأمر بالعلم، فالتعريف في ﴿البلاغ﴾ يستغرق البلاغ المعروف الكامل، ووصفه بالبيان معلوم مما سبق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص701–707؛ ص615–626.","url":""}]},{"id":"s5-497","number":497,"surah":5,"verses":[99],"verseLabel":"المائدة: 99","question":"ما سرّ تقديم ما يُبدى على ما يُكتم في قوله تعالى: ﴿والله يعلم ما تبدون وما تكتمون﴾؟","answer":"قُدم الظاهر لأنه أول ما يواجه الرسول والناس وتقع عليه الأحكام، ثم ضم إليه الباطن الذي لا يعلمه إلا الله؛ فانتقل من المشاهد إلى الأخفى ليقرر إحاطة العلم بهما، ويحذر من مخالفة السر للعلن.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص701–707.","url":""}]},{"id":"s5-498","number":498,"surah":5,"verses":[100],"verseLabel":"المائدة: 100","question":"ما دلالة إطلاق ﴿الخبيث﴾ و﴿الطيب﴾ في قوله تعالى: ﴿لا يستوي الخبيث والطيب﴾ دون تعيين؟","answer":"أطلق اللفظان ليعمّا كل خبيث وطيب في الاعتقاد والقول والعمل والكسب والأشخاص؛ فالقاعدة لا تختص بطعام أو مال معين، والعبرة بحقيقة الشيء لا بمظهره أو كثرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص708–715.","url":""}]},{"id":"s5-499","number":499,"surah":5,"verses":[100],"verseLabel":"المائدة: 100","question":"ما سرّ تقديم ﴿الخبيث﴾ على ﴿الطيب﴾؟","answer":"لأن السياق يحذر من الاغترار بكثرة الخبيث، فبدأ به ليضع موضع الفتنة أمام السامع ثم نفى مساواته بالطيب؛ وبذلك مهد لقوله: ﴿ولو أعجبك كثرة الخبيث﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص708–715.","url":""}]},{"id":"s5-500","number":500,"surah":5,"verses":[100],"verseLabel":"المائدة: 100","question":"ما دلالة إفراد الخطاب في قوله تعالى: ﴿ولو أعجبك كثرة الخبيث﴾؟","answer":"الخطاب المفرد يواجه كل سامع بالحكم كأنه المقصود وحده، ويصح أن يكون للنبي ﷺ والمراد تعليم الأمة؛ فالإعجاب بالكثرة فتنة فردية لا يُعفى منها أحد باتباع الجمهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص708–715.","url":""}]},{"id":"s5-501","number":501,"surah":5,"verses":[100],"verseLabel":"المائدة: 100","question":"ما سرّ ذكر ﴿كثرة الخبيث﴾ دون وصف الطيب بالكثرة؟","answer":"لأن قيمة الطيب في طيبه ولو كان قليلًا، أما الخبيث فقد لا يملك ما يغري إلا الكثرة؛ فنفت الآية ميزان العدد وقررت أن القليل الطيب خير من الكثير الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص708–715.","url":""}]},{"id":"s5-502","number":502,"surah":5,"verses":[100],"verseLabel":"المائدة: 100","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فاتقوا الله يا أولي الألباب لعلكم تفلحون﴾؟","answer":"أولو الألباب هم القادرون على تجاوز بريق الكثرة إلى تمييز الطيب من الخبيث، والتقوى تحملهم على اختيار الطيب، والفلاح ثمرة هذا العقل العامل بالتقوى؛ فانتظمت الخاتمة من الإدراك إلى الامتثال ثم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص708–715.","url":""}]},{"id":"s5-503","number":503,"surah":5,"verses":[101],"verseLabel":"المائدة: 101","question":"ما دلالة النهي بقوله تعالى: ﴿لا تسألوا عن أشياء إن تبد لكم تسؤكم﴾؟","answer":"النهي عن أسئلة التعنت والتكلف وما لا حاجة إليه إذا كان كشف جوابه يجلب حرجًا أو تكليفًا أو فضيحة، وليس نهيًا عن سؤال التعلم الذي يحتاج إليه الدين؛ فالعلة بينتها جملة ﴿إن تبد لكم تسؤكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص716–729.","url":""}]},{"id":"s5-504","number":504,"surah":5,"verses":[101],"verseLabel":"المائدة: 101","question":"ما دلالة تنكير ﴿أشياء﴾ وعدم تحديدها؟","answer":"التنكير يعم كل مسألة تتصف بأن إبداءها يسوء السائل، ويترك الباب غير مقصور على الوقائع التي نزلت بسببها الآية؛ وفي عدم تعدادها ستر ورحمة حتى لا يثار ما سكت الوحي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص716–729.","url":""}]},{"id":"s5-505","number":505,"surah":5,"verses":[101],"verseLabel":"المائدة: 101","question":"ما دلالة قوله تعالى: ﴿إن تبد لكم تسؤكم﴾ دون: إن تعلموها؟","answer":"الإبداء إظهار ما كان مستورًا وإبرازه في صورة جواب أو حكم تترتب عليه آثاره، وهو أخص من مجرد حصول العلم؛ فالذي يسوءهم أن يكشف لهم الأمر ويلزمهم مقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص716–729.","url":""}]},{"id":"s5-506","number":506,"surah":5,"verses":[101],"verseLabel":"المائدة: 101","question":"ما دلالة تقييد السؤال بقوله تعالى: ﴿حين ينزل القرآن﴾؟","answer":"لأن السؤال زمن نزول الوحي قد يستدعي جوابًا قرآنيًا يصير حكمًا ظاهرًا لازمًا بعد أن كان مسكوتًا عنه؛ لذلك كان التكلف حينئذ أشد أثرًا، أما سؤال الحاجة والبيان فمشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص716–729.","url":""}]},{"id":"s5-507","number":507,"surah":5,"verses":[101],"verseLabel":"المائدة: 101","question":"ما دلالة قوله تعالى بعد النهي: ﴿عفا الله عنها﴾؟","answer":"يحتمل أن المعنى: عفا الله عما سلف من أسئلتكم، ويحتمل أنه سكت عن تلك الأشياء فلم يكلفكم بها؛ وعلى الوجهين تبني الجملة أدبًا قوامه قبول عفو الله وعدم تتبع ما ستره أو تركه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص716–729.","url":""}]},{"id":"s5-508","number":508,"surah":5,"verses":[101],"verseLabel":"المائدة: 101","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله غفور حليم﴾ دون: غفور رحيم؟","answer":"الغفور يستر ما سلف من خطئهم، والحليم لا يعاجل بالعقوبة من أساء السؤال أو تجاوز الأدب، بل يمهله ليعود؛ فالحلم أنسب بمقام النهي عن التعنت بعد ذكر العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص716–729.","url":""}]},{"id":"s5-509","number":509,"surah":5,"verses":[102],"verseLabel":"المائدة: 102","question":"ما دلالة قوله تعالى: ﴿قد سألها قوم من قبلكم ثم أصبحوا بها كافرين﴾؟","answer":"تستشهد الآية بتاريخ أمم طلبت آيات أو أحكامًا على سبيل التعنت، فلما أجيبت لم تذعن؛ فحققت ﴿قد﴾ وقوع المثال، وجاءت ﴿ثم﴾ لتستبعد انتقالهم من السؤال إلى الكفر بما ظهر لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص730–737.","url":""}]},{"id":"s5-510","number":510,"surah":5,"verses":[102],"verseLabel":"المائدة: 102","question":"ما سرّ عود الضمير المؤنث المفرد في ﴿سألها﴾ إلى ﴿أشياء﴾؟","answer":"جمع غير العاقل يعامل في العربية معاملة المؤنث المفرد، لذلك صح أن يعود إلى ﴿أشياء﴾ الضمير في ﴿سألها﴾؛ والمعنى: سأل قوم عن أمثال تلك الأشياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص730–737.","url":""}]},{"id":"s5-511","number":511,"surah":5,"verses":[102],"verseLabel":"المائدة: 102","question":"ما دلالة ﴿ثم﴾ و﴿أصبحوا﴾ في قوله تعالى: ﴿ثم أصبحوا بها كافرين﴾؟","answer":"﴿ثم﴾ تفيد التراخي وتستبعد رتبة الكفر بعد حصول ما طلبوه، و﴿أصبحوا﴾ بمعنى صاروا، فتصور انقلاب حالهم وظهور عاقبتهم؛ وكان المنتظر أن يقود السؤال إلى التصديق لا الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص730–737.","url":""}]},{"id":"s5-512","number":512,"surah":5,"verses":[103],"verseLabel":"المائدة: 103","question":"ما دلالة قوله تعالى: ﴿ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام﴾ واختيار فعل ﴿جعل﴾؟","answer":"نفت الآية أن يكون الله شرع هذه الأصناف أو أنشأ لها حرمة خاصة؛ فـ﴿جعل﴾ هنا في معنى التشريع والتصيير الديني، وزيادة ﴿من﴾ تؤكد نفي أي فرد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص738–751.","url":""}]},{"id":"s5-513","number":513,"surah":5,"verses":[103],"verseLabel":"المائدة: 103","question":"ما دلالة سرد أسماء البحيرة والسائبة والوصيلة والحام؟","answer":"سمّت الآية البدع الجاهلية بأسمائها المتداولة لتبطلها واحدةً واحدة ولا تدع لأهلها أن يخفوها تحت عموم العادات؛ كما تحفظ غرابة الأسماء صورة التكلف الذي اخترعوه في الأنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص738–751.","url":""}]},{"id":"s5-514","number":514,"surah":5,"verses":[103],"verseLabel":"المائدة: 103","question":"ما دلالة تعريف ﴿الكذب﴾ في قوله تعالى: ﴿ولكن الذين كفروا يفترون على الله الكذب﴾؟","answer":"التعريف يفيد جنس الكذب المعروف في غاية شناعته، وهو نسبة هذه الأحكام المختلقة إلى الله؛ فليس خطؤهم مجرد عادة بشرية، بل افتراء متعمد على المشرّع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص738–751.","url":""}]},{"id":"s5-515","number":515,"surah":5,"verses":[103],"verseLabel":"المائدة: 103","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وأكثرهم لا يعقلون﴾ دون: لا يعلمون؟","answer":"قد يعلمون أسماء هذه العادات وكيف تمارس، لكن أكثرهم لا يستعمل عقله في طلب دليل نسبتها إلى الله أو إدراك تناقضها؛ فالمشكلة فساد التعقل، و﴿أكثرهم﴾ تنصف من لم يدخل في الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص738–751.","url":""}]},{"id":"s5-516","number":516,"surah":5,"verses":[104],"verseLabel":"المائدة: 104","question":"ما دلالة قولهم: ﴿حسبنا ما وجدنا عليه آباءنا﴾ دون: نتبع آباءنا؟","answer":"﴿حسبنا﴾ تعني يكفينا، فهي أبلغ في إغلاق باب النظر من مجرد الإخبار بالاتباع؛ إذ جعلوا الموروث كافيًا عن وحي الله وعن الرسول، وأعلنوا الاكتفاء قبل فحص الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص752–764.","url":""}]},{"id":"s5-517","number":517,"surah":5,"verses":[104],"verseLabel":"المائدة: 104","question":"ما الصورة في قوله تعالى: ﴿ما وجدنا عليه آباءنا﴾؟","answer":"صوّر المعتقد والعادة كطريق أو حال مستقرة وجدوا آباءهم قائمين عليها، ثم بقوا هم فوقها؛ فالتعبير يكشف تلقي الموروث جاهزًا بلا بحث في دليله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص752–764.","url":""}]},{"id":"s5-518","number":518,"surah":5,"verses":[104],"verseLabel":"المائدة: 104","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أولو كان آباؤهم لا يعلمون شيئًا ولا يهتدون﴾؟","answer":"الاستفهام للإنكار والإلزام: أيكفيهم طريق الآباء حتى لو فقد الآباء العلم والهداية؟ فهو يهدم التقليد بإظهار النتيجة التي لا يقبلها عقل: اتباع الجاهل الضال لمجرد سبقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص752–764.","url":""}]},{"id":"s5-519","number":519,"surah":5,"verses":[104],"verseLabel":"المائدة: 104","question":"ما الفرق بين نفي العلم ونفي الهداية في قوله تعالى: ﴿لا يعلمون شيئًا ولا يهتدون﴾؟","answer":"نفي العلم يدل على فقدان معرفة الحق ودليله، ونفي الهداية يدل على عدم سلوك الطريق الموصل إليه؛ فجمع فساد التصور وفساد المسير، لأن المرء قد يعرف ولا يعمل أو يتحرك بلا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص752–764.","url":""}]},{"id":"s5-520","number":520,"surah":5,"verses":[21],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما الفرق بين قوله تعالى: ﴿ما ألفينا عليه آباءنا﴾ في البقرة، وقوله: ﴿ما وجدنا عليه آباءنا﴾ في المائدة ولقمان؟","answer":"﴿ألفينا﴾ تفيد المصادفة واللقاء بالشيء قائمًا، فتلائم تصوير اتباعهم لما صادفوا الآباء عليه من غير نظر. و﴿وجدنا﴾ أعم في الإدراك، وتلائم مقام ادعائهم أن ما وجدوه كافٍ أو تمسكهم به عند دعوة الرسول؛ واتحد أصل التقليد واختلفت زاوية عرضه.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج2، ص663 فما بعدها.","url":""}]},{"id":"s5-521","number":521,"surah":5,"verses":[104],"verseLabel":"البقرة: 170؛ المائدة: 104","question":"ما الفرق بين قول المقلدين في المائدة: ﴿حسبنا ما وجدنا عليه آباءنا﴾، وقولهم في البقرة: ﴿بل نتبع ما ألفينا عليه آباءنا﴾؟","answer":"في البقرة صرحوا بالفعل الذي اختاروه في مقابلة الوحي: اتباع الآباء. وفي المائدة اشتد إعراضهم فقالوا ﴿حسبنا﴾، أي يكفينا الموروث ولا حاجة بنا إلى ما أنزل الله أو إلى الرسول؛ فصيغة المائدة أبلغ في الاكتفاء والانغلاق.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج2، ص663 فما بعدها.","url":""}]},{"id":"s5-522","number":522,"surah":5,"verses":[21],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما سرّ قوله تعالى في المائدة: ﴿تعالوا إلى ما أنزل الله وإلى الرسول﴾، وقوله في البقرة ولقمان: ﴿اتبعوا ما أنزل الله﴾؟","answer":"﴿تعالوا﴾ أصلها دعوة إلى الإقبال والارتفاع، فناسبت المائدة حيث دُعوا إلى الوحي وإلى الرسول الحاضر ليحتكموا إليه، في مقابل اكتفائهم بالموروث. أما ﴿اتبعوا﴾ فواجهت مباشرة سلوك التقليد في البقرة ولقمان بأمر اتباع المنزل.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج2، ص663 فما بعدها.","url":""}]},{"id":"s5-523","number":523,"surah":5,"verses":[104],"verseLabel":"البقرة: 170؛ المائدة: 104","question":"ما سرّ وصف الآباء في البقرة بأنهم ﴿لا يعقلون شيئًا﴾، وفي المائدة بأنهم ﴿لا يعلمون شيئًا﴾؟","answer":"في البقرة كان الكلام على تقليد الآباء في مقابل أمر الاتباع، فوبخ تعطيل العقل الذي يميز صحة الطريق. وفي المائدة ادعى الأبناء أن الموروث يكفيهم عن المنزل والرسول، فنفى عن آبائهم العلم الذي يصلح أساسًا لهذا الاكتفاء، ثم نفى الهداية في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج2، ص668 فما بعدها.","url":""}]},{"id":"s5-524","number":524,"surah":5,"verses":[105],"verseLabel":"المائدة: 105","question":"ما دلالة قوله تعالى: ﴿عليكم أنفسكم﴾ دون: أصلحوا أنفسكم؟","answer":"التركيب اسم فعل للإغراء، أي الزموا أنفسكم واحفظوها؛ وهو أوجز وأشد تنبيهًا من الأمر المباشر، كأن النفس أمانة موضوعة على عاتق صاحبها لا يجوز إهمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص765–777.","url":""}]},{"id":"s5-525","number":525,"surah":5,"verses":[105],"verseLabel":"المائدة: 105","question":"كيف يُفهم قوله تعالى: ﴿لا يضركم من ضل إذا اهتديتم﴾ مع الأمر بإصلاح الغير؟","answer":"الاهتداء يشمل أداء ما أوجب الله، ومنه الأمر بالمعروف والنهي عن المنكر بحسب القدرة والحكمة؛ فإذا أصلح المؤمن نفسه وبذل واجب البيان لم يضره إصرار غيره على الضلال. فالآية تنفي تبعة نتيجة لا يملكها، ولا تبيح ترك النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص765–777.","url":""}]},{"id":"s5-526","number":526,"surah":5,"verses":[105],"verseLabel":"المائدة: 105","question":"ما دلالة تقديم ﴿إلى الله﴾ في قوله تعالى: ﴿إلى الله مرجعكم جميعًا﴾؟","answer":"التقديم يقصر المرجع النهائي على الله، و﴿جميعًا﴾ تجمع المهتدي والضال بين يديه؛ فليقم كل إنسان بواجبه، إذ لا يفصل في الأعمال والمصائر إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص765–777.","url":""}]},{"id":"s5-527","number":527,"surah":5,"verses":[105],"verseLabel":"المائدة: 105","question":"ما دلالة قوله تعالى: ﴿فينبئكم بما كنتم تعملون﴾ دون: فيحاسبكم؟","answer":"الإنباء إظهار حقيقة الأعمال وإخبار أصحابها بها مفصلة بعد أن خفي بعضها أو التبس عليهم؛ فهو يتضمن إقامة الحجة قبل الجزاء، أما الحساب فيبرز وزن النتائج. واختيار الإنباء يناسب ما يبدونه وما يكتمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص765–777.","url":""}]},{"id":"s5-528","number":528,"surah":5,"verses":[105,106],"verseLabel":"المائدة: 105–106","question":"ما مناسبة الانتقال من قوله تعالى: ﴿عليكم أنفسكم﴾ إلى أحكام الشهادة عند الموت؟","answer":"بعد تحميل كل نفس مسؤولية هدايتها ومرجعها إلى الله، جاء حكم الوصية ليبين كيف تصون النفس حقوقها وحقوق غيرها عند نهاية العمر، وكيف تؤدى الأمانة في المال والشهادة قبل الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-529","number":529,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما الصورة في قوله تعالى: ﴿إذا حضر أحدكم الموت﴾ مع أن الحاضر أماراته؟","answer":"أسند الحضور إلى الموت نفسه مبالغة في قربه، كأنه شخص أقبل وحضر، والمراد حضور أسبابه وعلاماته التي تتيح الوصية؛ فالصورة تستنهض المبادرة قبل فوات القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-530","number":530,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما دلالة اشتراط ﴿ذوا عدل منكم أو آخران من غيركم﴾ في شاهدي الوصية؟","answer":"الأصل شاهدان عدلان من جماعة المسلمين ضمانًا للأمانة، ويُرخص عند ضرورة السفر في آخرين من غيرهم على أحد أشهر التفسيرات؛ فجمع الحكم بين قوة التوثيق ومراعاة تعذر الشهود، وتفصيل المراد بـ﴿غيركم﴾ موضع خلاف فقهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-531","number":531,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما دلالة تخصيص السفر في قوله تعالى: ﴿إن أنتم ضربتم في الأرض فأصابتكم مصيبة الموت﴾؟","answer":"في السفر يبعد الإنسان عن أهله وجماعته، وقد تفجؤه أمارات الموت ولا يجد الشهود المعتادين؛ لذلك احتاج السياق إلى بيان رخصة التوثيق بمن يتاح وحماية الوصية من الضياع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-532","number":532,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما الصورة في التعبير عن السفر بقوله تعالى: ﴿ضربتم في الأرض﴾؟","answer":"الضرب في الأرض يصور المسافر يباشر أرضها ويسير فيها بقوة وحركة طلبًا لمقصده؛ فهو أوقع من لفظ السفر المجرد في استحضار البعد والتنقل وما يصاحبهما من تعرض للحوادث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-533","number":533,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما دلالة تسمية الموت ﴿مصيبة الموت﴾؟","answer":"المصيبة ما يصيب الإنسان بنزول مكروه، والموت أعظم ما يقطع المرء عن تدبير ماله وأهله ويوقع بهم الفقد؛ فوصفه بالمصيبة يوافق مقام الخوف على الوصية والحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-534","number":534,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما دلالة حبس الشاهدين ﴿من بعد الصلاة﴾ عند الشك؟","answer":"اختير ما بعد الصلاة لأن النفوس تكون أقرب إلى خشية الله، ولأن اجتماع الناس يجعل اليمين أهيب وأبعد عن التلاعب؛ وقيل المراد صلاة العصر بوجه خاص. والحبس هنا إيقافهما لاستحلافهما لا سجنهما عقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-535","number":535,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما دلالة حكاية نص اليمين كاملًا: ﴿لا نشتري به ثمنًا ولو كان ذا قربى...﴾؟","answer":"فصّل النص منافذ الخيانة التي يجب سدها: بيع اليمين بمنفعة، والمحاباة للقرابة، وكتمان شهادة الله؛ فتلقين اليمين بألفاظها يغلظ التوثيق ويمنع الشاهد من الاحتماء بعبارة مبهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-536","number":536,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما الصورة في قوله تعالى: ﴿لا نشتري به ثمنًا﴾ في سياق الشهادة؟","answer":"صوّر تبديل الشهادة صفقة يبيع فيها الشاهد الحق أو يمينه بعوض دنيوي قليل؛ فكل منفعة يأخذها مقابل التحريف ثمن زائل، والخسارة الحقيقية في الدين والأمانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-537","number":537,"surah":5,"verses":[106],"verseLabel":"المائدة: 106","question":"ما سرّ تقديم النهي عن شراء الثمن على النهي عن كتمان الشهادة؟","answer":"لأن الطمع في العوض أو محاباة القريب من أبرز دوافع كتمان الشهادة، فبدأ بالباعث الخفي ثم صرح بالفعل الناتج عنه؛ وانتقل من منع المقايضة إلى حفظ أصل الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص778 فما بعدها.","url":""}]},{"id":"s5-538","number":538,"surah":5,"verses":[107],"verseLabel":"المائدة: 107","question":"ما الصورة في قوله تعالى: ﴿فإن عُثر على أنهما استحقا إثمًا﴾؟","answer":"صوّر الإثم المستور شيئًا مطمورًا يُعثر عليه بعد البحث أو المصادفة؛ وبناء ﴿عُثر﴾ للمجهول يوجه النظر إلى انكشاف الخيانة وثبوتها، لا إلى شخص مكتشفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص10–27.","url":""}]},{"id":"s5-539","number":539,"surah":5,"verses":[107],"verseLabel":"المائدة: 107","question":"ما دلالة قوله تعالى عن الشاهدين: ﴿استحقا إثمًا﴾؟","answer":"أي اكتسبا ما أوجب لهما الإثم واستحقاق المؤاخذة بخيانة اليمين أو الشهادة؛ فالتعبير لا يصف زلة عابرة فقط، بل تبعة صارت حقًا لازمًا عليهما بسبب فعلهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص10–27.","url":""}]},{"id":"s5-540","number":540,"surah":5,"verses":[107],"verseLabel":"المائدة: 107","question":"ما دلالة قيام شاهدين آخرين ﴿من الذين استحق عليهم الأوليان﴾؟","answer":"إذا ظهرت خيانة الشاهدين الأولين، قام مقامهما اثنان من أولياء الميت الأقرب فالأقرب ممن وقع عليهم الضرر وهم أحق بالدفاع عن الوصية، فيحلفان على صدق دعواهما. والعبارة والقراءات فيها تفصيل نحوي وفقهي، لكن مقصدها نقل التوثيق إلى أصحاب الحق عند ثبوت الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص10–27.","url":""}]},{"id":"s5-541","number":541,"surah":5,"verses":[107],"verseLabel":"المائدة: 107","question":"ما دلالة قوله تعالى: ﴿لشهادتنا أحق من شهادتهما﴾ دون: أصدق؟","answer":"﴿أحق﴾ تجمع الصدق والاستحقاق القضائي؛ فشهادة أصحاب الحق أولى بالقبول بعد ظهور خيانة الأولين، لا مجرد أصدق في خبر نفسي. واللام تؤكد هذه الأولوية في مقام التنازع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص10–27.","url":""}]},{"id":"s5-542","number":542,"surah":5,"verses":[107],"verseLabel":"المائدة: 107","question":"ما دلالة ختم يمين الشاهدين الآخرين بقوله تعالى: ﴿إنا إذًا لمن الظالمين﴾؟","answer":"يعترفان بأنهما إن كذبا أو تجاوزا الحق كانا مندرجين في زمرة الظالمين؛ و﴿إن﴾ واللام تؤكدان تبعة الشهادة، و﴿إذًا﴾ تربط الظلم بما لو وقع منهما من اعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص10–27.","url":""}]},{"id":"s5-543","number":543,"surah":5,"verses":[108],"verseLabel":"المائدة: 108","question":"ما معنى الإتيان بالشهادة ﴿على وجهها﴾ في قوله تعالى: ﴿ذلك أدنى أن يأتوا بالشهادة على وجهها﴾؟","answer":"وجه الشهادة صورتها الصحيحة المستقيمة التي توافق الحق بلا كتمان ولا تبديل؛ أي إن هذا الإجراء أقرب إلى حمل الشهود على أدائها كاملة كما يجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص28–40.","url":""}]},{"id":"s5-544","number":544,"surah":5,"verses":[108],"verseLabel":"المائدة: 108","question":"ما دلالة قوله تعالى: ﴿أو يخافوا أن ترد أيمان بعد أيمانهم﴾؟","answer":"الإجراء يردع الشاهدين من جهة أخرى: يخافان أن تكشف خيانتهما فتأتي أيمان الورثة بعد أيمانهما فتبطل أثرها وتفضحهما؛ فاحتمال رد اليمين يحمل على الصدق من البداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص28–40.","url":""}]},{"id":"s5-545","number":545,"surah":5,"verses":[108],"verseLabel":"المائدة: 108","question":"ما دلالة الجمع بين قوله تعالى: ﴿واتقوا الله واسمعوا﴾؟","answer":"التقوى وازع باطن يمنع الخيانة، والسماع قبول واعٍ للحكم وانقياد له لا مجرد إدراك الصوت؛ فجمعت الآية صلاح القلب وطاعة الأمر المسموع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص28–40.","url":""}]},{"id":"s5-546","number":546,"surah":5,"verses":[108],"verseLabel":"المائدة: 108","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"من خرج عن طاعة الله في الشهادة واليمين فقد فسق، والإصرار على هذا الخروج يحرمه هداية التوفيق إلى أداء الحق؛ فكانت الخاتمة تهديدًا بعد الأمر بالتقوى والسماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص28–40.","url":""}]},{"id":"s5-547","number":547,"surah":5,"verses":[109],"verseLabel":"المائدة: 109","question":"ما مناسبة الانتقال من الشهادة في الدنيا إلى قوله تعالى: ﴿يوم يجمع الله الرسل﴾؟","answer":"بعد بيان كيف توثق شهادة البشر ويُخشى كتمانها، نقل السياق إلى أعظم مشهد للشهادة: جمع الرسل وسؤالهم عن استجابة أممهم؛ لتعلم النفوس أن وراء قضاء الدنيا شهادة لا يضيع عندها حق ولا يخفى باطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص41–49.","url":""}]},{"id":"s5-548","number":548,"surah":5,"verses":[109],"verseLabel":"المائدة: 109","question":"ما الحكمة التي يبينها سؤال الرسل: ﴿ماذا أجبتم﴾ مع علم الله بالجواب؟","answer":"ليس السؤال لطلب علم، بل لإظهار جواب الرسل على رؤوس الأشهاد وإقامة الحجة على أممهم، وفيه تكريم للمستجيبين وتوبيخ للمكذبين؛ فيتحول العلم الإلهي إلى شهادة معلنة يقوم عليها الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص41–49.","url":""}]},{"id":"s5-549","number":549,"surah":5,"verses":[109],"verseLabel":"المائدة: 109","question":"ما دلالة جواب الرسل: ﴿لا علم لنا﴾ مع علمهم بمن استجاب لهم في الظاهر؟","answer":"نفوا العلم الكامل بحقائق الإجابة ومآلات الأمم وما حدث بعدهم؛ فما شهدوه من ظاهر لا يحيط بسرائر القلوب ولا بالغيب. ويجوز أن يكون الجواب من هول الموقف وتفويض العلم كله إلى الله، فعلمهم بالنسبة إلى علمه المحيط كأنه لا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص41–49.","url":""}]},{"id":"s5-550","number":550,"surah":5,"verses":[109],"verseLabel":"المائدة: 109","question":"ما دلالة قوله تعالى: ﴿إنك أنت علام الغيوب﴾ بصيغة المبالغة وضمير الفصل؟","answer":"﴿علام﴾ تدل على كمال العلم وكثرته وإحاطته بكل غيب، و﴿أنت﴾ يفيد القصر والتوكيد؛ فرد الرسل العلم الحقيقي بباطن الاستجابة ومآلها إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص41–49.","url":""}]},{"id":"s5-551","number":551,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة قوله تعالى لعيسى عليه السلام: ﴿اذكر نعمتي عليك وعلى والدتك﴾؟","answer":"كانت نعم الله على مريم متصلة برسالة ابنها: اصطفاؤها وتطهيرها وتبرئتها وحفظها، كما كان ميلاده المعجز نعمة عليهما معًا؛ لذلك جمعت الآية الأم والابن في تذكير واحد مع توجيه الخطاب إلى عيسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-552","number":552,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة قوله تعالى: ﴿إذ أيدتك بروح القدس﴾ واختيار فعل التأييد؟","answer":"التأييد تقوية تتبعها نصرة وثبات، و﴿روح القدس﴾ جبريل عليه السلام؛ فذكر الله أنه قوى عيسى بالملك الطاهر في تبليغ الرسالة ومواجهة المكذبين، لا أنه استمد قوته من ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-553","number":553,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما سرّ ترتيب قوله تعالى: ﴿تكلم الناس في المهد وكهلًا﴾؟","answer":"بدأ بالكلام في المهد لأنه المعجزة الخارقة التي برأت أمه وأثبتت نبوته، ثم ذكر كلامه كهلًا ليدل على استمرار تأييده وبلوغه طور النضج؛ فجمع بدء حياته وما يؤول إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-554","number":554,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة تكرار قوله تعالى: ﴿بإذني﴾ مع صنع هيئة الطير والشفاء وإحياء الموتى؟","answer":"كرر القيد عند الخوارق التي قد تكون مدخلًا للغلو، ليقرر أن عيسى سبب مأذون له وأن الخلق والشفاء والإحياء الحقيقي بقدرة الله؛ فكل معجزة شاهد على الرسالة لا على الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-555","number":555,"surah":5,"verses":[110],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما سرّ قوله تعالى في آل عمران: ﴿فتنفخ فيه﴾، وفي المائدة: ﴿فتنفخ فيها﴾؟","answer":"راعى كل ضمير مرجعه في السياق: في آل عمران يعود ﴿فيه﴾ إلى المخلوق أو الشيء المصوغ على هيئة الطير، وفي المائدة يعود ﴿فيها﴾ إلى ﴿هيئة الطير﴾ المؤنثة؛ فاتحد الحدث واختلف اللفظ باختلاف الملحوظ قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74؛ وله مناقشة عكسية في ج6.","url":""}]},{"id":"s5-556","number":556,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة قوله تعالى: ﴿فتكون طيرًا بإذني﴾ واختيار ﴿طيرًا﴾ دون: طائرًا؟","answer":"﴿طير﴾ اسم جنس يصدق على الواحد والجمع، فيصور الهيئة وقد صارت من جنس الطير الحي لا مجرد شيء شبيه بطائر واحد؛ ثم جاء ﴿بإذني﴾ ليعيد حدوث الحياة إلى قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-557","number":557,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة الجمع بين إبراء الأكمه والأبرص وإخراج الموتى؟","answer":"تدرجت الخوارق من شفاء مرض خِلقي في الأكمه، إلى مرض ظاهر مستعص في الأبرص، إلى الغاية التي يعجز عنها البشر وهي إخراج الموتى أحياء؛ فاستوعبت درجات العجز وأكدت أن وقوعها بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-558","number":558,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما الصورة في قوله تعالى: ﴿إذ كففت بني إسرائيل عنك﴾؟","answer":"الكف منع الشيء وقبضه عن الوصول، فصوّر تدبيرهم للأذى كيدٍ امتدت إلى عيسى فكفها الله عنه؛ وفيه تذكير بالحماية المباشرة حين هموا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-559","number":559,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة قول المكذبين عن البينات: ﴿إن هذا إلا سحر مبين﴾؟","answer":"قصروا المعجزات الظاهرة على السحر هربًا من دلالتها، ووصفوه بالمبين مع أن البينات هي الواضحة حقًا؛ فجمع قولهم المكابرة وقلب الحقيقة، إذ جعلوا وضوح الحجة وضوحًا للسحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74.","url":""}]},{"id":"s5-560","number":560,"surah":5,"verses":[110],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما سرّ تكرار قيد ﴿بإذني﴾ في المائدة أربع مرات، ووروده في آية آل عمران مرات أقل؟","answer":"المائدة مقام تعداد الله نعمه على عيسى ومحاسبته أمام من غلا فيه، فكرر الإذن مع كل طائفة من الخوارق لإبطال استقلاله بها. أما آل عمران فالمقام حكاية عيسى آيات رسالته لقومه، فذكر الإذن بما يكفي لربطها بالله من غير هذا التعداد الاستقصائي.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج5، ص108 وما بعدها.","url":""}]},{"id":"s5-561","number":561,"surah":5,"verses":[110],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما الفرق بين قول عيسى عليه السلام في آل عمران: ﴿وأحيي الموتى بإذن الله﴾، وقول الله في المائدة: ﴿وإذ تخرج الموتى بإذني﴾؟","answer":"في آل عمران يحكي عيسى لقومه أثر المعجزة مباشرة فقال ﴿أحيي﴾ وقيده بإذن الله. وفي المائدة يعدد الله نعمته عليه فقال ﴿تخرج الموتى﴾ مصورًا خروجهم من حال الموت أو القبور، ثم نسب الإذن إلى ذاته: ﴿بإذني﴾؛ فاختلفت زاوية الحكاية واتحد مصدر القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج5، ص108 فما بعدها؛ والأصل ج10، ص50–74.","url":""}]},{"id":"s5-562","number":562,"surah":5,"verses":[110],"verseLabel":"المائدة: 110","question":"ما دلالة الجمع في قوله تعالى: ﴿وعلمتك الكتاب والحكمة والتوراة والإنجيل﴾، مع دخول التوراة والإنجيل في جنس الكتاب؟","answer":"يحتمل ﴿الكتاب﴾ معنى الكتابة أو جنس الكتب، و﴿الحكمة﴾ فهمها ووضع العلم موضعه، ثم خص التوراة والإنجيل بالذكر لشرفهما وصلتهما برسالته؛ فالتخصيص بعد العموم يبرز الكتابين ولا يجعلهما تكرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص50–74؛ وللدلالة المعجمية: ج2، ص100–101.","url":""}]},{"id":"s5-563","number":563,"surah":5,"verses":[111],"verseLabel":"المائدة: 111","question":"ما دلالة قوله تعالى: ﴿وإذ أوحيت إلى الحواريين﴾ مع أنهم ليسوا أنبياء؟","answer":"الوحي في اللغة إعلام خفي سريع، ويأتي بمعنى الإلهام والقذف في القلب؛ فالمراد أن الله ألهم الحواريين الإيمان به وبرسوله، لا أنه أنزل عليهم وحي نبوة وتشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص75–80.","url":""}]},{"id":"s5-564","number":564,"surah":5,"verses":[111],"verseLabel":"المائدة: 111","question":"ما دلالة الجمع في الأمر بين ﴿أن آمنوا بي وبرسولي﴾؟","answer":"الإيمان بالله أصل، والإيمان برسوله تصديق لمن اختاره الله واتباع لما بلغه؛ فلا يصح ادعاء الأول مع رد الثاني. وإضافته إلى الله في ﴿برسولي﴾ تشرف عيسى وتثبت عبوديته ورسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص75–80.","url":""}]},{"id":"s5-565","number":565,"surah":5,"verses":[111],"verseLabel":"المائدة: 111","question":"ما دلالة قول الحواريين: ﴿آمنا واشهد بأننا مسلمون﴾ دون: مؤمنون؟","answer":"ذكروا الإيمان أولًا بوصفه تصديق القلب، ثم طلبوا الشهادة لهم بالإسلام لأنه الاستسلام الظاهر لله والانقياد للرسول؛ فجمعوا باطن التصديق وظاهر الطاعة، وأعلنوا وحدة دين الأنبياء في أصل الاستسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص75–80.","url":""}]},{"id":"s5-566","number":566,"surah":5,"verses":[112],"verseLabel":"المائدة: 112","question":"ما دلالة نداء الحواريين: ﴿يا عيسى ابن مريم﴾ عند سؤال المائدة؟","answer":"نادوه باسمه منسوبًا إلى أمه كما يعرف البشر، وهو خطاب التلميذ لنبيه لا خطاب العابد لإله؛ ويهيئ هذا الوصف البشري لطلبه أن يسأل ربه إنزال المائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص81–88.","url":""}]},{"id":"s5-567","number":567,"surah":5,"verses":[112],"verseLabel":"المائدة: 112","question":"كيف يُفهم قول الحواريين: ﴿هل يستطيع ربك أن ينزل علينا مائدة من السماء﴾؟","answer":"ليس لازمًا أن يكون شكًا في قدرة الله؛ فقد تأتي الاستطاعة بمعنى الفعل والإجابة، أي: هل يفعل ربك ذلك إذا سألته؟ وقيل كان السؤال في أول حالهم قبل رسوخ المعرفة. وفي قراءة: ﴿هل تستطيع ربَّك﴾، أي هل تستطيع أن تسأل ربك؛ فالواجب حفظ الأوجه وعدم نسبة الشك إليهم جزمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص81–88.","url":""}]},{"id":"s5-568","number":568,"surah":5,"verses":[112],"verseLabel":"المائدة: 112","question":"ما دلالة اختيار ﴿هل﴾ في سؤال الحواريين؟","answer":"﴿هل﴾ تطلب التصديق بحصول الفعل أو إمكان وقوعه في مقام عرض الطلب، فكأنهم يستفهمون: أيقع لنا إنزال المائدة؟ وهي ألطف في عرض الرجاء من صيغة قد تتجه إلى تعيين طرف أو إنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص81–88.","url":""}]},{"id":"s5-569","number":569,"surah":5,"verses":[112],"verseLabel":"المائدة: 112","question":"ما دلالة جواب عيسى عليه السلام: ﴿اتقوا الله إن كنتم مؤمنين﴾ قبل الاستجابة لطلبهم؟","answer":"واجه أولًا ما قد يوحي به الطلب من اختبار القدرة أو التكلف في الآيات، فدعاهم إلى تقوى الله وتعليق صدق الإيمان بها؛ لأن المؤمن لا يجعل استجابته مشروطة بخارق جديد. ثم لما بينوا مقصدهم دعا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص81–88.","url":""}]},{"id":"s5-570","number":570,"surah":5,"verses":[113],"verseLabel":"المائدة: 113","question":"ما دلالة تعليل الحواريين طلب المائدة بالأكل وطمأنينة القلب والعلم والشهادة؟","answer":"جمعوا منفعة البدن في الأكل، وزيادة اليقين في اطمئنان القلب، والتحقق من صدق الوعد، ثم أداء حق الآية بالشهادة عليها؛ فانتقلوا من الحاجة الشخصية إلى المسؤولية الإيمانية العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص89–92.","url":""}]},{"id":"s5-571","number":571,"surah":5,"verses":[113],"verseLabel":"المائدة: 113","question":"ما سرّ تقديم قولهم: ﴿نريد أن نأكل منها﴾ على طمأنينة القلوب؟","answer":"بدأوا بالحاجة العاجلة الظاهرة التي تدل عليها المائدة، ثم ارتقوا إلى المقاصد القلبية والعلمية والشهادية؛ وفي صراحتهم اعتراف ببشريتهم وحاجتهم، لا حصر لغاية الآية في الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص89–92.","url":""}]},{"id":"s5-572","number":572,"surah":5,"verses":[113],"verseLabel":"المائدة: 113","question":"ما دلالة قول الحواريين: ﴿ونعلم أن قد صدقتنا﴾ مع إعلانهم الإيمان؟","answer":"أرادوا علم المعاينة بصدق الوعد الخاص بإنزال المائدة، لا إنشاء الإيمان برسالة عيسى من الصفر؛ فخبر الوحي معلوم لهم تصديقًا، ووقوع الآية يزيدهم يقينًا حسيًا وطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص89–92.","url":""}]},{"id":"s5-573","number":573,"surah":5,"verses":[113],"verseLabel":"المائدة: 113","question":"ما دلالة ختم تعليلهم بقولهم: ﴿ونكون عليها من الشاهدين﴾؟","answer":"تعهدوا ألا يقف أثر المائدة عند انتفاعهم، بل يشهدوا بوقوعها وبدلالتها على صدق الرسول وقدرة الله؛ فحولوا طلب الآية إلى مسؤولية نقل الحق وإقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص89–92.","url":""}]},{"id":"s5-574","number":574,"surah":5,"verses":[114],"verseLabel":"المائدة: 114","question":"ما دلالة دعاء عيسى عليه السلام بقوله: ﴿اللهم ربنا﴾؟","answer":"﴿اللهم﴾ نداء خاص باسم الله يجمع التعظيم، ثم جاء ﴿ربنا﴾ لاستحضار معنى التربية والرعاية المشتركة للداعي وقومه؛ فجمع جلال المعبود وقرب الربوبية في مطلع الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص93–105.","url":""}]},{"id":"s5-575","number":575,"surah":5,"verses":[114],"verseLabel":"المائدة: 114","question":"ما دلالة صياغة عيسى عليه السلام الطلب بقوله: ﴿أنزل علينا مائدة من السماء﴾؟","answer":"نقل عيسى طلب الحواريين إلى دعاء مباشر مؤدب لربه، فحدد المطلوب ﴿مائدة﴾ ومصدرها ﴿من السماء﴾ لتكون آية ظاهرة من عند الله، وأضاف ﴿علينا﴾ فشاركهم الافتقار ولم يتعال عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص93–105.","url":""}]},{"id":"s5-576","number":576,"surah":5,"verses":[114],"verseLabel":"المائدة: 114","question":"ما دلالة قوله تعالى: ﴿تكون لنا عيدًا لأولنا وآخرنا﴾؟","answer":"العيد ما يعود في زمن معلوم بالفرح والاجتماع والذكر؛ فسأل أن يبقى يوم المائدة مناسبة شكر يتذكرها أول الأمة وآخرها، لا طعامًا ينقضي أثره بأكله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص93–105.","url":""}]},{"id":"s5-577","number":577,"surah":5,"verses":[114],"verseLabel":"المائدة: 114","question":"ما سرّ تقديم ﴿عيدًا﴾ على ﴿وآية منك﴾؟","answer":"قدم الأثر الجامع الذي تعيشه الأمة وتتوارث شكره، ثم ذكر أصله وهو كون المائدة علامة من الله على القدرة وصدق الرسالة؛ فالترتيب من أثر الآية في الجماعة إلى دلالتها العقدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص93–105.","url":""}]},{"id":"s5-578","number":578,"surah":5,"verses":[114],"verseLabel":"المائدة: 114","question":"ما مناسبة قوله تعالى: ﴿وارزقنا وأنت خير الرازقين﴾ بعد طلب المائدة؟","answer":"اعترف بأن المائدة رزق من الله لا ثمرة لقدرة عيسى، ثم أثنى بأن الله خير من يرزق: يخلق الرزق ويعطيه بحكمة ومن غير افتقار إلى عوض؛ فجمع الطلب والتوحيد والثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص93–105.","url":""}]},{"id":"s5-579","number":579,"surah":5,"verses":[115],"verseLabel":"المائدة: 115","question":"ما دلالة توكيد الوعد في قوله تعالى: ﴿إني منزلها عليكم﴾؟","answer":"أكد بـ﴿إن﴾ وجاء باسم الفاعل ﴿منزلها﴾ الدال على ثبوت الوعد وتحققه، فاستجاب لطلبهم وأزال التردد في وقوع الآية؛ ثم رتب على هذا اليقين مسؤولية أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص106–117.","url":""}]},{"id":"s5-580","number":580,"surah":5,"verses":[115],"verseLabel":"المائدة: 115","question":"ما سرّ تشديد الوعيد على من يكفر بعد إنزال المائدة؟","answer":"لأن المائدة آية مخصوصة طلبوها بأنفسهم ثم نزلت بعد قيام دلائل الرسالة، فالكفر بعدها عناد عقب المعاينة ونقض للعهد الذي ضمنه طلبهم؛ وكلما كانت الحجة أظهر كانت التبعة أشد. وقد دُمج في هذا الجواب معنى السؤال 586.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص106–117.","url":""}]},{"id":"s5-581","number":581,"surah":5,"verses":[115],"verseLabel":"المائدة: 115","question":"ما دلالة قوله تعالى: ﴿فإني أعذبه عذابًا لا أعذبه أحدًا من العالمين﴾؟","answer":"الفاء ترتب الوعيد على الكفر بعد الآية، و﴿إن﴾ تؤكده، واشتقاق ﴿عذابًا﴾ من فعله يضخم نوع العذاب، ثم نفى مماثلته لعذاب أحد من العالمين؛ فتراكم البناء ليوافق غلظ الجريمة بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص106–117.","url":""}]},{"id":"s5-582","number":582,"surah":5,"verses":[116],"verseLabel":"المائدة: 116","question":"ما الحكمة التي يبينها سؤال الله عيسى عليه السلام: ﴿أأنت قلت للناس اتخذوني وأمي إلهين من دون الله﴾ مع علم الله ببراءته؟","answer":"السؤال ليس لطلب العلم، بل لإعلان براءة عيسى على رؤوس الأشهاد، وإلزام من غلا فيه بشهادته، وتوبيخهم على نسبة ما لم يأمر به إليهم؛ فيقوم الإقرار العلني حجة في مشهد القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136.","url":""}]},{"id":"s5-583","number":583,"surah":5,"verses":[116],"verseLabel":"المائدة: 116","question":"ما دلالة ذكر أم عيسى معه في قوله تعالى: ﴿اتخذوني وأمي إلهين من دون الله﴾؟","answer":"لإبطال كل غلو رفع عيسى أو أمه فوق مقام العبودية، سواء ظهر في دعاء أو تعظيم تعبدي أو اعتقاد؛ فهما مخلوقان أنعم الله عليهما، ولا يملكان أن يكونا إلهين من دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136.","url":""}]},{"id":"s5-584","number":584,"surah":5,"verses":[116],"verseLabel":"المائدة: 116","question":"ما دلالة ابتداء جواب عيسى عليه السلام بقوله: ﴿سبحانك﴾؟","answer":"بدأ بتنزيه الله عن الشريك قبل الدفاع عن نفسه؛ لأن مقالة التأليه اعتداء على توحيد الله أولًا، فقدم حق ربه وأعلن براءته العقدية ثم نفى صدور القول عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136.","url":""}]},{"id":"s5-585","number":585,"surah":5,"verses":[116],"verseLabel":"المائدة: 116","question":"ما دلالة قوله تعالى على لسان عيسى: ﴿ما يكون لي أن أقول ما ليس لي بحق﴾ دون الاقتصار على: ما قلت؟","answer":"﴿ما يكون لي﴾ تنفي أصل الصلاحية والإمكان الشرعي لهذا القول، لا مجرد وقوعه في الماضي؛ و﴿ما ليس لي بحق﴾ يقرر أنه تجاوز لمقام العبودية لا يملكه رسول. فالنفي أعم وأقوى من نفي حادثة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136.","url":""}]},{"id":"s5-586","number":586,"surah":5,"verses":[116],"verseLabel":"المائدة: 116","question":"ما دلالة قوله تعالى على لسان عيسى: ﴿إن كنت قلته فقد علمته﴾ بصيغة الشرط؟","answer":"علّق الأمر على فرض محال في الواقع لإقامة أبلغ حجة: لو صدر مني القول لكان معلومًا لك قطعًا، وعلمك ببراءتي يغني عن كل دفاع. فليس الشرط ترددًا، بل تفويض للعلم الإلهي وإحكام للنفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136.","url":""}]},{"id":"s5-587","number":587,"surah":5,"verses":[116],"verseLabel":"المائدة: 116","question":"ما دلالة قوله تعالى على لسان عيسى: ﴿تعلم ما في نفسي ولا أعلم ما في نفسك﴾؟","answer":"يعلم الله ما أخفاه عيسى في ذاته من خاطر وقصد، أما عيسى فلا يعلم ما استأثر الله به من غيب وعلم. وجاءت المقابلة على لغة الخطاب، ولفظ النفس في جانب الله يفهم على ما يليق بذاته بلا مماثلة لنفوس المخلوقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136.","url":""}]},{"id":"s5-588","number":588,"surah":5,"verses":[109,116],"verseLabel":"المائدة: 109، 116","question":"ما دلالة تكرار قوله تعالى: ﴿إنك أنت علام الغيوب﴾ في جواب عيسى كما ورد في جواب الرسل؟","answer":"وافق عيسى إخوانه الرسل في رد علم السرائر والغيوب إلى الله وحده؛ وفي التكرار توكيد لوحدة موقفهم جميعًا من العبودية وحدود العلم، وهو حجة خاصة على من غلا في عيسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص118–136؛ ص41–49.","url":""}]},{"id":"s5-589","number":589,"surah":5,"verses":[17],"verseLabel":"المائدة: 116؛ الفرقان: 17","question":"ما الفرق بين تخصيص عيسى بالسؤال في المائدة، وجمع المعبودين والعابدين في مشهد الفرقان مع توجيه السؤال إلى المعبودين؟","answer":"المائدة تفصل قضية الغلو في عيسى وأمه، فخُص عيسى بالسؤال ليعلن حقيقة دعوته وبراءته. أما الفرقان فيعرض قاعدة عامة في عبادة غير الله، فيحشر المعبودين مع عابديهم ويسأل المعبودين: أأنتم أضللتم هؤلاء أم هم ضلوا؟ فالتخصيص هنا لقضية، والتعميم هناك لنمط الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج37، ص580–590.","url":""}]},{"id":"s5-590","number":590,"surah":5,"verses":[117],"verseLabel":"المائدة: 117","question":"ما دلالة القصر في قوله تعالى على لسان عيسى: ﴿ما قلت لهم إلا ما أمرتني به﴾؟","answer":"حصر كل ما بلغه لقومه في أمر الله وحده، فنفى الزيادة والتبديل ودعوى الألوهية عن أصل رسالته؛ وبذلك حمل من غلا فيه مسؤولية ما أحدثه بعد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص137–149.","url":""}]},{"id":"s5-591","number":591,"surah":5,"verses":[117],"verseLabel":"المائدة: 117","question":"ما دلالة بيان الأمر الإلهي بقوله تعالى: ﴿أن اعبدوا الله ربي وربكم﴾؟","answer":"فسر عيسى مضمون ما أُمر به بأصل رسالته: عبادة الله وحده، ثم قدم ربوبيته له على ربوبيته لقومه ليعلن أنه عبد مربوب مثلهم؛ فالجملة تهدم التأليه بنص دعوته نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص137–149.","url":""}]},{"id":"s5-592","number":592,"surah":5,"verses":[117],"verseLabel":"المائدة: 117","question":"ما دلالة وصف عيسى نفسه بقوله: ﴿وكنت عليهم شهيدًا ما دمت فيهم﴾ دون: شاهدًا؟","answer":"﴿شهيد﴾ أبلغ في ثبوت الشهادة والمراقبة واستحضار ما وقع، وقيّدها بمدة وجوده بينهم ليحدد نطاق علمه ومسؤوليته البشرية؛ فهو يشهد بما عاينه لا بما استتر بعد رفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص137–149.","url":""}]},{"id":"s5-593","number":593,"surah":5,"verses":[117],"verseLabel":"المائدة: 117","question":"ما دلالة التعبير عن انتهاء مقام عيسى بين قومه بقوله تعالى: ﴿فلما توفيتني﴾؟","answer":"التوفي في أصل اللغة أخذ الشيء وافيًا وقبضه؛ فالمعنى لما قبضتني من بينهم وأنهيت مدة شهودي عليهم. واللفظ وحده لا يحسم كيفية هذا التوفي ولا يصح أن يحمل هنا على معنى تفصيلي دون بقية الأدلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص137–149.","url":""}]},{"id":"s5-594","number":594,"surah":5,"verses":[117],"verseLabel":"المائدة: 117","question":"ما دلالة الانتقال من قوله تعالى: ﴿كنت عليهم شهيدًا﴾ إلى قوله: ﴿كنت أنت الرقيب عليهم﴾؟","answer":"شهادة عيسى محدودة بمدة وجوده في قومه، أما رقابة الله فمستمرة قبلها وفيها وبعدها؛ لذلك جاء ﴿أنت﴾ للتوكيد والقصر، فانتقل من مراقبة الرسول البشرية المحدودة إلى الرقابة الإلهية المحيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص137–149.","url":""}]},{"id":"s5-595","number":595,"surah":5,"verses":[117],"verseLabel":"المائدة: 117","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وأنت على كل شيء شهيد﴾؟","answer":"عمم بعد خصوص الرقابة على قوم عيسى: فشهادة الله محيطة بكل شيء ظاهر وباطن في كل زمن، وبذلك يكتمل تفويض الحكم إليه وتثبت براءة الرسول مما حدث بعد غيابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص137–149.","url":""}]},{"id":"s5-596","number":596,"surah":5,"verses":[55],"verseLabel":"المائدة: 117؛ آل عمران: 55","question":"ما الفرق بين قول عيسى عليه السلام: ﴿فلما توفيتني﴾، وقول الله له: ﴿إني متوفيك ورافعك إلي﴾؟","answer":"في آل عمران جاء الخطاب وعدًا من الله لعيسى قبل وقوع الأمر، فذكر التوفي والرفع في سياق الحفظ من الكافرين. وفي المائدة يحكي عيسى يوم القيامة انتهاء وجوده بين قومه فقال ﴿فلما توفيتني﴾، أي لما قبضتني من بينهم؛ فالأول وعد سابق يصرح بالرفع، والثاني شهادة لاحقة تحدد انتهاء رقابته عليهم، ولا يحسم لفظ التوفي وحده كيفيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص144–156؛ وج10، ص137–149.","url":""}]},{"id":"s5-597","number":597,"surah":5,"verses":[118],"verseLabel":"المائدة: 118","question":"ما دلالة قول عيسى عليه السلام: ﴿إن تعذبهم فإنهم عبادك﴾، وكيف تتصل العبودية بالتعذيب؟","answer":"العبودية هنا تعليل لتمام ملك الله وسلطانه، لا لكون مجرد العبودية سببًا للعذاب؛ أي إن عذبت من استحق منهم فأنت مالكهم العادل لا معقب لحكمك. وفي العبارة تفويض وأدب، من غير اعتراض ولا تزكية لمن بدّل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص150–159.","url":""}]},{"id":"s5-598","number":598,"surah":5,"verses":[118],"verseLabel":"المائدة: 118","question":"ما سرّ قوله تعالى على لسان عيسى: ﴿وإن تغفر لهم فإنك أنت العزيز الحكيم﴾ دون: الغفور الرحيم؟","answer":"ذكر العزة ليبين أن المغفرة، إن وقعت لمن يشاء الله، صادرة عن قدرة لا عن عجز عن العقوبة، وذكر الحكمة لأنها توضع في مستحقها وعلى الوجه الذي يعلمه الله. وفي المقام يفوض عيسى الحكم ولا يتقدم بين يدي الله بوصف يقتضي طلب المغفرة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص150–159.","url":""}]},{"id":"s5-599","number":599,"surah":5,"verses":[118],"verseLabel":"المائدة: 118","question":"ما سرّ تقديم احتمال العذاب على المغفرة في قول عيسى عليه السلام؟","answer":"لأن الكلام في قوم نُسب إليهم الغلو بعد قيام الحجة، فبدأ بما يوافق ظاهر استحقاق من أصر، ثم ذكر المغفرة تفويضًا لمشيئة الله وحكمته. كما أن الترتيب يبرئ عيسى من أن يجعل قرابته المزعومة سببًا للشفاعة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص150–159.","url":""}]},{"id":"s5-600","number":600,"surah":5,"verses":[118],"verseLabel":"المائدة: 118","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿فإنك أنت العزيز الحكيم﴾؟","answer":"يفيد ﴿أنت﴾ توكيد اختصاص الله بكمال العزة والحكمة؛ فهو وحده القادر على إنفاذ العذاب أو المغفرة، العالم بموضع كل منهما، وليس لعيسى إلا التسليم لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص150–159.","url":""}]},{"id":"s5-601","number":601,"surah":5,"verses":[119],"verseLabel":"المائدة: 119","question":"ما دلالة قوله تعالى: ﴿هذا يوم ينفع الصادقين صدقهم﴾ دون: المؤمنين إيمانهم؟","answer":"الصدق هو المحور الذي كشفه المشهد: صدق الرسل في البلاغ، وصدق عيسى في البراءة، وصدق المؤمنين في الاستجابة؛ وهو البرهان العملي على الإيمان. لذلك علق النفع يوم القيامة بالصدق الذي وافق فيه الباطن الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص160–175.","url":""}]},{"id":"s5-602","number":602,"surah":5,"verses":[119],"verseLabel":"المائدة: 119","question":"ما دلالة الإشارة في قوله تعالى: ﴿هذا يوم ينفع الصادقين صدقهم﴾ كأن اليوم حاضر؟","answer":"استحضرت الإشارة يوم القيامة حتى صار كالمشاهد القريب، ولا سيما بعد الحوار المعروض بين الله وعيسى؛ فيقوى اليقين بالجزاء ويشعر السامع أن الحكم يعلن أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص160–175.","url":""}]},{"id":"s5-603","number":603,"surah":5,"verses":[119],"verseLabel":"المائدة: 119","question":"ما دلالة الجمع بين ﴿خالدين فيها﴾ و﴿أبدًا﴾؟","answer":"﴿خالدين فيها﴾ تثبت دوام إقامتهم في الجنات، و﴿أبدًا﴾ تؤكد امتداد هذا الخلود بلا نهاية ولا انقطاع؛ فدفعت كل توهم لمفارقة المكان أو انتهاء الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص160–175.","url":""}]},{"id":"s5-604","number":604,"surah":5,"verses":[119],"verseLabel":"المائدة: 119","question":"ما سرّ تقديم قوله تعالى: ﴿رضي الله عنهم﴾ على قوله: ﴿ورضوا عنه﴾؟","answer":"رضا الله هو الأصل والنعمة الكبرى التي ينشأ عنها ثوابهم وأمنهم، ثم يكون رضاهم عنه بما أعطاهم من الجزاء ثمرة لذلك؛ فقدم السبب الأعلى وفضل الله على استجابة العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص160–175.","url":""}]},{"id":"s5-605","number":605,"surah":5,"verses":[119],"verseLabel":"المائدة: 119","question":"ما مناسبة ختم الجزاء بقوله تعالى: ﴿ذلك الفوز العظيم﴾؟","answer":"جمع الجزاء جنات الخلود ورضا الله ورضا الصادقين، فأشار إلى هذا المجموع باسم البعيد تعظيمًا لمنزلته، وسماه الفوز العظيم لأنه تحصيل لأعلى مطلوب ونجاة من أعظم مرهوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص160–175.","url":""}]},{"id":"s5-606","number":606,"surah":5,"verses":[120],"verseLabel":"المائدة: 120","question":"ما مناسبة ختم السورة بملك الله للسماوات والأرض؟","answer":"بعد محاجة من ألّه المسيح وأمه، وخضوع الرسل للحساب، ختمت السورة بأن الملك كله لله؛ فكل من في السماوات والأرض مملوك له، وبذلك يعود ختام السورة إلى أصل التوحيد الذي حسم حوارها الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص176 فما بعدها.","url":""}]},{"id":"s5-607","number":607,"surah":5,"verses":[49],"verseLabel":"المائدة: 120؛ الشورى: 49","question":"ما دلالة زيادة ﴿وما فيهن﴾ في خاتمة المائدة: ﴿لله ملك السماوات والأرض وما فيهن﴾، وعدم ذكرها في موضع الشورى؟","answer":"صرحت المائدة بمن في السماوات والأرض لأن السياق في عيسى وأمه والرسل والعباد، فكان إدخال الموجودات كلها في الملك ردًا مباشرًا على تأليه مخلوق. أما الشورى فانتقل بعد تقرير الملك مباشرة إلى خلق ما يشاء وهبة الأولاد، فدل الخلق على ملك من في السماوات والأرض من غير حاجة إلى التصريح نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص176 فما بعدها؛ والمسح العكسي ج10، ص183.","url":""}]},{"id":"s5-608","number":608,"surah":5,"verses":[17,18,120],"verseLabel":"المائدة: 17–18، 120","question":"ما مناسبة إعادة ملك السماوات والأرض في ختام السورة بعد وروده في الآيتين 17 و18؟","answer":"في الآية 17 أقيم الملك والقدرة حجة على بشرية المسيح وأمه، وفي الآية 18 رد به ادعاء اليهود والنصارى أنهم أبناء الله وأحباؤه، ثم عاد في الختام قاعدة جامعة بعد شهادة عيسى؛ فتكرر الأصل وتوجه في كل موضع إلى دعوى مخصوصة ثم ختم الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص176 فما بعدها.","url":""}]},{"id":"s5-609","number":609,"surah":5,"verses":[120],"verseLabel":"المائدة: 120","question":"ما دلالة ضمير الجمع المؤنث في قوله تعالى: ﴿وما فيهن﴾؟","answer":"عاد الضمير إلى السماوات والأرض باعتبارها أجرامًا متعددة مجموعة، فجيء بضمير جمع المؤنث مراعاة للفظ السماوات وما عطف عليها. وهذه الصيغة ليست خاصة بالعاقل، بل تستعمل للمؤنث جمعًا؛ والمقصود استيعاب كل ما في تلك العوالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص176 فما بعدها.","url":""}]},{"id":"s5-610","number":610,"surah":5,"verses":[120],"verseLabel":"المائدة: 120","question":"ما مناسبة ختم السورة كلها بقوله تعالى: ﴿وهو على كل شيء قدير﴾؟","answer":"القدرة التامة نتيجة الملك التام ودليله: فمن ملك السماوات والأرض وما فيهن لا يعجزه إنزال مائدة، ولا بعث الخلق، ولا محاسبتهم، ولا إثابة الصادقين وعقاب المكذبين. فجمعت الخاتمة قضايا السورة وردت الأمر كله إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص176 فما بعدها.","url":""}]},{"id":"s6-1","number":1,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما مناسبة افتتاح سورة الأنعام بقوله تعالى: ﴿الحمد لله﴾ كما افتتحت الفاتحة، مع اختلاف موضوع السورتين؟","answer":"افتتحت بالحمد لأن السورة تقيم دلائل استحقاق الله وحده للعبادة: الخلق والملك والرزق والتدبير؛ فالحمد نتيجة البرهان ومطلع محاجة المشركين. أما الفاتحة فتجعل الحمد مدخلًا لعبادة العبد ربه وطلب الهداية منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص200–216.","url":""}]},{"id":"s6-2","number":2,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما الفرق بين التعبير بالخلق في ﴿خلق السماوات والأرض﴾، وبالجعل في ﴿وجعل الظلمات والنور﴾؟","answer":"الخلق يبرز إنشاء أجرام السماوات والأرض على غير مثال، أما الجعل فيجمع الإيجاد مع التصيير والترتيب وإقامة الظلمات والنور في العالم المخلوق؛ والجميع داخل في خلق الله العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص200–216.","url":""}]},{"id":"s6-3","number":3,"surah":6,"verses":[1,3],"verseLabel":"الأنعام: 1، 3","question":"ما سرّ جمع ﴿السماوات﴾ وإفراد ﴿الأرض﴾ في سورة الأنعام؟","answer":"جُمعت السماوات لتعدد طبقاتها وعوالمها، وأُفردت الأرض لأنها عالم الإنسان المشاهد الذي يبدو وحدة متصلة في مقام الخطاب؛ فجمع النظم سعة العلو ووحدة موطن التكليف. وقد دُمج فيه السؤال 17.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص200–216؛ ص233–235.","url":""}]},{"id":"s6-4","number":4,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما سرّ جمع ﴿الظلمات﴾ وإفراد ﴿النور﴾؟","answer":"جُمعت الظلمات لتعدد أسباب الباطل وطرقه ومراتبه، وأُفرد النور لوحدة الحق ومصدره وطريقه؛ ويصدق ذلك على الظلمة والنور الحسيين وما يرمزان إليه من الشرك والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص209–211.","url":""}]},{"id":"s6-5","number":5,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما سرّ تقديم الظلمات على النور؟","answer":"قُدمت لأنها الحالة التي يخرج منها المخاطب إلى الهدى، ولأن الظلمة المقترنة بالعدم أو الليل تسبق ظهور النور في تجربة الخلق؛ ثم جاء النور غايةً كاشفة. والتقديم مناسب للسياق الذي يواجه الكافرين ليخرجهم من ظلماتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص212–214.","url":""}]},{"id":"s6-6","number":6,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم الذين كفروا بربهم يعدلون﴾ بعد دلائل الخلق؟","answer":"﴿ثم﴾ للتراخي الرتبي والتعجيب: بعد وضوح انفراد الله بخلق السماوات والأرض والظلمات والنور يبلغ التناقض غايته حين يجعل الكافر بربه عدلًا وشبيهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص212–216.","url":""}]},{"id":"s6-7","number":7,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما دلالة تقديم ﴿بربهم﴾ في قوله تعالى: ﴿بربهم يعدلون﴾؟","answer":"قدم الجار والمجرور لإبراز موضع الجريمة والتعجيب منه: بربهم، الذي خلق وأنعم وربّاهم، يسوّون غيره! فالتقديم يركز الإنكار على المقابلة بين الرب المنعم والشريك المزعوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص214–216.","url":""}]},{"id":"s6-8","number":8,"surah":6,"verses":[1],"verseLabel":"الأنعام: 1","question":"ما دلالة اختيار فعل ﴿يعدلون﴾ للتعبير عن الشرك؟","answer":"العدل هنا جعل الشيء عدلًا ونظيرًا لغيره، فيصور المشركين يسوّون المخلوق بالخالق، ويتضمن أيضًا ميلهم وعدولهم عن الحق؛ فجمع اللفظ التسوية الجائرة والانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص214–216.","url":""}]},{"id":"s6-9","number":9,"surah":6,"verses":[2],"verseLabel":"الأنعام: 2","question":"ما دلالة قوله تعالى: ﴿هو الذي خلقكم من طين﴾ مع أن أفراد البشر يُخلقون من نطفة؟","answer":"رُد النوع الإنساني إلى أصل أبيه آدم المخلوق من طين، كما أن غذاء الأجسام الذي تتكون منه النطف أصله من الأرض؛ فالتعبير يذكر الجميع بأصل واحد ضعيف وإن تنوعت مراحل خلق الأفراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص217–228.","url":""}]},{"id":"s6-10","number":10,"surah":6,"verses":[2],"verseLabel":"الأنعام: 2","question":"ما دلالة ذكر أجلين في قوله تعالى: ﴿ثم قضى أجلًا وأجل مسمى عنده﴾؟","answer":"على أشهر التفسيرين: الأجل الأول مدة حياة كل إنسان المنتهية بالموت، والثاني أجل البعث والقيامة الذي استأثر الله بعلمه. وقيل الأول ما بين الخلق والموت والثاني أجل كل إنسان المسمى عند الله؛ والمقصود إحاطة تدبيره ببداية الإنسان ونهايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص217–228.","url":""}]},{"id":"s6-11","number":11,"surah":6,"verses":[2],"verseLabel":"الأنعام: 2","question":"ما سرّ تنكير الأجل الأول ووصف الثاني بأنه ﴿مسمى عنده﴾؟","answer":"نُكر الأول لأن آجال الأفراد متعددة لا يحيطون بمقاديرها، أما الثاني فوصف بأنه محدد في علم الله لا يتقدم ولا يتأخر، وقدم ﴿عنده﴾ لإبراز اختصاصه بعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص223–225.","url":""}]},{"id":"s6-12","number":12,"surah":6,"verses":[2],"verseLabel":"الأنعام: 2","question":"ما سرّ تقديم ﴿أجلًا﴾ على ﴿أجل مسمى عنده﴾؟","answer":"جاء الترتيب على ما يلقاه الإنسان: أجله القريب بالموت أولًا، ثم الأجل الجامع للبعث والجزاء؛ فانتقل من نهاية الفرد المشاهدة إلى النهاية الكبرى المغيبة عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص223–225.","url":""}]},{"id":"s6-13","number":13,"surah":6,"verses":[2],"verseLabel":"الأنعام: 2","question":"ما دلالة قوله تعالى: ﴿ثم أنتم تمترون﴾ بعد الاستدلال بالخلق والآجال؟","answer":"﴿ثم﴾ تستبعد شكهم بعد هذه الدلائل، وذكر الضمير ﴿أنتم﴾ يواجههم بالتناقض ويؤكده: أنتم أنفسكم، مع وضوح الخلق والموت والبعث، تمارون في قدرة الله وتوحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص217–228.","url":""}]},{"id":"s6-14","number":14,"surah":6,"verses":[2],"verseLabel":"الأنعام: 2","question":"ما الفرق بين ﴿تمترون﴾ و«تشكّون»؟","answer":"الامتراء شك يصاحبه اضطراب ومماراة وجدال، فهو أشد من التردد النفسي المجرد؛ ولذلك لائم إصرار المشركين على الخصومة بعد قيام دلائل الخلق والأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص217–228.","url":""}]},{"id":"s6-15","number":15,"surah":6,"verses":[3],"verseLabel":"الأنعام: 3","question":"كيف يُفهم قوله تعالى: ﴿وهو الله في السماوات وفي الأرض﴾ مع تنزهه سبحانه عن المكان؟","answer":"المعنى أنه المعبود المسمى الله في السماوات وفي الأرض، أو أن ألوهيته وعلمه وسلطانه نافذة فيهما؛ وليس المراد حلول ذاته في مكان، تعالى الله عن ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص229–236.","url":""}]},{"id":"s6-16","number":16,"surah":6,"verses":[3],"verseLabel":"الأنعام: 3","question":"ما دلالة تكرار حرف الجر في قوله تعالى: ﴿في السماوات وفي الأرض﴾؟","answer":"أعاد ﴿في﴾ ليستقل كل عالم بتقرير ألوهية الله وسلطانه فيه، فلا يتوهم أن الحكم متعلق بالمجموع فقط أو أن له اختصاصًا بعالم دون آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص229–236.","url":""}]},{"id":"s6-17","number":17,"surah":6,"verses":[3],"verseLabel":"الأنعام: 3","question":"ما دلالة إضافة السر والجهر إلى المخاطبين في قوله تعالى: ﴿يعلم سركم وجهركم﴾؟","answer":"الإضافة تحملهم مسؤولية ما يخفون وما يعلنون، وتخص الحجة بأحوالهم التي قد يظنون أن بعضها مستور؛ فعلمه محيط بسر كل واحد وجهره، لا بالمفهوم المجرد وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص229–236.","url":""}]},{"id":"s6-18","number":18,"surah":6,"verses":[3],"verseLabel":"الأنعام: 3","question":"ما سرّ تقديم السر على الجهر؟","answer":"قُدم السر لأنه أخفى على الخلق وأبعد عن وسائل إدراكهم، فعلم الله به أدل على كمال الإحاطة؛ فإذا علم السر فالجهر أولى، ثم انتقل إلى الأعمال المكتسبة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص235.","url":""}]},{"id":"s6-19","number":19,"surah":6,"verses":[3],"verseLabel":"الأنعام: 3","question":"ما دلالة عطف قوله تعالى: ﴿ويعلم ما تكسبون﴾ بعد علمه بسرهم وجهرهم؟","answer":"السر والجهر يشملان ما خفي وظهر من الأقوال والأحوال، ثم عمّ ﴿ما تكسبون﴾ الأفعال التي يختارونها وتعود تبعتها عليهم؛ فانتقل من العلم بالباطن والظاهر إلى العلم بكل عمل مستوجب للجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص229–236.","url":""}]},{"id":"s6-20","number":20,"surah":6,"verses":[3],"verseLabel":"الأنعام: 3","question":"ما دلالة التعبير عن الأعمال بقوله تعالى: ﴿ما تكسبون﴾؟","answer":"الكسب عمل يجلب صاحبه لنفسه ربحًا أو خسارة، فصور الأعمال رصيدًا يعود أثره على فاعله ويستحق عليه الجزاء؛ وبذلك تحمل الكلمة الإنسان نتيجة اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص229–236.","url":""}]},{"id":"s6-21","number":21,"surah":6,"verses":[4],"verseLabel":"الأنعام: 4","question":"ما دلالة تكرار ﴿من﴾ في قوله تعالى: ﴿وما تأتيهم من آية من آيات ربهم﴾؟","answer":"الأولى زائدة في سياق النفي لتأكيد استغراقه: ما تأتيهم أي آية، والثانية تبين جنس تلك الآية ومصدرها، فهي آية من آيات ربهم؛ فتكرر الحرف لاختلاف الوظيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص237–243.","url":""}]},{"id":"s6-22","number":22,"surah":6,"verses":[4],"verseLabel":"الأنعام: 4","question":"ما الصورة في قوله تعالى: ﴿تأتيهم من آية﴾؟","answer":"شُخصت الآية كأنها وافد يأتيهم بالحجة حتى موضعهم، ومع ذلك يتعمدون الإعراض عنها؛ فالصورة تقوي لوم من لم يطلب منه بلوغ الدليل ثم رفضه عند مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص237–243.","url":""}]},{"id":"s6-23","number":23,"surah":6,"verses":[4],"verseLabel":"الأنعام: 4","question":"ما دلالة المضارع في قوله تعالى: ﴿تأتيهم﴾، ودلالة ﴿كانوا﴾ مع ﴿معرضين﴾؟","answer":"المضارع في ﴿تأتيهم﴾ يستحضر تجدد مجيء الآيات، أما ﴿كانوا عنها معرضين﴾ فتقرر أن الإعراض كان جوابهم الثابت كلما جاءت آية؛ فاجتمع تجدد الحجة ورسوخ الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص237–243.","url":""}]},{"id":"s6-24","number":24,"surah":6,"verses":[4],"verseLabel":"الأنعام: 4","question":"ما دلالة تقديم ﴿عنها﴾ في قوله تعالى: ﴿إلا كانوا عنها معرضين﴾؟","answer":"قدم الجار والمجرور لإبراز أن إعراضهم واقع عن الآية نفسها مع كونها من آيات ربهم، ولتوجيه الذم إلى موقفهم منها قبل وصفهم الراسخ بالإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص241–243.","url":""}]},{"id":"s6-25","number":25,"surah":6,"verses":[4],"verseLabel":"الأنعام: 4","question":"ما دلالة وصفهم بقوله تعالى: ﴿معرضين﴾ بالاسم دون: يعرضون؟","answer":"اسم الفاعل يثبت الإعراض صفة راسخة فيهم، لا فعلًا عابرًا يقع ثم يزول؛ ولذلك ناسب تكرر مجيء الآيات مع ثبات موقفهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص237–243.","url":""}]},{"id":"s6-26","number":26,"surah":6,"verses":[4,5],"verseLabel":"الأنعام: 4–5","question":"ما دلالة الانتقال من قوله تعالى: ﴿من آية﴾ إلى قوله: ﴿فقد كذبوا بالحق لما جاءهم﴾؟","answer":"ارتقى الوصف من كون المعروض آية دالة إلى كونه ﴿الحق﴾ نفسه، ليكشف أن إعراضهم ليس عن علامة محتملة بل تكذيب بالحقيقة الثابتة التي جاءت بها الآيات، وفي مقدمتها القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص244–251.","url":""}]},{"id":"s6-27","number":27,"surah":6,"verses":[5],"verseLabel":"الأنعام: 5","question":"ما دلالة تقييد التكذيب بقوله تعالى: ﴿لما جاءهم﴾؟","answer":"يبين أنهم بادروا إلى التكذيب وقت مجيء الحق من غير نظر ولا مهلة تدبر؛ فالجملة تشدد لومهم لأن ردهم لم ينشأ من غياب الحجة بل وقع عند حضورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص244–251.","url":""}]},{"id":"s6-28","number":28,"surah":6,"verses":[5],"verseLabel":"الأنعام: 5","question":"ما دلالة تسمية ما سيأتيهم ﴿أنباء ما كانوا به يستهزئون﴾؟","answer":"ستتحول الوعود والوعيد التي عاملوها أخبارًا للسخرية إلى وقائع ذات نبأ عظيم، فيأتيهم مصداق ما استهزؤوا به ويعلمون حقيقته حين لا ينفع العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص244–251.","url":""}]},{"id":"s6-29","number":29,"surah":6,"verses":[5],"verseLabel":"الأنعام: 5","question":"ما دلالة قوله تعالى: ﴿فسوف يأتيهم﴾ مع إمكان قرب بعض العقوبة؟","answer":"﴿سوف﴾ لا تنفي تحقق الوعيد، بل تفتح زمن مجيئه وتؤكد أنه آتٍ في الوقت الذي يقدره الله، قريبًا في الدنيا أو مؤجلًا إلى الآخرة؛ وفي الإمهال زيادة تهديد لا وعد بالسلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص244–251.","url":""}]},{"id":"s6-30","number":30,"surah":6,"verses":[5],"verseLabel":"الأنعام: 5","question":"ما دلالة تقديم ﴿به﴾ في قوله تعالى: ﴿ما كانوا به يستهزئون﴾؟","answer":"قدم الجار والمجرور لإبراز الشيء الذي اتخذوه محلًا للاستهزاء، وهو بعينه الذي ستأتيهم أنباؤه؛ فالتقديم يصل بين جريمتهم وعاقبتها ويجعل موضع سخريتهم محور التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص249–251.","url":""}]},{"id":"s6-31","number":31,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما دلالة قوله تعالى: ﴿ألم يروا كم أهلكنا من قبلهم من قرن﴾ مع أنهم لم يشاهدوا تلك الأمم؟","answer":"الرؤية هنا علم يقوم على أخبار الأمم وآثارها الباقية التي يمرون بها، حتى صار تاريخها بمنزلة المشاهد؛ والاستفهام يوبخهم على عدم الاعتبار بما يعلمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-32","number":32,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما دلالة تسمية الأمم الماضية ﴿قرنًا﴾؟","answer":"القرن جماعة من الناس اقترنت في زمن واحد أو تعاقبت فيه، فالتعبير يصور كل أمة وحدة تاريخية لها تمكينها ثم تنقضي ويأتي بعدها غيرها؛ وهو أنسب بسياق تعاقب الهلاك والإنشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-33","number":33,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما الفرق بين قوله تعالى: ﴿مكناهم في الأرض﴾ وقوله: ﴿ما لم نمكن لكم﴾؟","answer":"عُدّي الأول بنفسه لإبراز قوة تمكين الأمم السابقة ورسوخه، وجاء الثاني باللام لبيان ما جعل للمخاطبين من أسباب الانتفاع؛ والمقابلة تهددهم بأن من هلك كان أشد تمكينًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص257–260.","url":""}]},{"id":"s6-34","number":34,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما دلالة تقديم السماء في قوله تعالى: ﴿وأرسلنا السماء عليهم مدرارًا﴾؟","answer":"قدمت نعمة الماء النازلة من العلو لأنها أصل ما يتبعها من جريان الأنهار وخصب الأرض، ولتبدو النعمة محيطة بهم من فوقهم ثم من تحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص263.","url":""}]},{"id":"s6-35","number":35,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما دلالة قوله تعالى: ﴿وأرسلنا السماء﴾ مع أن المنزل هو المطر؟","answer":"أطلق المحل وأريد ما ينزل منه، أي المطر، حتى صارت السماء نفسها كأنها مرسلة عليهم بكثرة مائها؛ وفي ذلك مبالغة في وفرة النعمة واتصالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-36","number":36,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما دلالة وصف السماء بقوله تعالى: ﴿مدرارًا﴾؟","answer":"﴿مدرارًا﴾ صيغة مبالغة من الدر، تدل على مطر كثير متتابع غزير لا دفعة عابرة؛ فتلائم تعداد قوة تمكين تلك الأمم وسعة رزقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-37","number":37,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما الصورة في قوله تعالى: ﴿وجعلنا الأنهار تجري من تحتهم﴾؟","answer":"صوّر الأنهار جارية تحت مساكنهم وبساتينهم وفي سلطانهم، ملازمة لمواطن عيشهم لا بعيدة عنهم؛ فاجتمعت لهم نعمة السماء من فوق ونعمة الماء في الأرض من تحت.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-38","number":38,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما دلالة قوله تعالى: ﴿فأهلكناهم بذنوبهم﴾ بعد تفصيل تمكينهم ونعمهم؟","answer":"الفاء تفيد أن النعم والقوة لم تمنع حلول الجزاء حين كفروا، والباء تصرح بسبب الهلاك وهو ذنوبهم؛ فليس الهلاك لعجز في أسبابهم ولا ظلمًا لهم، بل عاقبة كسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-39","number":39,"surah":6,"verses":[6],"verseLabel":"الأنعام: 6","question":"ما سرّ وصف ﴿قرنًا﴾ المفرد بقوله تعالى: ﴿آخرين﴾ بصيغة الجمع؟","answer":"﴿قرن﴾ مفرد في اللفظ لكنه اسم جمع يدل على أناس كثيرين، فراعى الوصف معناه وجاء ﴿آخرين﴾ جمعًا؛ أي أنشأنا جماعة أخرى بعد المهلكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص252–267.","url":""}]},{"id":"s6-40","number":40,"surah":6,"verses":[7],"verseLabel":"الأنعام: 7","question":"ما دلالة تقييد الكتاب بقوله تعالى: ﴿في قرطاس﴾؟","answer":"ذكر القرطاس لينقل الدليل إلى أقصى درجات الحس: كتاب مكتوب في جسم يرونه ويباشرونه، فلا يتعللون بأنه صوت أو خيال؛ ومع ذلك يكشف جوابهم أن المشكلة عناد لا نقص في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص268–274.","url":""}]},{"id":"s6-41","number":41,"surah":6,"verses":[7],"verseLabel":"الأنعام: 7","question":"ما دلالة التصريح بالأيدي في قوله تعالى: ﴿فلمسوه بأيديهم﴾ مع أن اللمس يكون بها غالبًا؟","answer":"ذكر الأيدي توكيدًا للمباشرة الحسية وقطعًا لاحتمال أن يكون المراد نظرًا متخيلًا أو لمسًا مجازيًا؛ فقد جمع الفرض رؤية القرطاس ولمسه بأداة اللمس نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص268–274.","url":""}]},{"id":"s6-42","number":42,"surah":6,"verses":[7],"verseLabel":"الأنعام: 7","question":"ما دلالة افتراض لمس الكتاب وعدم الاكتفاء بمشاهدته؟","answer":"لأنهم قد يزعمون أن المرئي تخييل أو سحر للأبصار، فبلغ بهم البرهان إلى مباشرة القرطاس باليد؛ ليقرر أن عنادهم سيبقى ولو اجتمعت حاستا البصر واللمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص268–274.","url":""}]},{"id":"s6-43","number":43,"surah":6,"verses":[7],"verseLabel":"الأنعام: 7","question":"ما دلالة جوابهم رغم ذلك: ﴿إن هذا إلا سحر مبين﴾؟","answer":"القصر بـ﴿إن... إلا﴾ يكشف إصرارهم على حبس الدليل المحسوس في تهمة السحر، و﴿مبين﴾ تزيد المفارقة؛ فالذي بلغ غاية البيان عندهم سحر ظاهر، مما يثبت أن الاعتراض مكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص268–274.","url":""}]},{"id":"s6-44","number":44,"surah":6,"verses":[8],"verseLabel":"الأنعام: 8","question":"ما دلالة قولهم: ﴿لولا أنزل عليه ملك﴾ دون: لولا جاء معه ملك؟","answer":"طلبوا ملكًا منزلًا من السماء يشهد له أو يكون رسولًا معه، ليجعلوا التصديق موقوفًا على خرق حسي من عند الله؛ فجاء لفظ الإنزال موافقًا لطبيعة المقترح ومصدره المزعوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص275–279.","url":""}]},{"id":"s6-45","number":45,"surah":6,"verses":[8],"verseLabel":"الأنعام: 8","question":"ما دلالة قوله تعالى: ﴿ولو أنزلنا ملكًا لقضي الأمر ثم لا ينظرون﴾؟","answer":"لو نزل الملك على صورته وقامت الآية القاهرة ثم استمر التكذيب لانتهى زمن الاختبار واستحقوا العذاب بلا إمهال، كما جرت سنة الله فيمن طلب آية ثم كفر بها؛ لذلك لم يكن إجابة اقتراحهم رحمة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص275–279.","url":""}]},{"id":"s6-46","number":46,"surah":6,"verses":[8],"verseLabel":"الأنعام: 8","question":"ما دلالة حذف الأمر المقضي في قوله تعالى: ﴿لقضي الأمر﴾؟","answer":"حُذف ليذهب الذهن إلى كل ما يناسب هول المقام من انتهاء الاختبار ونزول الحكم والعذاب والاستئصال؛ فالإبهام يعظم الأمر بدل أن يحصره في لفظ واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص278–279.","url":""}]},{"id":"s6-47","number":47,"surah":6,"verses":[8],"verseLabel":"الأنعام: 8","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم لا ينظرون﴾ دون الفاء؟","answer":"تفيد ﴿ثم﴾ ترتيب ما بعد قضاء الأمر عليه مع إبراز تفاوت الرتبة: بعد صدور الحكم الحاسم لا يبقى لهم أدنى إمهال؛ فجمعت تعاقب الحدثين واستبعاد رجائهم في النظرة بعد القضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص275–279.","url":""}]},{"id":"s6-48","number":48,"surah":6,"verses":[9],"verseLabel":"الأنعام: 9","question":"كيف يُفهم قوله تعالى: ﴿ولو جعلناه ملكًا لجعلناه رجلًا﴾؟","answer":"لا يطيق البشر عادة رؤية الملك على صورته، فلو كان الرسول ملكًا لجعله الله في صورة رجل ليتمكنوا من رؤيته والتلقي عنه؛ وعندئذ يعود الاشتباه نفسه الذي اتخذوه حجة على الرسول البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص280–288.","url":""}]},{"id":"s6-49","number":49,"surah":6,"verses":[9],"verseLabel":"الأنعام: 9","question":"ما دلالة تكرار ﴿جعلناه﴾ في قوله تعالى: ﴿ولو جعلناه ملكًا لجعلناه رجلًا﴾؟","answer":"تعلق الجعل الأول باختيار جنس الرسول المفترض، أي ملكًا، وتعلق الثاني بالصورة التي لا بد أن يظهر بها للناس، أي رجلًا؛ فكل فعل ينشئ مرحلة مختلفة من الفرض والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص280–288.","url":""}]},{"id":"s6-50","number":50,"surah":6,"verses":[9],"verseLabel":"الأنعام: 9","question":"ما دلالة تكرار مادة اللبس في قوله تعالى: ﴿وللبسنا عليهم ما يلبسون﴾؟","answer":"في اللفظ مشاكلة تكشف عاقبة صنيعهم: لو ظهر الملك في صورة رجل لاشتبه عليهم أمره، كما يخلطون هم الحق بالباطل على أنفسهم وعلى غيرهم؛ فاقتراحهم يعيد الالتباس الذي يصنعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص280–288.","url":""}]},{"id":"s6-51","number":51,"surah":6,"verses":[9],"verseLabel":"الأنعام: 9","question":"ما الفرق في التعدية بين ﴿للبسنا عليهم﴾ و﴿ما يلبسون﴾؟","answer":"عُدي الأول بـ﴿على﴾ لبيان من يقع عليه الاشتباه، أما الثاني فحذف متعلقه ليتسع لما يخلطونه من الحق وما يوقعونه من لبس على أنفسهم وغيرهم؛ فالأول يحدد المتلقي والثاني يعمم فعلهم وموضوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص280–288.","url":""}]},{"id":"s6-52","number":52,"surah":6,"verses":[10],"verseLabel":"الأنعام: 10","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿ولقد استهزئ برسل من قبلك﴾؟","answer":"وجه البناء العناية إلى وقوع الاستهزاء بالرسل بوصفه سنة متكررة، لا إلى أسماء المستهزئين؛ وفيه تسلية للنبي ﷺ بأن ما لقيه قد لقيه رسل قبله ثم كانت العاقبة للمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص289–297.","url":""}]},{"id":"s6-53","number":53,"surah":6,"verses":[10],"verseLabel":"الأنعام: 10","question":"ما دلالة تنكير ﴿رسل﴾ في قوله تعالى: ﴿برسل من قبلك﴾؟","answer":"التنكير يدل على كثرة رسل غير معينين وقع بهم مثل ذلك، فيوسع مجال التسلية ويقرر أن الاستهزاء لم يكن خاصًا برسول أو أمة؛ كما يعظم شأن من ثبت منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص289–297.","url":""}]},{"id":"s6-54","number":54,"surah":6,"verses":[10],"verseLabel":"الأنعام: 10","question":"ما الصورة في قوله تعالى: ﴿فحاق بالذين سخروا منهم﴾؟","answer":"الحَيْق نزول المكروه وإحاطته بصاحبه والتصاقه به، فصور الجزاء يطوق الساخرين فلا يجدون منه مهربًا؛ وانقلب ما اتخذوه موضع استهزاء سببًا لعذابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص289–297.","url":""}]},{"id":"s6-55","number":55,"surah":6,"verses":[10],"verseLabel":"الأنعام: 10","question":"ما دلالة التنويع بين ﴿استهزئ﴾ و﴿سخروا﴾ و﴿يستهزئون﴾؟","answer":"بدأ بالمبني للمجهول لبيان سنة الاستهزاء بالرسل، ثم صرح بالسخرية مسندة إلى فاعليها عند ذكر الجزاء، ثم جاء المضارع ﴿يستهزئون﴾ لاستحضار فعلهم المتجدد الذي صار وباله محيطًا بهم؛ فتغيرت الصيغ بتغير المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص289–297.","url":""}]},{"id":"s6-56","number":56,"surah":6,"verses":[10],"verseLabel":"الأنعام: 10","question":"ما دلالة قوله تعالى: ﴿وحاق بهم ما كانوا به يستهزئون﴾، فكأن المستهزأ به هو الذي حاق بهم؟","answer":"المراد أن جزاء ما استهزؤوا به أو العذاب الذي أخبر به الرسل حاق بهم، فحذف المضاف ليقوى الارتباط بين الجريمة وعاقبتها؛ كأن الخبر الذي سخروا منه عاد واقعًا يحيط بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص289–297.","url":""}]},{"id":"s6-57","number":57,"surah":6,"verses":[11],"verseLabel":"الأنعام: 11","question":"ما دلالة الأمر بقوله تعالى: ﴿قل سيروا في الأرض﴾ دون: امشوا أو سافروا؟","answer":"السير حركة ممتدة مقصودة في البلاد، أعم من المشي على الأقدام وأوثق صلة بالتأمل في الآثار؛ فليس المراد انتقالًا عابرًا بل رحلة اعتبار تكشف سنن المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص298–305.","url":""}]},{"id":"s6-58","number":58,"surah":6,"verses":[11],"verseLabel":"الأنعام: 11","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم انظروا﴾ دون الفاء؟","answer":"تدل ﴿ثم﴾ على أن النظر المعتبر يأتي بعد سير يتيح مشاهدة الآثار وجمع الشواهد، وأن المطلوب تجاوز المرور السريع إلى تأمل متأن في العاقبة؛ فبين الحركة والاعتبار مهلة فكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص303–305.","url":""}]},{"id":"s6-59","number":59,"surah":6,"verses":[11],"verseLabel":"الأنعام: 11","question":"ما دلالة قوله تعالى: ﴿كيف كان عاقبة المكذبين﴾ دون: ماذا كانت عاقبتهم؟","answer":"﴿كيف﴾ تسأل عن هيئة النهاية وفظاعتها، لا عن اسمها أو مجرد وقوعها؛ فتدعو إلى تأمل صور الهلاك وآثاره وتفاصيله التي يشاهدها السائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص298–305.","url":""}]},{"id":"s6-60","number":60,"surah":6,"verses":[11],"verseLabel":"الأنعام: 11","question":"ما سرّ وصف الهالكين بـ﴿المكذبين﴾ بعد ذكر الاستهزاء؟","answer":"لأن التكذيب أصل موقفهم من الرسل، والاستهزاء مظهر زائد ناشئ عنه؛ فعند الدعوة إلى الاعتبار بعاقبتهم سماهم بالوصف الذي استوجب الهلاك وجمع صور ردهم للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص298–305.","url":""}]},{"id":"s6-61","number":61,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما دلالة أن يسأل النبي ﷺ: ﴿قل لمن ما في السماوات والأرض﴾ ثم يتولى الجواب: ﴿قل لله﴾؟","answer":"لأن الخصم لا يملك جوابًا صحيحًا إلا الإقرار بملك الله أو المكابرة بما تعرف الفطرة بطلانه، فتولى الوحي الجواب ليقرر الحجة سريعًا ولا يترك للمراوغة مجالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص306–316.","url":""}]},{"id":"s6-62","number":62,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما دلالة تقديم ﴿لله﴾ في جواب قوله تعالى: ﴿قل لله﴾؟","answer":"تقديم الجار والمجرور يفيد قصر ملك ما في السماوات والأرض على الله وحده، وهو المقصود من السؤال والحجة على بطلان ولاية غيره وعبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص306–316.","url":""}]},{"id":"s6-63","number":63,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما الصورة في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"الكتابة استعارة للعهد المؤكد الثابت الذي تفضل الله فأوجبه على نفسه، لا لإلزام مخلوق له؛ فصوّرت الرحمة حكمًا مكتوبًا محققًا مع بقاء السيادة المطلقة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص306–316.","url":""}]},{"id":"s6-64","number":64,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما دلالة تعدية الكتابة بـ﴿على﴾ في قوله تعالى: ﴿كتب على نفسه الرحمة﴾؟","answer":"تفيد ﴿على﴾ معنى الالتزام والوجوب المؤكد، أي ألزم ذاته العلية الرحمة تفضلًا منه ووعدًا لا يخلفه، لا لأن أحدًا أوجب عليه شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص306–316.","url":""}]},{"id":"s6-65","number":65,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما مناسبة الانتقال من كتابة الرحمة إلى التهديد بالجمع يوم القيامة؟","answer":"من رحمته أن أمهل الخلق وأرسل إليهم وأنذرهم، ومن تمام الرحمة والعدل أن يجمعهم للجزاء فلا يضيع حق ولا يستوي الطيب والخبيث؛ فالقيامة ليست نقيض الرحمة، بل موضع تمام آثارها وعدلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص306–316.","url":""}]},{"id":"s6-66","number":66,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما دلالة اجتماع اللام والنون في قوله تعالى: ﴿ليجمعنكم﴾؟","answer":"اللام موطئة لقسم مقدر، ونون التوكيد الثقيلة تثبت وقوع الجمع تثبيتًا قويًا؛ فاجتمعتا لمواجهة إنكار البعث وإزالة كل ريب في مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص311–313.","url":""}]},{"id":"s6-67","number":67,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما دلالة قوله تعالى: ﴿إلى يوم القيامة﴾ دون: في يوم القيامة؟","answer":"﴿إلى﴾ تصور الجمع متجهًا بالخلق إلى اليوم المحدد غايةً لمسيرهم، وتشعر بضم بعضهم إلى بعض حتى بلوغ ذلك الموعد؛ أما ﴿في﴾ فكانت ستقتصر على ظرف وقوع الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص311–313.","url":""}]},{"id":"s6-68","number":68,"surah":6,"verses":[12],"verseLabel":"الأنعام: 12","question":"ما دلالة قوله تعالى: ﴿الذين خسروا أنفسهم فهم لا يؤمنون﴾؟","answer":"الخسارة أصابت رأس مالهم الحقيقي، وهو أنفسهم ومصيرهم، لا شيئًا خارجًا عنهم؛ والفاء تبين أن عدم الإيمان علامة هذه الخسارة وسبب رسوخها، لا مجرد وصف منفصل عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص306–316.","url":""}]},{"id":"s6-69","number":69,"surah":6,"verses":[13],"verseLabel":"الأنعام: 13","question":"ما دلالة قوله تعالى: ﴿وله ما سكن في الليل والنهار﴾ بعد تقرير ملك ما في السماوات والأرض؟","answer":"انتقل من استيعاب المكان إلى استيعاب الزمان؛ فما في السماوات والأرض ملكه أينما كان، وما حل في الليل والنهار ملكه في كل وقت، فتتكامل إحاطة الملك بالمكان والزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص317–323.","url":""}]},{"id":"s6-70","number":70,"surah":6,"verses":[13],"verseLabel":"الأنعام: 13","question":"ما دلالة التعبير بـ﴿سكن﴾ مع أن ملك الله يشمل الساكن والمتحرك؟","answer":"السكون هنا يحتمل معنى الحلول والاستقرار في الليل والنهار، فيشمل الموجودات التي تكتنفها أوقاتهما، كما أن ذكر الساكن لا يخرج المتحرك بل يدل عليه بطريق الأولى؛ فالمقصود عموم ما يحتويه الزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص317–323.","url":""}]},{"id":"s6-71","number":71,"surah":6,"verses":[13],"verseLabel":"الأنعام: 13","question":"ما دلالة قوله تعالى: ﴿في الليل والنهار﴾ دون: في الزمان كله؟","answer":"الليل والنهار صورتان محسوسـتان تتعاقبان وتستوعبان زمن البشر، فالتعبير بهما يجسد الإحاطة بكل وقت ويذكر باختلاف أحوال المخلوقات فيهما، بخلاف اللفظ التجريدي العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص317–323.","url":""}]},{"id":"s6-72","number":72,"surah":6,"verses":[13],"verseLabel":"الأنعام: 13","question":"ما دلالة تقديم ﴿له﴾ في قوله تعالى: ﴿وله ما سكن﴾؟","answer":"يفيد التقديم اختصاص الملك الحقيقي بالله لكل ما يحتويه الليل والنهار؛ فلا يخرج موجود في أي وقت عن سلطانه، وهو استمرار لقصر الملك في الآية السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص318–319.","url":""}]},{"id":"s6-73","number":73,"surah":6,"verses":[13],"verseLabel":"الأنعام: 13","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وهو السميع العليم﴾ بعد ملك ما في الليل والنهار؟","answer":"ملكه ليس ملكًا بلا إحاطة؛ فهو يسمع أصوات ما يسكن ويتحرك في كل وقت، ويعلم الظاهر والخفي من أحواله. فربطت الخاتمة سلطان الملك بكمال المراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص321–323.","url":""}]},{"id":"s6-74","number":74,"surah":6,"verses":[13],"verseLabel":"الأنعام: 13","question":"ما سرّ تقديم ﴿السميع﴾ على ﴿العليم﴾؟","answer":"قدم السمع لأنه طريق خاص لإدراك الأقوال والأصوات التي قد تخفى في سكون الليل، ثم جاء العلم الأعم المحيط بالأقوال وغيرها؛ فانتقل من الخاص المناسب للصورة إلى الصفة الأشمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص321–323.","url":""}]},{"id":"s6-75","number":75,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"ما دلالة تقديم ﴿غير الله﴾ في قوله تعالى: ﴿أغير الله أتخذ وليًا﴾؟","answer":"قدم المفعول لأن إنكار اتخاذ غير الله هو محور السؤال، ويفيد السياق القصر: لا أتخذ وليًا مستحقًا للعبادة والنصرة من دون الله؛ فالمرفوض ذات البديل قبل فعل الاتخاذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص324–333.","url":""}]},{"id":"s6-76","number":76,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"ما دلالة وصف الله بأنه ﴿فاطر السماوات والأرض﴾ دون: خالق السماوات والأرض؟","answer":"الفاطر هو المبتدئ للخلق وشاق العدم بإيجاده على غير مثال، فناسب مقام نفي اتخاذ ولي غيره؛ فالذي بدأ الكون وأوجده أولى وحده بالولاية من كل مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص324–333.","url":""}]},{"id":"s6-77","number":77,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"ما دلالة قوله تعالى: ﴿وهو يطعم ولا يطعم﴾ في الاستدلال على استحقاق الله للولاية؟","answer":"الإطعام مظهر الربوبية والرزق، وعدم الحاجة إلى الطعام دليل الغنى المطلق؛ فجمع الطرفان إنعامه على خلقه وتنزهه عن افتقارهم، ومن كان كذلك استحق الولاية والعبادة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص328–330.","url":""}]},{"id":"s6-78","number":78,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"ما دلالة تكرار الأمر ﴿قل﴾ في الآية؟","answer":"جدد ﴿قل﴾ كل إعلان مستقل: إنكار اتخاذ ولي غير الله، ثم التصريح بأمره أن يكون أول من أسلم والتحذير من الشرك؛ فتكراره يفصل مقامات الحجة ويؤكد أن كل جواب وحي مأمور بإبلاغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص330–333.","url":""}]},{"id":"s6-79","number":79,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"كيف يُفهم قوله تعالى: ﴿أمرت أن أكون أول من أسلم﴾ مع سبق الأنبياء والمؤمنين؟","answer":"أي أول من أسلم من هذه الأمة ومن المخاطبين برسالته، أو أولهم مبادرةً وامتثالًا فيما كُلّف بتبليغه؛ فلا ينفي إسلام الأنبياء وأتباعهم في الأمم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص330–333.","url":""}]},{"id":"s6-80","number":80,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"ما دلالة الانتقال من قوله تعالى: ﴿إني أمرت﴾ إلى الخطاب المباشر: ﴿ولا تكونن من المشركين﴾؟","answer":"حكى أولًا الأمر الذي تلقاه بالإسلام، ثم جاء النهي موجهًا إليه مباشرةً ليشتد وقعه ويبلغ الأمة من ورائه؛ فالانتقال من الخبر عن التكليف إلى خطاب التحذير يجعل البراءة من الشرك حاضرة مؤكدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص331–333.","url":""}]},{"id":"s6-81","number":81,"surah":6,"verses":[14],"verseLabel":"الأنعام: 14","question":"ما دلالة قوله تعالى: ﴿من المشركين﴾ دون: مشركًا؟","answer":"النهي عن أن يكون مندرجًا في جماعة المشركين أو منتسبًا إلى طريقهم، وهو أبلغ من نفي وصف مفرد؛ لأنه يقطع الفعل والانتماء والموالاة لمنهج الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص331–333.","url":""}]},{"id":"s6-82","number":82,"surah":6,"verses":[15],"verseLabel":"الأنعام: 15","question":"ما دلالة قول النبي ﷺ: ﴿إني أخاف إن عصيت ربي عذاب يوم عظيم﴾ مع عصمته؟","answer":"الشرط فرض للتعليم والتعريض بالمشركين: إذا كان الرسول مع عصمته يعلن خوفه من عاقبة العصيان، فغيره أولى بالخوف. وفيه بيان أن أحدًا لا يستحق العبادة أو يأمن حكم الله بذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص334–343.","url":""}]},{"id":"s6-83","number":83,"surah":6,"verses":[15],"verseLabel":"الأنعام: 15","question":"ما دلالة الماضي في قوله تعالى: ﴿إن عصيت﴾ مع أن الشرط مفترض؟","answer":"يأتي الماضي بعد أداة الشرط لتصوير الفعل المفروض كأنه تحقق واستحضر أثره، وللدلالة على جدية الملازمة بين العصيان والعذاب؛ فلا يعني أن المعصية وقعت من النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص338–340.","url":""}]},{"id":"s6-84","number":84,"surah":6,"verses":[15],"verseLabel":"الأنعام: 15","question":"ما دلالة قوله تعالى: ﴿عصيت ربي﴾ دون: عصيت الله؟","answer":"وصف الربوبية يستحضر التربية والنعمة والرعاية، فتبدو المعصية أقبح لأنها مقابلة لإحسان الرب بالعصيان؛ كما يلائم ما سبق من الاستدلال بالخلق والإطعام والولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص334–343.","url":""}]},{"id":"s6-85","number":85,"surah":6,"verses":[15],"verseLabel":"الأنعام: 15","question":"ما دلالة قوله تعالى: ﴿عذاب يوم عظيم﴾ بوصف اليوم بالعظمة دون العذاب؟","answer":"نُقلت العظمة إلى اليوم لأنه ظرف يجمع أهوالًا متعددة، فيعظم العذاب بعظمة اليوم كله وما يقع فيه من بعث وحساب وجزاء، لا بوصف ألم واحد فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص340–343.","url":""}]},{"id":"s6-86","number":86,"surah":6,"verses":[16],"verseLabel":"الأنعام: 16","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿من يصرف عنه يومئذ فقد رحمه﴾؟","answer":"بُني ﴿يُصرف﴾ للمجهول لتوجيه النظر إلى النعمة العظمى، وهي صرف العذاب عن الإنسان، مع العلم أن الصارف هو الله من قوله ﴿فقد رحمه﴾؛ فبرز حال الناجي وافتقاره إلى الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص339–343.","url":""}]},{"id":"s6-87","number":87,"surah":6,"verses":[16],"verseLabel":"الأنعام: 16","question":"ما دلالة تقديم ﴿عنه﴾ في قوله تعالى: ﴿من يصرف عنه يومئذ﴾؟","answer":"قدم الجار والمجرور للعناية بمن نجا عنه العذاب في ذلك اليوم، وليربط الصرف مباشرةً بذات العبد المحتاج قبل التصريح بأن نجاته رحمة؛ فمحور الجملة حال المرحوم لا وصف العذاب وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص339–343.","url":""}]},{"id":"s6-88","number":88,"surah":6,"verses":[16],"verseLabel":"الأنعام: 16","question":"ما دلالة التعبير عن النجاة من العذاب بقوله تعالى: ﴿فقد رحمه﴾ دون: فقد نجا؟","answer":"لأن النجاة ليست ثمرة قوة العبد واستقلاله، بل أثر رحمة الله؛ فعدل إلى السبب الأعلى الذي يشمل صرف العذاب وإيصال الخير، ويمنع الاغترار بالعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص339–343.","url":""}]},{"id":"s6-89","number":89,"surah":6,"verses":[16],"verseLabel":"الأنعام: 16","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وذلك الفوز المبين﴾؟","answer":"أشار ﴿ذلك﴾ إلى صرف العذاب ونيل الرحمة، وسماه الفوز الواضح لأنه جمع النجاة من أعظم مرهوب وتحصيل أعظم مطلوب؛ فلا فوز يقاس به يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص339–343.","url":""}]},{"id":"s6-90","number":90,"surah":6,"verses":[17],"verseLabel":"الأنعام: 17","question":"ما دلالة اختيار المس في قوله تعالى: ﴿وإن يمسسك الله بضر﴾؟","answer":"المس أخف درجات الاتصال، فدل على أن أدنى ضر يقدره الله على العبد لا يملك كشفه غيره؛ وإذا كان الحكم في المس اليسير كذلك فما فوقه أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-91","number":91,"surah":6,"verses":[17],"verseLabel":"الأنعام: 17","question":"ما دلالة مقابلة ﴿بضر﴾ بقوله تعالى: ﴿بخير﴾ دون: بنفع؟","answer":"الخير أوسع من النفع؛ فهو يشمل كل ما يحسن في ذاته أو عاقبته من رزق وعافية وهداية، أما النفع فقد يلحظ مجرد الفائدة العاجلة. فوسعت المقابلة مجال فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-92","number":92,"surah":6,"verses":[17],"verseLabel":"الأنعام: 17","question":"ما سرّ ذكر قوله تعالى في الضر: ﴿فلا كاشف له إلا هو﴾، وعدم ذكر جملة مماثلة عند الخير؟","answer":"الضر إذا وقع تعلق القلب بكشفه، فنفى الله كل كاشف سواه. أما الخير فانتقل منه إلى القاعدة الأعم: ﴿فهو على كل شيء قدير﴾، فتشمل قدرته إعطاء الخير وحفظه وزيادته وكل ما وراء ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-93","number":93,"surah":6,"verses":[17],"verseLabel":"الأنعام: 17","question":"ما دلالة اختيار ﴿كاشف﴾ لإزالة الضر؟","answer":"الكشف رفع غطاء عما تحته، فصوّر الضر كأنه غاشية أحاطت بالإنسان لا يزيحها عنه إلا الله؛ وهو أبلغ في تصوير انجلاء الكرب من لفظ الإزالة المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-94","number":94,"surah":6,"verses":[17],"verseLabel":"الأنعام: 17","question":"ما دلالة الانتقال في جانب الخير إلى قوله تعالى: ﴿فهو على كل شيء قدير﴾؟","answer":"بدل أن يقصر الكلام على إيصال الخير، قرر قدرة عامة تشمل منحه ومنعه وحفظه، وتشمل كشف الضر وسائر الممكنات؛ فاستدل بالجزأين على القاعدة الكلية التي تبطل التعلق بغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-95","number":95,"surah":6,"verses":[18],"verseLabel":"الأنعام: 18","question":"ما دلالة وصف الله هنا بـ﴿القاهر﴾ دون ﴿القهار﴾؟","answer":"﴿القاهر﴾ اسم فاعل يثبت صفة الغلبة في المقام المتعلق بقهره لعباده، أما ﴿القهار﴾ فصيغة مبالغة تبرز كثرة القهر وتكرره في مقامات أخرى. وليس في ﴿القاهر﴾ نقص، بل اختير ما يلائم تركيب ﴿فوق عباده﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-96","number":96,"surah":6,"verses":[18],"verseLabel":"الأنعام: 18","question":"كيف يُفهم قوله تعالى: ﴿وهو القاهر فوق عباده﴾، وهل المراد فوقية مكان تحيط به؟","answer":"تثبت الآية علو الله وقهره وسلطانه على عباده على الوجه اللائق به، لا علو جسم يحويه مكان أو يشبه المخلوق؛ و﴿القاهر﴾ يوضح أن المقام مقام غلبة وسيادة لا يخرج عنها أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-97","number":97,"surah":6,"verses":[18],"verseLabel":"الأنعام: 18","question":"ما دلالة قوله تعالى: ﴿فوق عباده﴾ دون: فوق خلقه؟","answer":"وصف العباد يبرز خضوعهم وافتقارهم وكونهم مملوكين له، فيناسب القهر والسيادة، كما يذكر المكلفين بأنهم عبيد لا يملكون الاستقلال عن حكم ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-98","number":98,"surah":6,"verses":[18],"verseLabel":"الأنعام: 18","question":"ما دلالة تكرار الضمير في قوله تعالى: ﴿وهو القاهر فوق عباده وهو الحكيم الخبير﴾؟","answer":"أعاد ﴿هو﴾ لتستقل الجملة الثانية بتقرير حكمته وخبرته كما استقلت الأولى بقهره، وليؤكد أن القاهر نفسه لا يجري قهره إلا بحكمة وعلم؛ فالتكرار يجمع السلطان وعدله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-99","number":99,"surah":6,"verses":[18],"verseLabel":"الأنعام: 18","question":"ما مناسبة الجمع بين ﴿الحكيم﴾ و﴿الخبير﴾ بعد ذكر القهر؟","answer":"الحكيم يضع قهره وتدبيره في موضعهما فلا يظلم، والخبير يعلم دقائق أحوال عباده وظواهرهم وبواطنهم؛ فليست غلبته قوة مجردة، بل سلطان قائم على العلم والحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص351–355.","url":""}]},{"id":"s6-100","number":100,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما سرّ الاستفهام بـ﴿أي شيء أكبر شهادة﴾، دون: مَن أكبر الشهداء؟","answer":"لفظ ﴿شيء﴾ من أعم الألفاظ، فوسّع دائرة المفاضلة لتشمل كل ما يمكن أن تُتصوّر له شهادة، ثم جاء الجواب بأن الله أكبر شهادة؛ فلا تبقى شهادة تقابل شهادته أو تدانيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-101","number":101,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة اجتماع السؤال والجواب في قوله تعالى: ﴿قل أي شيء أكبر شهادة قل الله﴾؟","answer":"الاستفهام يوقظ السامع ويهيئه لتلقي الحجة، ثم يتولى الوحي الجواب لأن القضية لا تحتمل جوابًا سواه: الله هو الأكبر شهادة. فجمع الأسلوب بين إثارة النظر وحسم النتيجة التي لا يستطيع الخصم دفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-102","number":102,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة التعبير باسم ﴿شهيد﴾ في قوله تعالى: ﴿قل الله شهيد بيني وبينكم﴾؟","answer":"﴿شهيد﴾ صيغة تدل على ثبوت الشهادة وقوتها وإحاطتها؛ وشهادة الله منزّهة عن الكذب والخطأ والسهو، وتظهر فيما أقامه من آيات وبراهين على صدق رسوله ﷺ. فناسب الاسم مقام الاحتكام الفاصل بين الرسول والمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-103","number":103,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة تكرار ﴿بين﴾ في قوله تعالى: ﴿بيني وبينكم﴾؟","answer":"أعيدت ﴿بين﴾ مع الطرف الثاني لإظهار طرفي الخصومة مستقلين في مقام الاحتكام: الرسول ﷺ من جهة، والمكذبون من جهة أخرى. والتكرار هو الأسلوب العربي المبين للعلاقة بين جانبين، وفيه تقوية لصورة الفصل بالشهادة بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-104","number":104,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة بناء الفعل للمفعول في قوله تعالى: ﴿وأوحي إلي هذا القرآن﴾؟","answer":"حُذف فاعل الوحي للعلم به؛ فالسياق قد عيّن أن الله هو الشهيد وهو موحي القرآن، وتوجه الاهتمام إلى نفس الوحي الواصل إلى الرسول ﷺ وإلى الكتاب الذي صار حجةً وإنذارًا. فالحذف لا يُجهّل المصدر، بل يبرز موضع الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-105","number":105,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة الإشارة إلى الوحي بقوله تعالى: ﴿هذا القرآن﴾؟","answer":"اسم الإشارة يستحضر القرآن المتلو الحاضر بين أيديهم، فيجعل الحجة المشار إليها معينةً يمكن سماعها وتدبرها، لا دعوى غائبة. وتسميته قرآنًا تبرز كونه مقروءًا متلوًا تقوم ألفاظه ومعانيه بالإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-106","number":106,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة جعل القرآن وسيلة الإنذار في قوله تعالى: ﴿لأنذركم به﴾؟","answer":"الباء تجعل القرآن نفسه أداة الإنذار؛ لأن ما فيه من الحجج والوعد والوعيد هو الذي يبلغ القلوب ويحذرها العاقبة. واقتُصر على الإنذار لمناسبة خطاب المكابرين، مع بقاء البشارة مفهومة من سائر مقاصد القرآن ومواضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-107","number":107,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة حذف مفعول ﴿بلغ﴾ في قوله تعالى: ﴿ومن بلغ﴾؟","answer":"التقدير: ومن بلغه القرآن، وحذف الضمير لاتضاحه من السياق ولتوسيع معنى البلاغ وطرقه؛ فكل من وصل إليه القرآن أو بلغه معناه على وجه تقوم به الحجة داخل في الإنذار، عربيًا كان أو غير عربي، في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-108","number":108,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة عطف ﴿ومن بلغ﴾ على المخاطبين في قوله تعالى: ﴿لأنذركم به ومن بلغ﴾؟","answer":"نقل العطف الإنذار من المخاطبين الأولين في مكة إلى كل إنسان يبلغه القرآن؛ فمن بلغه بعد الرسول ﷺ فكأنما سمعه منه ما دام قد وصل إليه بلا زيادة ولا نقصان. وبذلك دلّ التركيب على عموم الرسالة واستمرار حجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-109","number":109,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما مناسبة الاستفهام ﴿أئنكم لتشهدون أن مع الله آلهة أخرى﴾ بعد إقامة شهادة الله؟","answer":"بعد أن ثبت أن شهادة الله هي الكبرى وأن القرآن وحيه، وُوجهوا بلازم عقيدتهم: أيملكون أن يشهدوا شهادة تقابل تلك الحجة بأن مع الله آلهة؟ فالاستفهام إنكاري توبيخي يكشف استحالة قيام شهادتهم على برهان، ويستقصي الإعذار لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-110","number":110,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما سرّ وصف جمع ﴿آلهة﴾ بالمفرد المؤنث ﴿أخرى﴾؟","answer":"﴿آلهة﴾ جمع لغير العاقل، ووصف جمع غير العاقل يجري مجرى المفردة المؤنثة؛ فقيل ﴿أخرى﴾. وفي ذلك أيضًا جمع لهذه المعبودات في وصف واحد، والتنبيه على ضعفها وهوان أمرها وبطلان تسميتها آلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-111","number":111,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة تكرار الأمر ﴿قل﴾ أربع مرات في الآية؟","answer":"تكرر ﴿قل﴾ أربع مرات لأن كل مقولة بعدها رسالة مستقلة عظيمة يجب إعلانها: طرح الحجة، وتعيين الله شهيدًا، ورفض شهادة الشرك، وإعلان التوحيد والبراءة منه. وفي التكرار تلقين للنبي ﷺ وتثبيت وعناية، وتنبيه إلى أهمية كل جواب ومبادرة تبليغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-112","number":112,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة الجواب الموجز الحاسم: ﴿قل لا أشهد﴾؟","answer":"جاء النفي مباشرًا ليقطع كل احتمال لموافقتهم على شهادة الشرك؛ فلا يدخل الرسول ﷺ معهم في أصل الدعوى ولا يطيل مناقشة شهادة لا برهان لها. ثم أعقب الرفض بإثبات الحق: ﴿قل إنما هو إله واحد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-113","number":113,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة القصر في قوله تعالى: ﴿إنما هو إله واحد﴾؟","answer":"قصر الألوهية على الله وحده، فنفى أن يكون معه إله آخر يستحق العبادة. وجاء الضمير عائدًا إلى الله المذكور قبلُ، فاستغنى به عن تكرار الاسم، وانتقل الكلام من نفي شهادة الشرك إلى تقرير حقيقة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-114","number":114,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة التعبير بالاسم ﴿بريء﴾ في قوله تعالى: ﴿وإنني بريء مما تشركون﴾؟","answer":"الاسم يدل على ثبوت البراءة واستقرارها، لا على فعل عارض يقع مرة؛ والبراءة في أصلها تخلّص ومفارقة وتباعد مما يُكره. فالصيغة إعلان دائم قاطع بمفارقة الشرك وما يُعبد من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-115","number":115,"surah":6,"verses":[19],"verseLabel":"الأنعام: 19","question":"ما دلالة عموم قوله تعالى: ﴿مما تشركون﴾؟","answer":"الموصول ﴿ما﴾ يعم كل ما يجعلونه شريكًا لله، والتعبير بالفعل يستحضر فعل الإشراك المتجدد ولا يقتصر على أسماء أصنام بعينها. فالبراءة شاملة للمعبودات الباطلة وللمنهج الذي يسوّيها بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص356–381.","url":""}]},{"id":"s6-116","number":116,"surah":6,"verses":[20],"verseLabel":"الأنعام: 20","question":"إلى مَن يعود الضمير في قوله تعالى: ﴿يعرفونه كما يعرفون أبناءهم﴾؟","answer":"يعود الضمير إلى النبي محمد ﷺ؛ أي إن علماء أهل الكتاب يعرفونه بحليته ونعته الثابت في كتبهم كما يعرفون أبناءهم. وجاءت الآية حجة على المكذبين بمعرفة أهل الكتاب بصدق نبوته، مع أن بعض المفسرين وسّع مرجع الضمير إلى القرآن أو الحق المتقدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص382–394.","url":""}]},{"id":"s6-117","number":117,"surah":6,"verses":[20],"verseLabel":"الأنعام: 20","question":"ما دلالة التعبير بالموصول في قوله تعالى: ﴿الذين آتيناهم الكتاب﴾؟","answer":"عرّفهم بالصلة التي هي موضع الحجة: إيتاؤهم الكتاب ودراستهم له. فالمقصود خاصة علماؤهم الذين عرفوا ما في التوراة والإنجيل من صفة النبي ﷺ، لا كل منتسب إلى أهل الكتاب؛ وبذلك صار علمهم سببًا للاحتجاج بشهادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص382–394.","url":""}]},{"id":"s6-118","number":118,"surah":6,"verses":[20],"verseLabel":"الأنعام: 20","question":"ما دلالة تعريف ﴿الكتاب﴾ في قوله تعالى: ﴿آتيناهم الكتاب﴾؟","answer":"التعريف للعهد؛ أي الكتاب المعروف الذي أوتيته كل طائفة، وهو التوراة لليهود والإنجيل للنصارى. وفي التعريف استحضار المرجع الذي قامت به معرفتهم، فلا تصدر شهادتهم عن ظن بل عما وجدوه في الوحي الذي بأيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص382–394.","url":""}]},{"id":"s6-119","number":119,"surah":6,"verses":[20],"verseLabel":"الأنعام: 20","question":"ما دلالة التعبير بـ﴿يعرفونه﴾، دون: يعلمونه؟","answer":"المعرفة تتعلق بذات الشيء وتمييزه من آثاره وصفاته، أما العلم فيتسع للحكم على أحواله ونِسَبه؛ فناسبت ﴿يعرفونه﴾ معرفتهم شخص النبي ﷺ بصفته ونعته، كما تُعرف ذات الابن معرفة لا اشتباه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص382–394.","url":""}]},{"id":"s6-120","number":120,"surah":6,"verses":[20],"verseLabel":"الأنعام: 20","question":"ما سرّ تشبيه معرفتهم بالنبي ﷺ بمعرفتهم أبناءهم خاصة؟","answer":"الابن من ألصق الناس بأبيه وأكثرهم حضورًا بين يديه، وتتميز صورته وصفاته لديه بلا التباس؛ فالتشبيه يقرر شدة وضوح صفة النبي ﷺ في كتبهم وتمكن معرفتهم بها، لا مجرد علم بعيد أو محتمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص382–394.","url":""}]},{"id":"s6-121","number":121,"surah":6,"verses":[20],"verseLabel":"الأنعام: 20","question":"ما مناسبة تكرار قوله تعالى: ﴿الذين خسروا أنفسهم فهم لا يؤمنون﴾ بعد وروده في الآية 12؟","answer":"في الآية 12 جاء وصف الخسران عقب تقرير ملك الله ورحمته وجمع الناس للقيامة، أما هنا فجاء عقب ثبوت معرفة أهل الكتاب بالنبي ﷺ؛ فالأول يبين خسارة من أعرض عن دلائل التوحيد والبعث، والثاني يفضح من عرف الرسول ثم كتم معرفته ولم يؤمن. اتحد الحكم واختلف سبب إبرازه في السياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص382–394؛ وانظر ص314–322 في الآية 12.","url":""}]},{"id":"s6-122","number":122,"surah":6,"verses":[21],"verseLabel":"الأنعام: 21","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"الاستفهام إنكاري يفيد أنه لا أحد أبلغ ظلمًا ممن اختلق على الله أو كذب بآياته؛ لأن الجريمتين تفسدان أصل الهداية: إحداهما تنسب إلى الله ما لم يقل، والأخرى ترد ما أقام عليه حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص395–407.","url":""}]},{"id":"s6-123","number":123,"surah":6,"verses":[21],"verseLabel":"الأنعام: 21","question":"ما دلالة صيغة أفعل التفضيل في قوله تعالى: ﴿أظلم﴾؟","answer":"تدل ﴿أظلم﴾ على بلوغ المفترين والمكذبين أعلى درجات الظلم؛ لعظم جرأتهم على الله بنسبة الشريك أو الولد إليه، ولتكذيبهم بآياته وإنكار رسوله. والاستفهام المصاحب ينفي أن يوجد من هو أشد منهم ظلمًا في هذا الباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص395–407.","url":""}]},{"id":"s6-124","number":124,"surah":6,"verses":[21],"verseLabel":"الأنعام: 21","question":"ما دلالة الجمع بين ﴿افترى﴾ و﴿كذبًا﴾ في قوله تعالى: ﴿افترى على الله كذبًا﴾؟","answer":"الافتراء هو الكذب المتعمد المختلق، وجاء ﴿كذبًا﴾ مصدرًا مؤكدًا له يصرح بقبح حقيقته ويزيل كل احتمال أن يكون خطأً أو وهمًا. وفي التقارب الاشتقاقي مع ﴿كذّب﴾ بعده إبراز لوجهي الجريمة: اختلاق الباطل وردّ الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص395–407.","url":""}]},{"id":"s6-125","number":125,"surah":6,"verses":[21],"verseLabel":"الأنعام: 21","question":"ما دلالة العطف بـ﴿أو﴾ بين الافتراء على الله والتكذيب بآياته؟","answer":"تفيد ﴿أو﴾ أن كل واحد من الفعلين مستقل في بلوغ غاية الظلم، سواء اختلق المرء على الله باطلًا أم رد آياته الثابتة؛ وقد يجتمعان في شخص واحد، فيجمع بين صناعة الكذب ومحاربة الحق. فهي تمنع توهم أن الحكم لا يثبت إلا باجتماعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص395–407.","url":""}]},{"id":"s6-126","number":126,"surah":6,"verses":[21],"verseLabel":"الأنعام: 21","question":"ما دلالة تعدية التكذيب بالباء في قوله تعالى: ﴿كذب بآياته﴾؟","answer":"الباء تصل فعل التكذيب بالآيات وتصور تلبّس المكذب بإنكارها وملازمته له؛ فكلما واجه آية تصدى لردها وطمس دلالتها. والتعبير بـ﴿آياته﴾ أعم من القرآن وحده، إذ يشمل الآيات الوحيية والكونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص395–407.","url":""}]},{"id":"s6-127","number":127,"surah":6,"verses":[21],"verseLabel":"الأنعام: 21","question":"ما دلالة إظهار وصف ﴿الظالمون﴾ في قوله تعالى: ﴿إنه لا يفلح الظالمون﴾، دون: إنهم لا يفلحون؟","answer":"وضع الاسم الظاهر موضع الضمير ليصرح بعلة نفي الفلاح: ظلمهم نفسه. ولم يقل ﴿الأظلمون﴾ كيلا يُتوهم أن من كان دونهم ظلمًا قد يفلح بظلمه؛ فكل ظلم سبب للحرمان، وأشدّه الافتراء والتكذيب المذكوران.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص395–407.","url":""}]},{"id":"s6-128","number":128,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما دلالة التوكيد بـ﴿جميعًا﴾ في قوله تعالى: ﴿ويوم نحشرهم جميعًا﴾؟","answer":"يؤكد ﴿جميعًا﴾ أن الحشر يستوعبهم فلا يتخلف منهم أحد، ويجمع العابدين وما عبدوه ليقع السؤال والمواجهة على رؤوس الأشهاد. فليس اللفظ حشوًا بعد معنى الحشر، بل تصوير لاجتماعهم الكامل في موقف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-129","number":129,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم نقول للذين أشركوا﴾؟","answer":"تفيد ﴿ثم﴾ التراخي بين الحشر وبين سؤال التقريع؛ فيُجمعون أولًا في هول الموقف، ثم تأتي المواجهة التي تكشف سقوط شركائهم. ويصلح التراخي هنا للزمن ولرتبة ما بعده من شدة التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-130","number":130,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما دلالة وصفهم بالصلة في قوله تعالى: ﴿للذين أشركوا﴾، دون: للمشركين؟","answer":"الصلة تستحضر الفعل الذي صار سببًا للسؤال والعقوبة: هم الذين أحدثوا الشرك وجعلوا لله أندادًا. وفي الفعل الماضي تسجيل للجريمة التي وقعت منهم، تمهيدًا لتبكيتهم على الشركاء الذين زعموهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-131","number":131,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أين شركاؤكم﴾؟","answer":"ليس سؤالًا لطلب علم، بل للتقريع والتعجيز وإظهار أن الذين علقوا بهم الرجاء قد غابوا وعجزوا عن النصرة. فالمشركون يُلزمون بمواجهة الفراغ الذي انتهى إليه اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-132","number":132,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما دلالة إضافة الشركاء إليهم في قوله تعالى: ﴿شركاؤكم﴾؟","answer":"أضيفوا إلى المشركين لأنهم شركاء في زعمهم واختراعهم وحدهم، لا شركاء لله في الحقيقة؛ فالإضافة تتبرأ من إقرار تسميتهم، وتحملهم تبعة ما صنعوه من نسبة الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-133","number":133,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما دلالة حذف معمولي ﴿تزعمون﴾ في قوله تعالى: ﴿الذين كنتم تزعمون﴾؟","answer":"دل السياق على المحذوف: تزعمونهم شركاء أو آلهةً وشفعاء؛ فحُذف اختصارًا وتحقيرًا للدعوى عن أن يعاد تفصيلها، وترك اللفظ يستوعب كل ما كانوا ينسبونه إلى معبوداتهم من أوصاف باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-134","number":134,"surah":6,"verses":[22],"verseLabel":"الأنعام: 22","question":"ما دلالة اختيار فعل ﴿تزعمون﴾ في وصف اعتقادهم في الشركاء؟","answer":"الزعم قول يغلب استعماله فيما لا يقوم عليه برهان ويُتهم صاحبه فيه؛ فسمّى اعتقادهم زعمًا ليكشف أنه دعوى مجردة لا حقيقة لها. واستحضار استمرار زعمهم في الدنيا يزيد سؤال القيامة تقريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص408–418.","url":""}]},{"id":"s6-135","number":135,"surah":6,"verses":[23],"verseLabel":"الأنعام: 23","question":"ما دلالة تسمية جوابهم يوم القيامة ﴿فتنتهم﴾؟","answer":"الفتنة هنا ما انتهى إليه افتتانهم بالشرك من معذرة وجواب مضطرب؛ فلم يجدوا عند الامتحان إلا أن ينكروا ما كانوا عليه. وتسميته فتنتهم تصل مبدأ الضلال في الدنيا بعاقبته الفاضحة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص419–424.","url":""}]},{"id":"s6-136","number":136,"surah":6,"verses":[23],"verseLabel":"الأنعام: 23","question":"ما دلالة القصر في قوله تعالى: ﴿ثم لم تكن فتنتهم إلا أن قالوا﴾؟","answer":"حصر القصر كل ما استطاعوا تقديمه من معذرة في قول واحد هو إنكار شركهم؛ فلم تبق لهم حجة ولا دفاع سوى الكذب. وفي ذلك تصوير لإفلاسهم بعد أن كانوا يجادلون ويزعمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص419–424.","url":""}]},{"id":"s6-137","number":137,"surah":6,"verses":[23],"verseLabel":"الأنعام: 23","question":"ما دلالة قسمهم يوم القيامة: ﴿والله ربنا ما كنا مشركين﴾؟","answer":"يصور القسم شدة اضطرابهم ومحاولتهم النجاة حتى بالكذب بين يدي الله؛ فالعادة التي رسخت فيهم من المكابرة ظهرت في أشد المواقف. وقيل إنهم ينكرون رجاء أن تنالهم مغفرة أهل التوحيد، ثم تشهد عليهم جوارحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص419–424.","url":""}]},{"id":"s6-138","number":138,"surah":6,"verses":[23],"verseLabel":"الأنعام: 23","question":"ما دلالة توسط ﴿ربنا﴾ بين القسم وجوابه في قولهم: ﴿والله ربنا ما كنا مشركين﴾؟","answer":"﴿ربنا﴾ نداء أو وصف لاسم الجلالة يقرّ بأن المقسَم به هو ربهم الذي رباهم ويملك أمرهم؛ فجاء اعتراف الربوبية في قلب إنكار الشرك ليزيد تناقضهم ظهورًا، وفيه محاولة استرحام لا تنفع مع الكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص419–424.","url":""}]},{"id":"s6-139","number":139,"surah":6,"verses":[23],"verseLabel":"الأنعام: 23","question":"ما دلالة قولهم: ﴿ما كنا مشركين﴾، دون: لم نشرك؟","answer":"نفوا عن أنفسهم الوصف الثابت في الزمن الماضي، كأن الشرك لم يكن حالًا لهم قط، وهو إنكار أوسع وأشد من نفي فعل مفرد. لذلك كشف التعبير مقدار افترائهم على أنفسهم حين أنكروا تاريخًا لازمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص419–424.","url":""}]},{"id":"s6-140","number":140,"surah":6,"verses":[24],"verseLabel":"الأنعام: 24","question":"ما دلالة الأمر بالنظر في قوله تعالى: ﴿انظر كيف كذبوا على أنفسهم﴾؟","answer":"الأمر للتعجيب والاعتبار من حالهم، ويوجه النبي ﷺ وكل سامع إلى تأمل هيئة كذبهم وتناقضهم لا إلى مجرد معرفة الخبر. وعُرض مشهد القيامة المستقبل كأنه حاضر يُنظر إليه لتحقق وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص425–431.","url":""}]},{"id":"s6-141","number":141,"surah":6,"verses":[24],"verseLabel":"الأنعام: 24","question":"ما دلالة الاستفهام بـ﴿كيف﴾ في قوله تعالى: ﴿انظر كيف كذبوا﴾؟","answer":"﴿كيف﴾ توجه النظر إلى هيئة الكذب العجيبة وشدته: أقسموا على نفي أمر عاشوه وظهرت حقيقته. فالمقصود التعجب من الكيفية المتناقضة، لا مجرد نقل مضمون ما قالوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص425–431.","url":""}]},{"id":"s6-142","number":142,"surah":6,"verses":[24],"verseLabel":"الأنعام: 24","question":"ما دلالة تعدية الكذب بـ﴿على﴾ في قوله تعالى: ﴿كذبوا على أنفسهم﴾؟","answer":"لأن كذبهم عاد على أنفسهم بالشهادة عليها والإهلاك لها، ولأنهم نسبوا إليها ما تعلم بطلانه من دعوى أنهم لم يكونوا مشركين. فـ﴿على﴾ تحمل معنى الجناية والافتراء الواقع ضرره على صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص425–431.","url":""}]},{"id":"s6-143","number":143,"surah":6,"verses":[24],"verseLabel":"الأنعام: 24","question":"ما دلالة تصوير بطلان معبوداتهم بقوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"صوّر ما اخترعوه كشيء بحثوا عنه فضلّ طريقه وغاب عنهم وقت الحاجة؛ فلا الشركاء حضروا ولا الشفاعة المزعومة نفعت. وفي الفعل مفارقة مؤلمة بين تعلقهم بهم في الدنيا وفقدهم الكامل في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص425–431.","url":""}]},{"id":"s6-144","number":144,"surah":6,"verses":[24],"verseLabel":"الأنعام: 24","question":"ما دلالة التعبير بـ﴿ما كانوا يفترون﴾، دون: شركاؤهم أو آلهتهم؟","answer":"سمّاها بما هي عليه في الحقيقة: افتراء صنعوه، فلم يقر لها باسم الشريك أو الإله إلا على جهة الحكاية عن زعمهم. والموصول يعم المعبودات وما ألحقوه بها من دعوى الشفاعة والنفع والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص425–431.","url":""}]},{"id":"s6-145","number":145,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة الإفراد في قوله تعالى: ﴿ومنهم من يستمع إليك﴾ مع أن المستمعين جماعة؟","answer":"روعي لفظ ﴿من﴾ المفرد، فجاء ﴿يستمع﴾ بالإفراد، مع أن معناها يعم أفرادًا متعددين؛ فجمع التركيب بين إيجاز اللفظ وشمول الحكم. ثم عادت الضمائر جمعًا في ﴿قلوبهم﴾ و﴿آذانهم﴾ مراعاةً للمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-146","number":146,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿يستمع إليك﴾، دون: يستمع إلى القرآن؟","answer":"صوّرهم وهم يقصدون مجلس النبي ﷺ ويسمعون تلاوته منه مباشرة، فتقوم عليهم الحجة بقربهم من المبلّغ والبلاغ معًا. ومع ذلك لم يكن قصدهم الاهتداء، بل انتهى استماعهم إلى المجادلة والطعن في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-147","number":147,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما مناسبة جعل ﴿أكنة﴾ على القلوب و﴿وقرًا﴾ في الآذان؟","answer":"الأكنة أغطية تحجب القلب عن فقه المعنى، والوقر ثقل يصمّ الأذن عن الانتفاع بالمسموع؛ فناسب كل مانع آلته. واجتماعهما يمثل فرط بُعدهم عن الحق: لا السماع الظاهر أوصل، ولا القلب الباطن فقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-148","number":148,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما سرّ جمع ﴿أكنة﴾ وإفراد ﴿وقرًا﴾؟","answer":"جُمعت الأكنة لتعدد القلوب والأغطية التي تحول بينها وبين وجوه فقه القرآن، أما ﴿وقرًا﴾ فمصدر يدل على جنس الثقل الواقع في الآذان، والمصدر يستوي فيه الواحد والكثير. فاختلاف العدد تابع لاختلاف بناء اللفظ ودلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-149","number":149,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة التعبير بـ﴿أن يفقهوه﴾، دون: أن يفهموه؟","answer":"الفقه إدراك دقيق يصل إلى مراد الكلام وما وراء ظاهره، فهو أخص من مطلق الفهم؛ والآية لا تنفي وصول أصوات القرآن إلى آذانهم، بل تنفي نفاذ معانيه وحججه إلى قلوب أصرّت على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-150","number":150,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة قوله تعالى: ﴿وإن يروا كل آية لا يؤمنوا بها﴾؟","answer":"علق عدم إيمانهم على رؤية كل آية ليبين أن العلة ليست نقص الدليل، بل إصرار القلب؛ فلو اجتمعت لهم الآيات كلها لم ينتفعوا بها. وفي ﴿كل﴾ بلوغ بالوصف أقصى درجات المكابرة بعد انسداد السمع والفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-151","number":151,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة تعدية الإيمان بالباء في قوله تعالى: ﴿لا يؤمنوا بها﴾؟","answer":"الباء تعلق الإيمان بالآية تعلق تصديق وقبول واطمئنان، فنفى عنهم الانتفاع بها لا مجرد معرفتها أو رؤيتها. ولهذا صح أن يروا الآيات بأعينهم ثم لا يؤمنوا بها بقلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-152","number":152,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة ﴿حتى﴾ في قوله تعالى: ﴿حتى إذا جاؤوك يجادلونك﴾؟","answer":"جعلت ﴿حتى﴾ مجيئهم للمجادلة غايةً لما قبلها: يستمعون، ولا يفقهون، ولا يؤمنون، ثم ينتهي أمرهم إلى الحضور لا لطلب الحق بل لمخاصمته. فهي تكشف المآل الذي بلغ إليه إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]},{"id":"s6-153","number":153,"surah":6,"verses":[25],"verseLabel":"الأنعام: 25","question":"ما دلالة الجمع بين ﴿جاؤوك﴾ و﴿يجادلونك﴾؟","answer":"يبين الأول حركتهم وقصدهم مجلس النبي ﷺ، ويبين الثاني حالهم وغايتهم عند المجيء؛ فقد حضروا مناظرين معاندين لا مسترشدين. فالجملة الحالية تفضح الباعث الذي حوّل القرب من الوحي إلى خصومة معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص432–450.","url":""}]}]);
